/* Question bank — based on general U.S. rules of the road (common across state DMV handbooks).
   NOTE: answer positions in this file are NOT balanced on purpose — app.js shuffles the
   display order of choices on every render, so users always see a uniform distribution. */
"use strict";

const CATEGORIES = {
  signs:    { name: "Signs & Signals",   icon: "octagon",   desc: "Shapes, colors, and meanings" },
  markings: { name: "Markings & Lanes",  icon: "lanes",     desc: "Lines, arrows, bike and HOV lanes" },
  row:      { name: "Right of Way",      icon: "crossroad", desc: "Who goes first — the #1 fail topic" },
  speed:    { name: "Speed & Distance",  icon: "gauge",     desc: "Limits, safe speeds, following distance" },
  parking:  { name: "Parking & Stopping",icon: "parking",   desc: "Where and how to park safely" },
  alcohol:  { name: "Alcohol & Drugs",   icon: "ban",       desc: "Limits, penalties, and impairment" },
  safety:   { name: "Safety & Emergencies", icon: "shield", desc: "Belts, night driving, crashes, skids" },
  vulnerable:{ name: "People & Riders",  icon: "users",     desc: "Pedestrians, bikes, motorcycles, animals" },
  vehicle:  { name: "Vehicle Basics",    icon: "wrench",    desc: "Checks, tires, ABS, and maintenance" },
  laws:     { name: "Rules & Penalties", icon: "scale",     desc: "Documents, turns, and the law" },
};

const QUESTIONS = [
  { id:"sg01", cat:"signs", form:"recall", signId:"stop",
    q:"What must you do at this sign?",
    choices:["Slow down and roll through if clear","Stop only if another car is present","Come to a COMPLETE stop","Yield without stopping"],
    a:2,
    why:"An eight-sided (octagonal) red sign means come to a full stop — wheels fully stopped — at the stop line, crosswalk, or before entering the intersection. Then yield to traffic and pedestrians and go when safe.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg02", cat:"signs", form:"recall",
    q:"Why is the STOP sign the only eight-sided (octagon) sign?",
    choices:["It was chosen randomly in the 1920s","So it can be recognized even from behind or covered in snow","To match European designs","Because red paint was cheaper"],
    a:1,
    why:"The unique octagon shape lets drivers recognize it from any angle — even the back of the sign — or when snow covers the words. Every octagonal sign means STOP, no exceptions.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg03", cat:"signs", form:"recall", signId:"yield",
    q:"What does this sign require?",
    choices:["Give the right of way to traffic and pedestrians; stop if needed","Always come to a complete stop","Speed up to merge quickly","Wait for a green light"],
    a:0,
    why:"A downward-pointing triangle means YIELD: slow down, give the right of way to cross traffic and pedestrians, and be ready to stop. Unlike a stop sign, you may continue without stopping if the way is genuinely clear.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg04", cat:"signs", form:"recall", signId:"doNotEnter",
    q:"This sign means:",
    choices:["Road closed to pedestrians","No trucks allowed","Exit only","Do not enter this road or ramp"],
    a:3,
    why:"A red circle with a white horizontal bar means DO NOT ENTER. It marks one-way streets, exit ramps, and restricted roads — beyond it you would be driving against traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg05", cat:"signs", form:"recall", signId:"wrongWay",
    q:"You see this sign facing you. What should you do?",
    choices:["Continue carefully","Back up on the shoulder at speed","Pull over, stop, and turn around","Turn on headlights and keep going"],
    a:2,
    why:"WRONG WAY means you are driving against traffic — usually on a freeway ramp. Pull to the side immediately, stop, and turn around. WRONG WAY and DO NOT ENTER signs are often paired.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg06", cat:"signs", form:"recall", signId:"speedLimit",
    q:"A white rectangular sign showing 'SPEED LIMIT 55' means:",
    choices:["You should drive exactly 55 mph","55 mph is the MAXIMUM legal speed in ideal conditions","55 mph is the minimum speed","Trucks must drive 55"],
    a:1,
    why:"Posted limits are maximums for ideal conditions. In rain, fog, snow, or heavy traffic you must slow below the limit — the basic speed law requires a speed reasonable for conditions.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg07", cat:"signs", form:"recall",
    q:"What is the difference between WHITE and YELLOW signs?",
    choices:["White = traffic regulations you must obey; yellow = warnings ahead","White warns, yellow regulates","Yellow marks rest areas","There is no difference"],
    a:0,
    why:"White signs are regulatory — they state the law (speed limits, one way, no parking). Yellow (and orange) signs warn you about conditions ahead. Knowing the color system lets you react even before reading.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg08", cat:"signs", form:"recall", signId:"noUturn",
    q:"This sign tells you:",
    choices:["No left turns","Roundabout ahead","Detour ahead","U-turns are prohibited here"],
    a:3,
    why:"A red circle with a slash over a U-turn arrow prohibits U-turns at that location. Where there is no sign, U-turns are generally legal if you can see clearly and make them safely.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg09", cat:"signs", form:"recall", signId:"oneWay",
    q:"This sign means:",
    choices:["Merging traffic ahead","Passing lane ahead","Traffic flows only in the direction of the arrow","Detour ahead"],
    a:2,
    why:"ONE WAY with an arrow means all traffic on that street moves only in the arrow's direction. Never turn against it — and remember you can only turn onto it in the arrow's direction.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg10", cat:"signs", form:"recall", signId:"railCrossing",
    q:"This round yellow sign means:",
    choices:["Roundabout ahead","A railroad crossing is ahead","Rest area ahead","One-lane bridge ahead"],
    a:1,
    why:"A ROUND yellow sign with a black X and 'RR' warns of a railroad crossing ahead. Slow down, look and listen for trains, and never start across unless you can clear the tracks completely.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg11", cat:"signs", form:"recall",
    q:"When you approach a railroad crossing with flashing red lights and lowered gates, you must:",
    choices:["Stop between 15 and 50 feet from the crossing and wait","Speed up to beat the train","Honk and cross slowly","Stop directly on the tracks"],
    a:0,
    why:"Flashing red lights and gates mean a train is coming. Stop well before the crossing (roughly 15–50 feet back) and wait until the lights stop and the gates rise. Never drive around gates or stop on the tracks.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg12", cat:"signs", form:"recall", signId:"pedCrossing",
    q:"This diamond sign means:",
    choices:["School zone","No walking allowed","Crossroad ahead","Pedestrian crossing ahead"],
    a:3,
    why:"A yellow diamond with a walking figure warns of a pedestrian crossing. Slow down, check the sidewalks, and be prepared to stop — pedestrians have the right of way in the crosswalk.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg13", cat:"signs", form:"recall", signId:"schoolZone",
    q:"A five-sided (pentagon) yellow-green sign means:",
    choices:["A hospital is ahead","A national park entrance","A school zone or school crossing is ahead","A highway cloverleaf"],
    a:2,
    why:"The pentagon shape and fluorescent yellow-green color are reserved for schools. Slow to the posted school speed, watch for children, and obey crossing guards — children are unpredictable near roads.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg14", cat:"signs", form:"recall", signId:"deerCrossing",
    q:"This sign warns that:",
    choices:["Cattle ranch ahead","Wild animals often cross here","Horseback riders only","Zoo entrance ahead"],
    a:1,
    why:"A deer (or other animal) crossing sign marks an area where animals frequently cross, often at dawn and dusk. Slow down and stay alert — animals rarely cross alone; if one appears, more may follow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg15", cat:"signs", form:"recall", signId:"slippery",
    q:"This sign means:",
    choices:["Slippery when wet","Winding road","Washboard surface","Trucks carrying liquids"],
    a:0,
    why:"A car with wavy skid marks means the pavement is unusually slippery when wet — common on bridges, in shade, and on roads with oil buildup. Slow down before curves and avoid sudden braking or steering.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg16", cat:"signs", form:"recall", signId:"merge",
    q:"This sign means:",
    choices:["Lane ends ahead — merge","Two roads cross ahead","Your lane becomes a turn lane","Merging traffic enters your road ahead"],
    a:3,
    why:"Merging traffic (a side arrow joining the main arrow) means vehicles will enter your roadway ahead. Drivers on the through road and merging drivers SHARE the job: adjust speed and open a gap.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg17", cat:"signs", form:"recall", signId:"dividedHighwayBegins",
    q:"This sign means:",
    choices:["The divided highway is ending","Two lanes merge into one","A divided highway begins ahead — keep right of the median","A tunnel is ahead"],
    a:2,
    why:"'Divided highway begins' warns that the road ahead has a median with opposing traffic on the far side. Keep to the RIGHT of the divider and don't cross it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg18", cat:"signs", form:"recall", signId:"twoWayTraffic",
    q:"This sign warns that:",
    choices:["A one-way street begins","Two-way traffic is ahead — oncoming traffic in the other lane","A passing zone begins","The road splits"],
    a:1,
    why:"Opposing up/down arrows mean you are entering (or on) a two-way road. Keep right and only pass where the road is clear and passing is legal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg19", cat:"signs", form:"recall", signId:"roundabout",
    q:"When you see this sign, you should:",
    choices:["Slow down and prepare to yield to traffic already in the circle","Speed up to get through quickly","Stop completely before entering","Enter to the left of the island"],
    a:0,
    why:"A roundabout sign means a circular intersection ahead. Slow down, yield to traffic already circulating, enter to the RIGHT of the central island, travel counterclockwise, and use your turn signal to exit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg20", cat:"signs", form:"recall", signId:"workZone",
    q:"What does an ORANGE sign indicate?",
    choices:["A school area","A detour for trucks only","An evacuation route","A temporary warning — road work or construction zone"],
    a:3,
    why:"Orange is used only for construction and maintenance zones. Slow down, increase following distance, watch for workers and equipment, and obey posted reduced limits — fines are often doubled in work zones.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg21", cat:"signs", form:"recall", signId:"flagger",
    q:"In a work zone, a flagger's instructions:",
    choices:["Are only suggestions","Apply only to trucks","Overrule the zone's signs and signals — but a police officer directing traffic outranks even the flagger","Override everything, including police directions"],
    a:2,
    why:"Authority order: flagger over the work zone's signs/signals/markings; a police officer over everyone. Follow the flagger exactly — they protect both workers and you — unless an officer directs otherwise.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg22", cat:"signs", form:"recall", signId:"hospital",
    q:"A BLUE square sign like this marks:",
    choices:["A parking area","Driver services — here, a hospital","A scenic route","A police station"],
    a:1,
    why:"Blue signs list motorist services: hospitals, gas, food, lodging, rest areas. Green signs give guidance (directions/exits), and brown marks recreation areas.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg23", cat:"signs", form:"recall", signId:"noParking",
    q:"This sign means:",
    choices:["You may not park here","You may park for 5 minutes only","No stopping or standing at any time","Parking for residents only"],
    a:0,
    why:"No PARKING means you can't leave your vehicle, though you may briefly stop to load or unload. 'No Standing' and 'No Stopping' signs are stricter — you may not pause there at all.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg24", cat:"signs", form:"recall", signId:"signalAhead",
    q:"This sign tells you:",
    choices:["A fire station is ahead","A railroad signal is ahead","Street lighting ends","A traffic signal is ahead — be ready to stop"],
    a:3,
    why:"A traffic-signal sign warns of a signal that's hidden by a curve, hill, or trees. Ease off the gas, check behind you, and prepare to stop if the light is changing.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg25", cat:"signs", form:"recall", signId:"stopAhead",
    q:"This sign means:",
    choices:["Stop here","Yield ahead","A stop sign is ahead — begin slowing now","All traffic must turn"],
    a:2,
    why:"A yellow diamond showing a stop sign warns that a STOP sign is ahead, often hard to see. Start braking early rather than making a panic stop at the sign.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg26", cat:"signs", form:"recall", signId:"bikeCrossing",
    q:"This sign means:",
    choices:["Bicycle parking ahead","Bicyclists cross or share the road ahead","No bicycles allowed","Bike repair shop ahead"],
    a:1,
    why:"Watch for riders crossing or sharing the road. Slow down, check blind spots before turning right, and give riders wide, slow clearance when passing — minimum passing distances are set by each state, so pick your state pack for your exact rule.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg27", cat:"signs", form:"recall", signId:"chevron",
    q:"A large chevron sign like this is posted:",
    choices:["On the OUTSIDE of sharp curves","At rest areas","At every railroad crossing","In parking garages"],
    a:0,
    why:"Chevrons mark the outside of a sharp curve, pointing the direction of the bend. Slow down BEFORE the curve, stay in your lane, and avoid braking mid-curve.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg28", cat:"signs", form:"recall", signId:"keepRight",
    q:"This white sign means:",
    choices:["Pass on the right","Right lane ends","Right turn only","Keep right of the island or obstruction ahead"],
    a:3,
    why:"Keep Right (a black arrow bending around a dot) means an island, median, or obstruction is ahead — pass on its right side.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg29", cat:"signs", form:"recall",
    q:"A flashing RED traffic light means:",
    choices:["Proceed with caution without stopping","The light is broken — ignore it","Treat it like a STOP sign — stop fully, then go when safe","Stop and wait for green"],
    a:2,
    why:"A flashing red light = stop sign rules. Come to a complete stop, yield to traffic and pedestrians, then proceed when clear. (A flashing YELLOW just means slow down and proceed with caution.)",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg30", cat:"signs", form:"recall",
    q:"A steady YELLOW traffic light means:",
    choices:["Speed up to clear the intersection","The light is about to turn red — stop if you can do so safely","Stop only if a police officer is present","Yield to pedestrians only"],
    a:1,
    why:"Yellow means the signal is about to turn red. Stop before the intersection if you can do it safely; if you're too close to stop, continue through with care. Never accelerate to 'beat the light.'",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg31", cat:"signs", form:"recall",
    q:"A GREEN traffic light means:",
    choices:["Go if the intersection is clear — still yield to pedestrians and vehicles already in it","You have the right of way over everything","Slow down before entering","Go only if no cars are waiting"],
    a:0,
    why:"Green means go IF the intersection is clear. You must still yield to pedestrians and to any vehicle already in the intersection — and never enter (even on green) if traffic would trap you inside.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg32", cat:"signs", form:"recall",
    q:"A YELLOW light that has been green for a while is often called a 'stale' green. The best action is:",
    choices:["Maintain speed and expect it to stay green","Accelerate to make it through","Stop immediately wherever you are","Cover the brake, check mirrors, and be ready to stop"],
    a:3,
    why:"A 'stale' green (long-lit, or pedestrian signals counting down) may change any moment. Ease off the gas, cover the brake, and check your mirror so you can stop safely if it turns yellow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg33", cat:"signs", form:"recall",
    q:"A solid YELLOW line beside a BROKEN yellow line on your side means:",
    choices:["You may pass any time","Passing is prohibited for everyone","You may pass when safe ONLY if the broken line is on your side","The road is one-way"],
    a:2,
    why:"On two-way roads, a broken yellow line on YOUR side means passing is allowed when safe. If the solid line is on your side, you may not cross it to pass — oncoming traffic may.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg34", cat:"signs", form:"recall",
    q:"A GREEN arrow traffic light means:",
    choices:["Prepare to stop","A protected turn — oncoming traffic is stopped, but still yield to pedestrians","Yield to all traffic first","The signal is out of order"],
    a:1,
    why:"A green arrow is a PROTECTED movement: oncoming traffic faces red. You may turn without yielding to oncoming cars, but you must still yield to pedestrians in the crosswalk.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg35", cat:"signs", form:"recall", signId:"noPassingZone",
    q:"This pennant-shaped sign marks:",
    choices:["The START of a no-passing zone","The end of a passing zone","A passing lane ahead","A recreation area"],
    a:0,
    why:"The yellow pennant is posted on the LEFT side of the road at the beginning of a no-passing zone. Do not cross the center line to pass until the zone ends (solid yellow line or 'pass with care' sign).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw01", cat:"row", form:"recall",
    q:"Two cars reach a 4-way stop at exactly the same time. Who goes first?",
    choices:["The car on the LEFT","Whoever arrived faster","The bigger vehicle","The car on the RIGHT"],
    a:3,
    why:"When two vehicles arrive simultaneously at an all-way stop, the driver on the RIGHT has the right of way. If you're the left car, yield, make eye contact, and proceed after they move.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw02", cat:"row", form:"recall",
    q:"You're turning left at an intersection with a green light (no arrow). Oncoming traffic is going straight. Who has the right of way?",
    choices:["You, because you arrived first","Whoever signals first","The oncoming through traffic","Neither — both must stop"],
    a:2,
    why:"On a plain green ball, a left turn must YIELD to oncoming traffic and pedestrians. Only turn when there's a safe gap — or wait for a green arrow, which protects your turn.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw03", cat:"row", form:"recall",
    q:"You're pulling out of a driveway or parking lot. You must:",
    choices:["Go quickly — traffic will slow for you","Yield to pedestrians on the sidewalk and to all traffic on the road","Honk and pull out","Stop only for cars, not people"],
    a:1,
    why:"Vehicles entering the roadway from a driveway, alley, or parking lot yield to EVERYTHING: pedestrians on the sidewalk first, then all traffic on the road. Sidewalk users always have priority.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw04", cat:"row", form:"recall",
    q:"An emergency vehicle with sirens and flashing lights approaches. You should:",
    choices:["Pull over to the right edge of the road and stop until it passes","Speed up to clear the intersection","Stop exactly where you are, even in an intersection","Follow closely to get through traffic"],
    a:0,
    why:"State laws require you to pull toward the RIGHT edge (or curb), stop, and stay there until the emergency vehicle passes. Don't block an intersection — clear it first if you're in one.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw05", cat:"row", form:"recall",
    q:"A blind pedestrian with a white cane or guide dog steps to the curb. You must:",
    choices:["Honk so they know you're there","Wave them across from your window","Drive around them slowly","Stop completely and yield — don't startle or crowd them"],
    a:3,
    why:"You must stop and yield the full right of way to blind pedestrians (white cane or guide dog). Never honk — the sound can confuse them. Remain stopped until they're safely across.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw06", cat:"row", form:"recall",
    q:"At an uncontrolled intersection (no signs or signals), two cars arrive at the same time:",
    choices:["The faster car goes first","The car going straight goes first","The car on the right goes first","The newer car goes first"],
    a:2,
    why:"Same rule as a 4-way stop: first to arrive goes first; if simultaneous, yield to the vehicle on your RIGHT. Slow down approaching any uncontrolled intersection — never assume the other driver sees you.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw07", cat:"row", form:"recall",
    q:"At a T-intersection, a car on the road that ENDS must yield to:",
    choices:["The car that signals first","The car on the through road","The smaller vehicle","Nobody — it's first come, first served"],
    a:1,
    why:"At a T-intersection, traffic on the terminating road yields to traffic on the continuing (through) road, because through traffic isn't expecting cross traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw08", cat:"row", form:"recall",
    q:"A pedestrian is crossing at a marked crosswalk with no signal. You should:",
    choices:["Yield — stop and let them finish crossing","Honk for them to hurry","Drive around them if there's room","Keep moving; cars have priority"],
    a:0,
    why:"Pedestrians have the right of way in marked and unmarked crosswalks. You must stop and wait — and never pass another vehicle that has stopped for a crosswalk (they may be hiding a person).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw09", cat:"row", form:"recall",
    q:"A school bus with flashing RED lights is stopped on your side of an undivided road. You must:",
    choices:["Pass slowly on the left","Pass if no children are visible","Keep moving — only the bus must stop","Stop, whichever direction you're traveling, until the lights stop"],
    a:3,
    why:"On an UNDIVIDED road, traffic in BOTH directions must stop for a school bus's flashing red lights and stay stopped until they're off (and the stop arm withdraws). Children cross in front of the bus.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw10", cat:"row", form:"recall",
    q:"A school bus with flashing red lights is stopped on the OTHER side of a divided road with a median. You should:",
    choices:["Stop anyway, like all traffic","Back up and take another route","Proceed with caution — only traffic behind the bus must stop","Speed past before children exit"],
    a:2,
    why:"On a divided highway separated by a median (or barrier), only traffic traveling in the same direction as the bus must stop. Still, slow down and watch for children near the road.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw11", cat:"row", form:"recall",
    q:"Entering a roundabout, you must yield to:",
    choices:["Traffic entering after you","Traffic already circulating in the roundabout","Nobody — first in wins","Only large vehicles"],
    a:1,
    why:"Vehicles already IN the roundabout have the right of way. Wait for a gap at the yield line, enter to the right of the island, go counterclockwise, signal, and exit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw12", cat:"row", form:"recall",
    q:"You're merging onto a freeway. Who has the right of way?",
    choices:["Freeway traffic already on the highway","You — freeway traffic must move over","Whichever car is faster","The vehicle in the right lane at all times"],
    a:0,
    why:"Merging traffic yields to highway traffic. Use the acceleration lane to match highway speed, find a gap, and merge smoothly. That said, courtesy (moving over or adjusting speed) prevents collisions.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw13", cat:"row", form:"recall",
    q:"You're backing out of a parking space. You must:",
    choices:["Expect others to stop for you","Back out quickly to claim the lane","Honk continuously while backing","Yield to all traffic and pedestrians"],
    a:3,
    why:"A backing vehicle NEVER has the right of way. Check mirrors and physically look over your shoulder, back slowly, and yield to everyone — pedestrians and moving vehicles.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw14", cat:"row", form:"recall",
    q:"The light is green, but traffic ahead has stopped and you'd be stuck IN the intersection. What should you do?",
    choices:["Enter and wait for traffic to move","Creep forward slowly","Wait behind the crosswalk until you can clear the intersection completely","Enter and turn on hazards"],
    a:2,
    why:"Never enter an intersection you can't clear — this 'blocks the box' and gridlocks cross traffic. Wait at the stop line until there's room to fully cross, even on a green light.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw15", cat:"row", form:"recall",
    q:"You want to turn right across a bike lane at an intersection. You must:",
    choices:["Turn quickly — cyclists must stop","Yield to bicyclists in the bike lane before crossing it","Honk to clear the lane","Use the bike lane as a turning lane early"],
    a:1,
    why:"Cyclists in the bike lane have the right of way. Merge into the lane only after yielding, and always check the blind spot over your right shoulder — a common spot for 'right-hook' crashes.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw16", cat:"row", form:"recall",
    q:"A police, ambulance, or fire vehicle is stopped on the roadside with flashing lights. You should:",
    choices:["Move over a lane away from them if safe, or slow down significantly","Maintain speed and pass closely","Stop completely behind them","Photograph the scene while passing"],
    a:0,
    why:"'Move Over' laws require drivers to change lanes away from stopped emergency vehicles when safely possible; if you can't change lanes, slow down well below the limit. This protects responders and stranded drivers.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw17", cat:"row", form:"recall",
    q:"An oncoming driver at night flashes their headlights at you while your high beams are on. You should:",
    choices:["Flash back to warn them","Turn your lights off","Keep the high beams; they're safer","Switch to low beams — you're probably blinding them"],
    a:3,
    why:"High beams can blind oncoming drivers for hundreds of feet. A flash from oncoming traffic usually means you're dazzling them — switch to low beams promptly.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw18", cat:"row", form:"recall",
    q:"You approach a crosswalk where a pedestrian who is blind is waiting with a guide dog. The signal changes to green for you. You should:",
    choices:["Proceed — your light is green","Creep forward to prompt them","Yield to the pedestrian","Sound your horn lightly"],
    a:2,
    why:"Regardless of the signal, blind pedestrians (white cane or guide dog) always have the absolute right of way. Stop and let them cross fully — never honk or nudge forward.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw19", cat:"row", form:"recall",
    q:"Two vehicles meet on a narrow mountain road where only one can pass. Who yields?",
    choices:["The vehicle going uphill","The vehicle going DOWNHILL","The heavier vehicle","Whoever is local"],
    a:1,
    why:"The driver going UPHILL has the right of way — it's harder to restart on a grade. The downhill vehicle should pull over or back up to a wide spot. (Any vehicle should yield to buses and trucks.)",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp01", cat:"speed", form:"recall",
    q:"The 'basic speed law' says you must:",
    choices:["Never drive faster than is safe for current conditions","Always drive at the posted limit","Drive at least the posted limit","Match the speed of traffic exactly"],
    a:0,
    why:"The basic speed law overrides the posted number: you can be cited for driving the limit in fog, rain, or heavy traffic if it's unsafe. You may also be cited for driving too SLOWLY and obstructing traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp02", cat:"speed", form:"recall",
    q:"In good conditions, your following distance should be at least:",
    choices:["1 second behind the car ahead","2 seconds","Half a car length","3 seconds"],
    a:3,
    why:"Use the 3-second rule: pick a fixed object; when the car ahead passes it, count 'one-thousand-one…' — you should reach it no sooner than 3 seconds. Add time for rain (4s), and snow/ice or night (5–6s+).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp03", cat:"speed", form:"recall",
    q:"When may you legally exceed the posted speed limit to pass a car?",
    choices:["When the other car is going 10 under","Only on freeways","Never","Only during daylight"],
    a:2,
    why:"NEVER exceed the posted limit to pass — the limit applies to every lane at all times, so if the vehicle ahead already travels at it there is nothing legal left to gain.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp04", cat:"speed", form:"recall",
    q:"If you double your speed, your stopping distance becomes roughly:",
    choices:["Twice as long","Four times as long","Three times as long","Unchanged — brakes compensate"],
    a:1,
    why:"FOUR TIMES AS LONG: kinetic energy grows with the SQUARE of speed, so doubling speed multiplies the energy your brakes must dissipate by four — braking distance roughly quadruples, which is why speed dramatically worsens crash severity.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp05", cat:"speed", form:"recall",
    q:"Your car starts to hydroplane. What should you do?",
    choices:["Ease off the accelerator and steer straight","Brake hard immediately","Accelerate to cut through the water","Turn sharply toward the shoulder"],
    a:0,
    why:"Hydroplaning (tires riding on water, losing contact) can start as slow as 35 mph. Don't brake or turn abruptly — ease off the gas, hold the wheel straight, and let the car slow until the tires grip again.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp06", cat:"speed", form:"recall",
    q:"On a freeway entrance ramp, you should:",
    choices:["Slow down before merging","Stop and wait for a huge gap","Merge immediately, regardless of speed","Use the acceleration lane to reach the speed of freeway traffic, then merge into a gap"],
    a:3,
    why:"The safest merge is at (or near) the speed of highway traffic. Use the full acceleration lane, signal, check mirrors and blind spot, then merge smoothly into an available gap.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp07", cat:"speed", form:"recall",
    q:"In heavy fog, the safest approach is to:",
    choices:["Use high beams to see farther","Turn off your lights to reduce glare","Slow down, use LOW beams, and increase following distance","Tailgate so you don't lose the car ahead"],
    a:2,
    why:"High beams reflect off fog and make things WORSE. Slow way down (often well below the limit), use low beams (fog lights if you have them), and never follow taillights closely — that's how fog pileups happen.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp08", cat:"speed", form:"recall",
    q:"Approaching the crest of a hill where you can't see beyond it, you should:",
    choices:["Maintain speed — you have the right of way","Slow down and keep right","Speed up to get over the hill faster","Flash your headlights"],
    a:1,
    why:"Hidden hazards — stalled cars, pedestrians, animals, or a slow vehicle — may be just over the crest. Slow down and stay right so you can stop within the distance you can see.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp09", cat:"speed", form:"recall",
    q:"Driving much slower than the flow of traffic:",
    choices:["Can be illegal and dangerous — it disrupts the traffic flow","Is always the safest choice","Is required in the left lane","Is only illegal for trucks"],
    a:0,
    why:"On highways, driving too slowly is a citation-worthy hazard: it forces evasive lane changes around you. Keep right if you're slower than traffic; on freeways, minimum-limit laws apply.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp10", cat:"speed", form:"recall",
    q:"In a work zone with posted reduced speed limits:",
    choices:["The lower limit applies only when workers are present","The limit is advisory only","You may keep 5 mph over","You must obey the posted work-zone limit — fines are often doubled"],
    a:3,
    why:"Work-zone speed limits are enforceable regulations, often with doubled fines, and in many states they apply whether or not workers are visible. Slow down early — workers may be just beyond equipment.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp11", cat:"speed", form:"recall",
    q:"When following a large truck on a downgrade, you should:",
    choices:["Tailgate to draft behind it","Pass quickly on the shoulder","Increase your following distance substantially","Turn off overdrive"],
    a:2,
    why:"Trucks slow and maneuver unpredictably on hills (they shift and brake heavily), and you need more room to see around them. Add seconds to your following distance downhill and when visibility is blocked.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp12", cat:"speed", form:"recall",
    q:"The speed shown on a yellow curve or ramp advisory sign is:",
    choices:["The legal speed limit for the curve","A RECOMMENDED safe speed for the curve in good conditions","A truck-only limit","The minimum speed"],
    a:1,
    why:"Advisory speeds on yellow signs are engineering recommendations for ideal conditions — not legal limits. But ignoring them in rain or with a top-heavy vehicle is how rollovers and run-off-road crashes happen.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp13", cat:"speed", form:"recall",
    q:"How much distance do you need to pass safely on a two-lane road?",
    choices:["Enough to return without forcing the passed car to brake — often 1/3 mile or more","About 5 seconds of clear road","Whatever feels comfortable","Passing is illegal on two-lane roads"],
    a:0,
    why:"At 55 mph you cover ~80 ft/second; a safe pass needs clear sight distance for the ENTIRE maneuver (accelerate, pass, and return with room). If you'd cut off the passed vehicle or oncoming traffic appears — abort.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp14", cat:"speed", form:"recall",
    q:"Night driving is more dangerous mainly because:",
    choices:["Roads are wetter at night","There is more traffic","Cars are harder to hear","You can see less — reduce speed and increase following distance"],
    a:3,
    why:"Fatality rates are far higher at night due to reduced visibility, fatigue, and more impaired drivers. Slow down so your stopping distance stays within your headlight range, and never out-drive your lights.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk01", cat:"parking", form:"recall",
    q:"Parking facing DOWNHILL with a curb, you should turn your wheels:",
    choices:["Away from the curb (left)","Straight ahead","Toward the curb (right)","It doesn't matter if you use the parking brake"],
    a:2,
    why:"Downhill + curb: turn wheels TOWARD the curb (right) so if brakes fail the car rolls into the curb, not traffic. Set the parking brake and leave the car in low gear (or Park).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk02", cat:"parking", form:"recall",
    q:"Parking facing UPHILL with a curb, you should turn your wheels:",
    choices:["Toward the curb (right)","Away from the curb (left), letting the car roll back slightly to touch it","Straight ahead","Fully lock either direction"],
    a:1,
    why:"Uphill + curb: turn wheels AWAY from the curb and ease back so a tire rests against it — the car rolls OFF the road if it slips. (With NO curb, turn wheels toward the edge of the road both ways.)",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk03", cat:"parking", form:"recall",
    q:"When parallel parked, your wheels should be no more than:",
    choices:["12–18 inches from the curb","6 inches from the curb","3 feet from the curb","Anywhere within the lane"],
    a:0,
    why:"Most states require parallel-parked cars within 12–18 inches of the curb. Practicing curb distance is a common road-test scoring point — and prevents sideswipes by passing traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk04", cat:"parking", form:"recall",
    q:"Which of these is ALWAYS illegal?",
    choices:["Parking on a residential street overnight","Parking facing uphill","Parking without passengers","Double parking (stopping beside a parked car)"],
    a:3,
    why:"Double parking blocks a travel lane and is illegal everywhere. Also always illegal: parking in intersections, crosswalks, sidewalks, bus stops, in front of driveways and fire hydrants, and on bridges/tunnels.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk05", cat:"parking", form:"recall",
    q:"You may never park within how far of a fire hydrant?",
    choices:["5 feet","50 feet","15 feet (or as posted)","100 feet"],
    a:2,
    why:"The common rule is at least 15 feet from a fire hydrant (some states differ slightly). Fire crews needs room to run hoses — blocking a hydrant risks lives and earns a hefty ticket or tow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk06", cat:"parking", form:"recall",
    q:"Before exiting your parked car into traffic, you should:",
    choices:["Open the door slowly and hope for the best","Check mirrors and look over your shoulder for traffic, cyclists, and pedestrians","Push the door open quickly","Exit on the driver's side only, always"],
    a:1,
    why:"'Dooring' a cyclist is dangerous and usually the driver's fault. Check the mirror and blind spot, then open with your far hand (the 'Dutch reach') so your body naturally turns to look.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk07", cat:"parking", form:"recall",
    q:"A curb painted RED typically means:",
    choices:["No stopping, standing, or parking (often fire lanes)","Loading zone only","15-minute parking","Disabled permit parking"],
    a:0,
    why:"Red curb = no stopping at all (commonly fire lanes). Yellow = loading/commercial; white = very brief passenger pickup; blue = disabled permit only; green = limited-time parking.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk08", cat:"parking", form:"recall",
    q:"A curb or sign marked BLUE means:",
    choices:["Police vehicles only","No parking before noon","Electric vehicle charging","Parking only with a disabled person placard or plate"],
    a:3,
    why:"Blue marks accessible parking. Parking there without a valid disability placard/plate brings some of the largest parking fines — and takes the space from someone who needs it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk09", cat:"parking", form:"recall",
    q:"You must stop on the shoulder of a highway at night. What should you do?",
    choices:["Stay in the travel lane with hazards on","Stand behind the car to warn traffic","Turn on hazard lights and pull as far off the road as possible","Turn off all lights to be less noticeable"],
    a:2,
    why:"Pull as far onto the shoulder as possible, turn on hazard flashers, and stay belted inside, well off traffic. Never stand behind or near the car — passing drivers drift toward what they stare at.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk10", cat:"parking", form:"recall",
    q:"When leaving a parallel parking space, you must:",
    choices:["Back out fast to force others to yield","Signal, check traffic and blind spot, and yield to all traffic","Wait for someone to stop and let you out","Use hazards and go"],
    a:1,
    why:"You're entering traffic from a parked position — you have NO right of way. Signal, check mirrors and blind spot, reverse only until visible, then pull out into a safe gap.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk11", cat:"parking", form:"recall",
    q:"It is illegal to park (or stop) in all of these EXCEPT:",
    choices:["In a marked legal parking space along the curb","In a crosswalk","On a crosswalk side of a stopped school bus loading zone","Blocking a driveway"],
    a:0,
    why:"Legal where permitted: curbside spaces without restrictive signs. The others — crosswalks, school loading zones, blocked driveways, intersections, sidewalks, fire hydrants, bus stops — are always illegal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk12", cat:"parking", form:"recall",
    q:"On a one-way street, you may generally park:",
    choices:["Only on the right side, facing the direction of travel","Only during daylight","Facing against traffic on the right","On either side, with wheels facing the curb direction as posted"],
    a:3,
    why:"Many states allow parking on EITHER side of a one-way street (left curb included), as long as the car faces the direction traffic flows on that side. Two-way streets: right side only.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk13", cat:"parking", form:"recall",
    q:"Hill parking (turning the wheels) exists because:",
    choices:["It looks neat","It helps the steering system","If the brakes fail, the car rolls off the road instead of into traffic","It's required only for manual transmissions"],
    a:2,
    why:"Turning the wheels is a mechanical backup: if the parking brake or transmission fails on a grade, the car rolls into the curb or shoulder instead of freewheeling into traffic or a pedestrian.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al01", cat:"alcohol", form:"recall",
    q:"For drivers 21 and over, the general per-se BAC limit is:",
    choices:["0.10%","0.08%","0.05%","0.02%"],
    a:1,
    why:"0.08% BAC is the per-se DUI limit in most U.S. states (some are lower, e.g. 0.05% in Utah). You can also be convicted BELOW the limit if driving is visibly impaired.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al02", cat:"alcohol", form:"recall",
    q:"For drivers UNDER 21, most states enforce:",
    choices:["Zero tolerance — essentially any alcohol (0.01–0.02%) is a violation","The same 0.08% limit","0.05% tolerance","No limit at all"],
    a:0,
    why:"'Zero tolerance' laws set the under-21 limit near zero (typically 0.01–0.02%, which even mouthwash could trip). Under-21 drinkers lose their license quickly — usually on a first offense.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al03", cat:"alcohol", form:"recall",
    q:"What is the ONLY thing that reduces your blood alcohol content?",
    choices:["Coffee","A cold shower","Food and water","Time"],
    a:3,
    why:"Your liver eliminates alcohol at a fixed rate (roughly one standard drink per hour). Coffee, showers, food, and exercise make you FEEL more alert but do NOT lower BAC — only time works.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al04", cat:"alcohol", form:"recall",
    q:"Alcohol FIRST affects which driving ability?",
    choices:["Steering precision","Night vision","Judgment and self-control","Hearing"],
    a:2,
    why:"Judgment and inhibition degrade at BAC levels far below the legal limit — which is why impaired drivers feel 'fine to drive' while their risk has already doubled. Coordination and reaction come next.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al05", cat:"alcohol", form:"recall",
    q:"Which of these contains roughly the SAME amount of alcohol?",
    choices:["A 6-pack of beer and one glass of wine","12 oz beer, 5 oz wine, 1.5 oz of 80-proof spirits","One shot and one bottle of wine","All drinks, regardless of size"],
    a:1,
    why:"One standard drink ≈ 12 oz of 5% beer ≈ 5 oz of 12% wine ≈ 1.5 oz of 40% (80-proof) liquor. Counting 'drinks' only works if you know the standard sizes — a large craft beer can equal 2–3 drinks.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al06", cat:"alcohol", form:"recall",
    q:"Refusing a lawfully requested breath or blood test usually results in:",
    choices:["Automatic license suspension under implied-consent laws","Nothing — you can't be forced","A fine only","A warning"],
    a:0,
    why:"By driving, you've already consented to chemical testing ('implied consent'). Refusal typically triggers automatic license suspension (often longer than a DUI itself) and can be used against you in court.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al07", cat:"alcohol", form:"recall",
    q:"An open container of alcohol in the passenger area of a car is:",
    choices:["Legal if the driver isn't drinking","Legal on private roads only","Legal if the cap is on","Illegal in nearly every state, for drivers AND passengers"],
    a:3,
    why:"Open-container laws prohibit open alcohol in the passenger compartment — even for passengers, even resealed. Carry it in the trunk or a locked glove compartment where state law allows.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al08", cat:"alcohol", form:"recall",
    q:"A first DUI conviction typically brings:",
    choices:["A warning letter","Points only","License suspension, heavy fines, alcohol education, and possible jail","License revocation for life"],
    a:2,
    why:"Even a FIRST DUI commonly means license suspension, thousands in fines and fees, mandatory alcohol classes, probation, possible jail time, and hugely increased insurance costs. Penalties grow fast with repeat offenses.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al09", cat:"alcohol", form:"recall",
    q:"Prescription or over-the-counter medicines:",
    choices:["Never affect driving","Can impair driving — it's illegal to drive while impaired by ANY drug","Are fine if prescribed by a doctor","Only matter for commercial drivers"],
    a:1,
    why:"DUI covers drugs — legal or not. Antihistamines, painkillers, sleep aids, and anxiety meds can cause drowsiness and slow reactions. If the label warns against driving, obey it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al10", cat:"alcohol", form:"recall",
    q:"Marijuana use before driving:",
    choices:["Impairs judgment, coordination, and reaction time — and is illegal","Improves focus","Is legal in all states","Only matters for teen drivers"],
    a:0,
    why:"THC impairs distance judgment, reaction time, and lane tracking. Driving high is a drug-impaired (DUID) offense in every state, and combining cannabis with alcohol multiplies impairment.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al11", cat:"alcohol", form:"recall",
    q:"The safest plan if you'll be drinking is:",
    choices:["Drink only beer","Wait 30 minutes after the last drink","Eat a big meal first","A designated sober driver, rideshare, or public transit — decided BEFORE you go"],
    a:3,
    why:"Decide the safe ride before the first drink, when judgment is intact. Waiting 'a while' or eating doesn't reliably sober anyone up — plans made while impaired fail.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf01", cat:"safety", form:"recall",
    q:"Seat belts must be worn by:",
    choices:["The driver only","The driver and front passengers only","The driver and ALL passengers, front and back","Adults in back only"],
    a:2,
    why:"Most states require belts for everyone in the car. An unbelted rear passenger becomes a projectile that can kill people in the front — and belts cut crash deaths roughly in half.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf02", cat:"safety", form:"recall",
    q:"An airbag deploys. To stay safe, sit at least ___ from the steering wheel and never place a rear-facing child seat in front of one.",
    choices:["4 inches","10 inches","24 inches","40 inches"],
    a:1,
    why:"Keep ~10 inches between your breastbone and the wheel, angled slightly back, hands at 9-and-3. Children under 13 belong in the BACK seat — away from deploying airbags.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf03", cat:"safety", form:"recall",
    q:"You must use headlights:",
    choices:["Sunset to sunrise, and whenever visibility is poor (or wipers are on)","Only at midnight to 5 a.m.","Only on highways","Only when raining"],
    a:0,
    why:"Headlights are required from sunset to sunrise and in rain, fog, snow — many states require them whenever wipers run. Lights aren't just to see: they help others SEE you (and it's the law).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf04", cat:"safety", form:"recall",
    q:"You must dim your high beams when an oncoming vehicle is within about:",
    choices:["100 feet","1,500 feet","You never need to dim them","500 feet"],
    a:3,
    why:"Dim high beams within ~500 feet of an oncoming vehicle and ~300 feet (one car-length x ~30) when following — glare blinds other drivers for seconds after you pass.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf05", cat:"safety", form:"recall",
    q:"Oncoming headlights blind you at night. You should:",
    choices:["Stare at the lights to judge distance","Flash your brights back","Look toward the RIGHT edge of your lane and slow down","Close one eye"],
    a:2,
    why:"Don't stare into oncoming lights — watch the right edge/lane line of your path and reduce speed until your vision recovers. Speed must always match what you can actually see.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf06", cat:"safety", form:"recall",
    q:"Your car begins to SKID (rear slides out). The correct recovery is:",
    choices:["Slam the brakes and hold the wheel straight","Ease off the gas and steer GENTLY where you want to go","Accelerate hard","Yank the parking brake"],
    a:1,
    why:"In a skid, stay off the brake, ease off the gas, and steer smoothly toward your intended path ('steer into the skid' — turn the way the rear is sliding). Over-correcting causes snap spinouts.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf07", cat:"safety", form:"recall",
    q:"Your BRAKES FAIL completely. The correct order of actions is:",
    choices:["Pump the brake pedal, downshift to a low gear, then apply the parking brake gradually","Immediately pull the parking brake at full speed","Turn off the engine","Steer into oncoming traffic to use their momentum"],
    a:0,
    why:"Pump for residual pressure, downshift to engine-brake, then feather the parking brake. Scrape against a curb or guardrail if needed and steer to a safe run-off. Turning the engine off kills power steering and can lock the wheel.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf08", cat:"safety", form:"recall",
    q:"A TIRE BLOWS OUT at speed. You should:",
    choices:["Brake hard immediately","Accelerate to stabilize the car","Swerve to the shoulder instantly","Grip the wheel firmly, ease off the gas, and slow gently before pulling off"],
    a:3,
    why:"A blowout pulls the car hard to one side. Firm grip, foot off the gas, NO hard braking — let the car decelerate, then ease to the shoulder once slow. Braking hard with a blown front tire flips the car.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf09", cat:"safety", form:"recall",
    q:"Your accelerator sticks open. First action:",
    choices:["Turn the key fully off","Brake with the parking brake at speed","Shift to NEUTRAL and brake, then pull over and stop the engine","Keep driving to a mechanic"],
    a:2,
    why:"Neutral disconnects the engine from the wheels — you keep steering and braking while the engine just revs. Then brake, pull off, and shut down. (Don't turn the key fully off at speed: it can lock the steering.)",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf10", cat:"safety", form:"recall",
    q:"Your engine stalls while you're driving. You should:",
    choices:["Slam the brakes","Keep steering (it's harder without power), signal, brake gently, and coast to the side","Turn the wheel sharply","Stop in the travel lane immediately"],
    a:1,
    why:"Steering and brakes still work after a stall — just heavier. Grip firmly, signal, brake smoothly, and steer off the road, then restart with park/neutral. Warn traffic with hazards once stopped.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf11", cat:"safety", form:"recall",
    q:"You're the first at a crash scene with possible injuries. The BEST first action is:",
    choices:["Park safely, protect the scene (hazards/flares), call 911, and aid the injured unless moving them is necessary","Move all injured people out of the cars immediately","Leave to find help","Give injured people water"],
    a:0,
    why:"Protect the scene so no secondary crash occurs, call emergency services, and check the injured. Don't move an injured person unless there's immediate danger (fire, traffic) — movement can worsen spinal injuries.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf12", cat:"safety", form:"recall",
    q:"You hit an unattended parked car. You must:",
    choices:["Drive off if no one saw","Wait 10 minutes then leave","Pay cash to the nearest shop","Leave a note with your name, contact, and insurance info, and report as required by state law"],
    a:3,
    why:"Leaving without notice is hit-and-run — a criminal offense. Leave a visible note with your details (and photograph the damage), then notify police/DMV as your state requires.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf13", cat:"safety", form:"recall",
    q:"Texting while driving:",
    choices:["Is safe at stoplights","Is fine if you type quickly","Is illegal in almost every state and multiplies crash risk many times over","Only matters for new drivers"],
    a:2,
    why:"Sending/reading a text takes your eyes off the road ~5 seconds — at 55 mph that's a football field driven blind. It's banned for all drivers in nearly all states, and it's a leading cause of teen crashes.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf14", cat:"safety", form:"recall",
    q:"Large trucks have big blind spots ('no-zones'). The rule of thumb:",
    choices:["Trucks can see everything from their height","If you can't see the truck's MIRRORS, the driver can't see YOU","Trucks have no blind spots on the right","Following closely eliminates blind spots"],
    a:1,
    why:"Trucks have deep blind spots: up to 20 ft in front, 30 ft behind, and a full lane-width along the right side. If the truck's mirrors don't show you, assume you're invisible — pass promptly, never linger.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf15", cat:"safety", form:"recall",
    q:"The area of your rearview mirrors that hides a motorcycle or small car is handled by:",
    choices:["A head check (glance over the shoulder) before changing lanes","Installing bigger mirrors","Slowing down before every lane change","Honking before changing lanes"],
    a:0,
    why:"Mirrors leave gaps where bikes hide completely. Signal, check mirrors, THEN glance over your shoulder into the blind spot before moving. 'SMOG': Signal, Mirrors, Over-shoulder, Go.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf16", cat:"safety", form:"recall",
    q:"Motorcycles:",
    choices:["Can always stop faster than cars, so tailgating is fine","Must ride on the shoulder","Are only allowed in the left lane","Need a full lane — never share a lane with one, and keep 3–4 seconds back"],
    a:3,
    why:"Motorcycles are entitled to a full lane. Follow at 3–4+ seconds (they can brake very quickly), check blind spots carefully, and remember: 'looked but failed to see' causes most car-motorcycle crashes.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf17", cat:"safety", form:"recall",
    q:"When an oncoming vehicle drifts into your lane at night, you should:",
    choices:["Move onto the shoulder at speed","Speed past on the left","Slow down, move right, honk and flash lights — don't swerve into their lane or off the road","Stop in your lane"],
    a:2,
    why:"Head-on space is precious: brake, hug the right, sound the horn and flash your lights. Never swerve LEFT into their path or off the pavement at speed unless impact is otherwise certain.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf18", cat:"safety", form:"recall",
    q:"A child under about 8 years old should ride:",
    choices:["In the front seat with a belt","In an appropriate child seat or booster, in the BACK seat","On a parent's lap","In a booster in the front with the airbag on"],
    a:1,
    why:"Children need child seats/boosters matched to age, weight, and height — usually in the back seat until at least age 8–12 (when the adult belt fits correctly). Front seats with airbags are dangerous for young children.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf19", cat:"safety", form:"recall",
    q:"Carbon monoxide from your car is dangerous because:",
    choices:["It's odorless and colorless — never run an engine in a closed garage or idle in deep snow","It smells strongly of fuel","It stains the windows","It only affects the driver"],
    a:0,
    why:"CO is invisible and scentless, causing drowsiness then death. Never warm a car in a closed garage, and if idling in deep snow, clear the exhaust pipe — blocked exhausts push CO into the cabin.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf20", cat:"safety", form:"recall",
    q:"You feel drowsy on a long drive. The ONLY real fix is:",
    choices:["Loud music and fresh air","Coffee and a snack","Opening the window","Stop and rest (nap/lodge) — or switch drivers"],
    a:3,
    why:"Micro-sleeps happen no matter how alert you feel. Music, air, and caffeine only mask fatigue briefly. The safe choice is to stop — a 20-minute nap or a night's rest. Driving drowsy impairs like alcohol.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf21", cat:"safety", form:"recall",
    q:"When being tailgated, the safest response is:",
    choices:["Brake-check them to send a message","Speed up beyond the limit","Move right when safe and let them pass","Turn on hazards and slow abruptly"],
    a:2,
    why:"Don't brake-check — that causes the very crash you fear. Increase YOUR following distance (so you can brake gently), then move over and let them by. You never win a road-rage contest; just disengage.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf22", cat:"safety", form:"recall",
    q:"An angry driver antagonizes you (tailgating, gesturing). You should:",
    choices:["Respond so they don't think you're weak","Avoid eye contact, keep distance, and never follow or stop to confront","Speed away at 100 mph","Block them from passing"],
    a:1,
    why:"Disengage completely: distance, no eye contact, no gestures. If pursued, drive to a police station or busy public place — never home. Confrontations escalate unpredictably.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw01", cat:"laws", form:"recall",
    q:"When driving, you must carry:",
    choices:["Your driver's license, and proof of registration and insurance in most states","Your license only — insurance stays at home","Just a photo ID","Nothing, if you memorize your license number"],
    a:0,
    why:"Keep your license on you and the vehicle's registration and insurance proof in the car (paper or electronic where allowed). Failing to produce them at a stop brings fines — and driving uninsured can suspend your license.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw02", cat:"laws", form:"recall",
    q:"You change your address. Most states require you to notify the DMV:",
    choices:["Never","Within 5 years","Only when you buy a new car","Within days (commonly 10–30) of moving"],
    a:3,
    why:"States require prompt address updates (often within 10–30 days) so licenses, notices, and recalls reach you. It's usually a quick online update — and tickets can follow missed notices.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw03", cat:"laws", form:"recall",
    q:"You're in a crash causing injury or major damage. You must:",
    choices:["Exchange info only if the other driver asks","Move on and report next week","Stop, help the injured, exchange information, and report to police as required — leaving is a felony","Pay cash and leave"],
    a:2,
    why:"You MUST stop (leaving = hit-and-run), render aid, exchange license/insurance details, and report crashes with injury or over the damage threshold to police/DMV. Serious-injury hit-and-runs are felonies.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw04", cat:"laws", form:"recall",
    q:"Unless a sign prohibits it, you may turn right on red:",
    choices:["After slowing to 10 mph","After a COMPLETE stop and yielding to pedestrians and cross traffic","Any time, without stopping","Only between 9 a.m. and 5 p.m."],
    a:1,
    why:"Right-on-red (where allowed) still requires a full stop at the line, then yielding to pedestrians and oncoming left-turners. Rolling turns on red are a common — and heavily enforced — ticket.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw05", cat:"laws", form:"recall",
    q:"You must signal before turning or changing lanes:",
    choices:["Continuously for at least the last 100 feet (more on highways)","Only if other cars are nearby","After you begin the turn","Only when a police car is visible"],
    a:0,
    why:"Signal at least 100 feet before turning (300+ feet on fast roads) so others can react. Signaling after braking, or not at all, is both a citation and a crash cause.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw06", cat:"laws", form:"recall",
    q:"Where is a U-turn generally ILLEGAL?",
    choices:["On any residential street","At any stop sign","In every intersection","Near a curve or hill crest where you can't be seen 200 feet ahead, or where signs prohibit it"],
    a:3,
    why:"U-turns are illegal where visibility is blocked (curves, crests), in business districts (unless at an intersection), across double yellow lines, and wherever posted. Otherwise they're legal if safely completed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw07", cat:"laws", form:"recall",
    q:"Crossing a SOLID white line means:",
    choices:["Crossing is always fine","It marks a bike lane's start","Crossing is prohibited (or discouraged) — e.g., lane exits or intersections","It's a pedestrian line"],
    a:2,
    why:"Solid white lines separate lanes where lane changes are prohibited or discouraged (like exit-only gore areas, intersections). Broken white lines = lane changes permitted.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw08", cat:"laws", form:"recall",
    q:"Reckless driving is defined as:",
    choices:["Driving 1 mph over the limit","Driving with willful disregard for the safety of persons or property","Any lane change without a signal","Playing music loudly"],
    a:1,
    why:"Reckless driving — willful disregard for safety (extreme speed, weaving, racing, road-rage maneuvers) — is a serious misdemeanor, often with jail time, and can be charged even without a crash.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw09", cat:"laws", form:"recall",
    q:"Accumulating too many points on your license typically leads to:",
    choices:["Warnings, then suspension/revocation of your license","Nothing — points are just statistics","Cheaper insurance","Automatic vehicle impound"],
    a:0,
    why:"Moving violations add points; enough points in a set period triggers progressive penalties ending in suspension or revocation. Points also raise insurance premiums for years.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw10", cat:"laws", form:"recall",
    q:"HOV (diamond) lanes may be used by:",
    choices:["Any car at night","Electric cars, always, everywhere","Trucks with 2+ axles","Vehicles carrying the posted minimum number of occupants (motorcycles often excepted)"],
    a:3,
    why:"High-Occupancy Vehicle lanes require the posted minimum headcount (usually 2–3) during designated hours. Motorcycles are typically exempt; EVs/placards only where signed. Violations draw big fines.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw11", cat:"laws", form:"recall",
    q:"A police officer signals you to pull over. You should:",
    choices:["Stop instantly in the travel lane","Get out and walk back to the officer","Signal, slow, and pull completely off the road to the right, then stay in the car with hands visible","Keep driving until you feel like it"],
    a:2,
    why:"Signal, ease right fully off the roadway, stop, roll the window down, keep hands on the wheel, and stay in the car unless directed. At night, turn on the dome light. Sudden movements put officers on alert.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw12", cat:"laws", form:"recall",
    q:"If your license is SUSPENDED or revoked, you:",
    choices:["May drive to work only","May not drive at all until reinstated","May drive with a friend in the car","May drive during daylight"],
    a:1,
    why:"You MAY NOT DRIVE AT ALL until your license is reinstated — driving on a suspension/revocation is a fresh offense carrying jail time and longer suspensions. Reinstate first (fees, hearings, sometimes an ignition interlock).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw13", cat:"laws", form:"recall",
    q:"Littering from a vehicle:",
    choices:["Carries fines (often escalated for highway litter), and unsecured loads are illegal","Is harmless for organic waste","Is legal on rural roads","Only applies to cigarettes"],
    a:0,
    why:"Littering fines are steep (many states escalate for highway litter), and a cigarette tossed roadside can spark wildfires. Loads must be secured — flying debris causes real crashes and real felony charges.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw14", cat:"laws", form:"recall",
    q:"Wearing headphones or earbuds in BOTH ears while driving:",
    choices:["Is safe if the volume is low","Is required for hands-free calls","Is only illegal for truckers","Is illegal in most states — you must be able to hear sirens, horns, and trains"],
    a:3,
    why:"Most states ban covering both ears — you need to hear emergency vehicles, horns, and crossing bells. A single earpiece for calls is the common allowance.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw15", cat:"laws", form:"recall",
    q:"Using your phone's GPS while driving:",
    choices:["Is always illegal","Is legal at any speed","Is fine if programmed before you drive; programming it while moving can be cited as distracted driving","Is only legal on highways"],
    a:2,
    why:"Set your destination before moving (or while parked). Touching and programming a device in traffic falls under handheld and distracted-driving laws in most states.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg36", cat:"signs", form:"recall", signId:"hill",
    q:"This sign warns of:",
    choices:["A truck stop ahead","A steep downgrade — slow down and use a low gear","A rest area ahead","A weigh station ahead"],
    a:1,
    why:"The truck-on-grade sign marks a steep hill. Slow BEFORE the crest and shift to a low gear so engine braking holds your speed — riding the brakes downhill overheats them (brake fade).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg37", cat:"signs", form:"recall", signId:"deadEnd",
    q:"This sign means:",
    choices:["The road ahead ends — it doesn't connect through","Detour ahead","No outlet for trucks","Lane ends, merge left"],
    a:0,
    why:"DEAD END means the road terminates without a through connection. Start slowing early and plan your turn-around — don't brake at the last second.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg38", cat:"signs", form:"recall", signId:"softShoulder",
    q:"This sign means:",
    choices:["Construction ahead","A steep drop-off","No parking on the grass","The shoulder is soft (dirt or gravel) — unsafe at speed"],
    a:3,
    why:"A soft shoulder can't support a car at speed — wheels sink and drag you off the road. If you must use it, slow down first, grip the wheel, and return to pavement gently.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg39", cat:"signs", form:"recall", signId:"noLeftTurn",
    q:"This sign means:",
    choices:["No left turns here","Detour to the left","Left turns are prohibited — plan an alternate route","The left lane ends"],
    a:2,
    why:"A slashed left-turn arrow prohibits left turns at that location. Continue and loop around (three rights make a left) instead of risking an illegal turn.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg40", cat:"signs", form:"recall", signId:"schoolCrossing",
    q:"How is a SCHOOL CROSSING sign different from a SCHOOL ZONE sign?",
    choices:["It's blue instead of yellow-green","It marks where children actually cross — slow down and prepare to stop","It applies only to buses","It means the school is closed"],
    a:1,
    why:"The pentagon with children on a crosswalk marks the crossing itself; the walking-figures pentagon warns of the school zone ahead. Never pass cars stopped there — children cross mid-block.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw20", cat:"row", form:"recall",
    q:"Turning LEFT on red (from a one-way street onto a one-way street) is:",
    choices:["Legal in many states unless a sign prohibits it — after a full stop and yielding to everything","Illegal everywhere","Legal only during daylight","Legal only for trucks"],
    a:0,
    why:"Many states allow left-on-red from one one-way onto another, with the same rules as right-on-red: complete stop, yield to traffic and pedestrians. A prohibiting sign always wins.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw21", cat:"row", form:"recall",
    q:"You're turning right at a green light while pedestrians cross your target street. You must:",
    choices:["Turn quickly behind them","Honk so they hurry","Ease into the crosswalk","Wait until they clear your half of the crosswalk (or fully cross, per your state)"],
    a:3,
    why:"Turning traffic yields to pedestrians — even on green. Wait behind the line until they're clear; squeezing past at speed is exactly how 'right-hook' collisions happen.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp15", cat:"speed", form:"recall",
    q:"Total stopping distance is made up of:",
    choices:["Braking distance only","Reaction distance only","Perception distance + reaction distance + braking distance","Two car lengths, always"],
    a:2,
    why:"Total stopping distance = PERCEPTION distance + REACTION distance + BRAKING distance. You travel while you see the hazard, while you react (~1 second ≈ 80 feet at 55 mph), and while the car brakes — at 55 mph the total is longer than a football field.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp16", cat:"speed", form:"recall",
    q:"A following distance of 2 seconds is:",
    choices:["Enough in all conditions","Only a floor for perfect conditions — use 3+ seconds, and double it in rain, night, or behind trucks","The legal maximum","For experienced drivers only"],
    a:1,
    why:"Two seconds is the bare minimum in ideal conditions. Most handbooks teach 3 seconds, adding more for rain (4s), night, and snow or ice (6s+), and whenever following motorcycles and trucks.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al12", cat:"alcohol", form:"recall",
    q:"Which factors actually determine your blood alcohol content (BAC)?",
    choices:["Number of drinks, rate of drinking, body weight, food, and time","Willpower and confidence","Coffee consumed","The kind of music playing"],
    a:0,
    why:"BAC rises with how much and how fast you drink, and falls only with time — roughly one standard drink processed per hour. Body weight and food change your peak; nothing but time lowers it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al13", cat:"alcohol", form:"recall",
    q:"Repeat DUI offenders are commonly required to install:",
    choices:["A speed limiter","A louder horn","Special license plates only","An ignition interlock — a breath test the car must pass before starting"],
    a:3,
    why:"Ignition interlocks are standard for repeat (and increasingly first) DUI offenses, alongside license restrictions, mandatory classes, and fines. Tampering with one is a new offense.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf23", cat:"safety", form:"recall",
    q:"A deer runs onto the road directly ahead. Generally you should:",
    choices:["Swerve hard into the next lane","Accelerate to get past it","Brake firmly and stay in your lane — don't swerve at speed unless hitting a person is the alternative","Turn off your headlights"],
    a:2,
    why:"Brake hard in a straight line and sound the horn. Swerving at speed often causes a worse rollover or head-on crash. If hitting the animal is unavoidable, hold your lane and brake.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf24", cat:"safety", form:"recall",
    q:"After a collision you must exchange:",
    choices:["Only first names","Driver's license, contact and insurance details, and vehicle/plate information — plus help any injured people","A handshake and apology","Nothing if the other driver leaves first"],
    a:1,
    why:"Exchange name, address, license number, insurance, and plate/vehicle details; render aid to the injured; and report as your state requires. Leaving without exchanging is hit-and-run.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk01", cat:"markings", form:"recall",
    q:"A BROKEN (dashed) yellow line beside the centerline on your side means:",
    choices:["You may pass when it's safe","Passing is prohibited","The road is one-way","An emergency lane is ahead"],
    a:0,
    why:"On two-way roads, a broken yellow line on your side means passing is allowed when the way ahead is clear. A solid yellow on your side means passing is prohibited.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk02", cat:"markings", form:"recall",
    q:"DOUBLE solid yellow centerlines mean:",
    choices:["Passing allowed from both directions","A railroad crossing ahead","A reversible lane","No passing from either direction — cross only to turn left where permitted"],
    a:3,
    why:"Double solid yellow lines prohibit passing in either direction. In most states you may cross them only to turn left into a driveway or side road where legal — never to pass.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk03", cat:"markings", form:"recall",
    q:"A SOLID white line between lanes means:",
    choices:["Lane changes are permitted","The lane is ending","Lane changes are discouraged or prohibited — stay in your lane","It marks a bike lane only"],
    a:2,
    why:"Solid white lines separate lanes where changing is prohibited or discouraged — near intersections, exits, and gore areas. Broken white lines mean lane changes are allowed when safe.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk04", cat:"markings", form:"recall",
    q:"What's the difference between YELLOW and WHITE pavement lines?",
    choices:["Yellow separates same-direction traffic; white separates opposing","Yellow separates OPPOSING traffic (and marks the left edge); white separates same-direction traffic","White is only used in construction zones","There is no difference"],
    a:1,
    why:"Yellow lines divide traffic moving in opposite directions and mark the left edge of a one-way road; white lines divide traffic moving the same direction. A yellow edge line is always on your LEFT.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk05", cat:"markings", form:"recall",
    q:"A center lane bounded by a broken yellow line inside a solid yellow line (on both sides) is:",
    choices:["A shared two-way LEFT TURN lane","A passing lane","An HOV lane","A truck lane"],
    a:0,
    why:"That's a center two-way left-turn lane: used by traffic from BOTH directions to prepare left turns (usually limited to ~200–400 feet). Never use it for passing or through travel.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk06", cat:"markings", form:"recall",
    q:"A bike lane (bicycle symbol + solid white line) may be driven in:",
    choices:["Whenever traffic is heavy","For up to 500 feet at any time","If you travel under 25 mph","Only where permitted for turning — after yielding to riders; never for passing or parking"],
    a:3,
    why:"Bike lanes are for bicycles. Cars enter only where signs or markings permit (typically to turn right near an intersection, after yielding to cyclists). Driving or parking in them is illegal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk07", cat:"markings", form:"recall",
    q:"Two parallel white lines crossing the road (or zebra bars) mark:",
    choices:["A speed table","A railroad crossing","A pedestrian crosswalk — yield and never block it","A stop line"],
    a:2,
    why:"Parallel or zebra lines mark a crosswalk. Pedestrians have the right of way there — stop behind the stop line, and never block the crosswalk even in heavy traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk08", cat:"markings", form:"recall",
    q:"The thick solid white line before an intersection shows:",
    choices:["Where pedestrians must wait","Where to stop — stop fully BEFORE it","A merge point","A no-parking zone"],
    a:1,
    why:"The thick white stop line marks where you must stop for signals and signs — behind the line, before the crosswalk, and before entering the intersection.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk09", cat:"markings", form:"recall",
    q:"A painted DIAMOND on the pavement marks:",
    choices:["A restricted HOV (high-occupancy vehicle) lane","A toll lane","A hazard area","A truck climbing lane"],
    a:0,
    why:"The diamond marks HOV lanes, restricted during posted hours to vehicles carrying the minimum posted occupancy (motorcycles and transit are often exempt). Violations draw steep fines.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk10", cat:"markings", form:"recall",
    q:"The diagonally striped area between a through lane and an exit or merge lane (the 'gore') is:",
    choices:["A breakdown lane","A passing zone","An acceleration lane","Never to be driven in — it's a neutral island between merging paths"],
    a:3,
    why:"Gore areas separate merging and diverging lanes. Crossing them — especially a last-second dive to make an exit — is dangerous and illegal. Miss the exit; take the next one.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk11", cat:"markings", form:"recall",
    q:"At a railroad crossing, a crossbuck with a plaque reading '2' means:",
    choices:["A 2 mph zone","Two-way traffic","Two tracks — after one train passes, a second may be hidden behind it","A 2-hour parking limit"],
    a:2,
    why:"The plaque shows the number of tracks. Never start across until you can see along ALL tracks — a second train can be hidden behind the first, in either direction.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk12", cat:"markings", form:"recall",
    q:"A white arrow painted in your lane pointing left means:",
    choices:["Left turns are suggested","You must turn left from that lane","Detour ahead","Trucks only"],
    a:1,
    why:"Pavement arrows control lane use: a straight arrow must go straight, a left arrow must turn left. Pick the right lane BEFORE you enter the intersection.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk13", cat:"markings", form:"recall",
    q:"When is passing on the RIGHT legal?",
    choices:["On roads with multiple same-direction lanes, or when the vehicle ahead is turning left — never via the shoulder","Never","Only on one-way streets","Only in daylight"],
    a:0,
    why:"Passing on the right is legal on multi-lane roads and when the car ahead signals a left turn — done in a proper travel lane. Passing on the shoulder is always illegal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk14", cat:"markings", form:"recall",
    q:"RED raised reflective pavement markers facing you mean:",
    choices:["A fire hydrant is nearby","A snow-chain area","A toll plaza ahead","You're on the wrong side or going against traffic — pull off safely and turn around"],
    a:3,
    why:"Red reflectors are aimed at wrong-way drivers — seeing them usually means you're against traffic (often on a ramp). Yellow markers sit on the left and centerline, white on lane lines, blue marks hydrants.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk15", cat:"markings", form:"recall",
    q:"Your lane ends ahead (converging lines / 'LANE ENDS' sign). You should:",
    choices:["Speed up to get ahead of traffic","Stop at the end of the lane","Merge early when safe — and alternate one car each (zipper) in heavy traffic","Straddle both lanes until someone lets you in"],
    a:2,
    why:"Merge smoothly before the lane runs out. In congestion, alternating at the taper ('zipper merge') keeps traffic moving and prevents last-second cutoffs.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr01", cat:"vulnerable", form:"scenario", concept:"bike-passing-distance",
    q:"You're overtaking a cyclist on a narrow road. The safest universal habit is:",
    choices:["Squeeze past — bikes are narrow","Slow down and pass wide, giving generous clearance; many states set a legal minimum (commonly three feet or more)","Pass as close as possible so they can grab your mirror","Sound the horn and pass at full speed"],
    a:1,
    why:"Wind pressure alone can unseat a rider, so slow down, move over fully when possible, and pass with generous clearance. HOW MUCH clearance is law varies by state (three feet in most, four in Pennsylvania) — select your state pack for your exact figure.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr02", cat:"vulnerable", form:"recall",
    q:"A cyclist hugging the right edge suddenly swerves LEFT toward your lane. Most likely:",
    choices:["They're avoiding a hazard — debris, a drain, or a parked car's opening door","They're turning around","They're challenging you","They lost control"],
    a:0,
    why:"Riders swerve for hazards drivers never see: gravel, potholes, grates, and the 'door zone' beside parked cars. Expect it, ease off the gas, and pass only with real clearance.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr03", cat:"vulnerable", form:"recall",
    q:"A group of cyclists rides ahead of you. You should:",
    choices:["Honk so they single up","Squeeze between them and oncoming traffic","Tailgate until they move over","Pass only when legal, with clear sight distance and room for the WHOLE group — like any slow vehicle"],
    a:3,
    why:"Treat a cycling group as one slow vehicle. Wait for a legal passing zone with room to clear every rider — threading between riders and oncoming traffic is a common fatal mistake.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr04", cat:"vulnerable", form:"recall",
    q:"Two motorcyclists ride side by side in one lane. This means:",
    choices:["You may share their lane too","That lane is twice as wide","You must NEVER ride alongside them — a motorcycle owns its full lane","It's illegal for them"],
    a:2,
    why:"Riders may share a lane with each other, but motor vehicles may never share or 'split' a motorcycle's lane. Change lanes fully to pass — never crowd alongside.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr05", cat:"vulnerable", form:"recall",
    q:"A motorcyclist shifts position within their lane as you approach an intersection. Usually they're:",
    choices:["Showing off","Making themselves visible and avoiding blind spots — look twice before turning","Preparing to race","Signaling you to pass"],
    a:1,
    why:"Riders move within the lane to be seen and to avoid oil, grease, and blind spots. Before turning across traffic, look TWICE — 'looked but failed to see' causes most car-motorcycle crashes.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr06", cat:"vulnerable", form:"recall",
    q:"A motorcycle's turn signal has been blinking for a long stretch. You should:",
    choices:["Wait — many motorcycle signals don't cancel automatically; watch their head and body instead","Assume they'll turn and pull out","Honk to remind them","Ignore all motorcycle signals"],
    a:0,
    why:"Unlike cars, most motorcycle turn signals don't shut off on their own. A blinking signal doesn't guarantee a turn — read the rider's head checks and lean before acting.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr07", cat:"vulnerable", form:"recall",
    q:"Why do so many drivers say they 'never saw' the motorcycle they hit?",
    choices:["Motorcycles are usually speeding","Motorcycles have no lights","They always lane-split","Their narrow profile hides in blind spots and blends into the background — scan intersections twice"],
    a:3,
    why:"Motorcycles are small and easily lost in glare, blind spots, and background clutter — especially at intersections, where most collisions happen. Train your eyes to spot two wheels and a helmet, not just car shapes.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr08", cat:"vulnerable", form:"recall",
    q:"A pedestrian crosses mid-block, against the signal, into your path. You should:",
    choices:["Maintain speed — you have the right of way","Honk and keep going","Slow and yield — right of way never justifies a collision","Swerve into oncoming traffic"],
    a:2,
    why:"Right of way is something you YIELD, not enforce. Whoever is wrong, the person on foot loses every collision — slow, cover the brake, and give them the road.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr09", cat:"vulnerable", form:"recall",
    q:"A ball rolls into the street ahead of you. You should:",
    choices:["Maintain speed — it's just a ball","Slow immediately and cover the brake — expect a child to chase it","Honk to warn","Swerve around it at speed"],
    a:1,
    why:"A rolling ball is often a child a half-second behind it. In residential areas, expect kids to dart from between parked cars without looking — slow down and be ready to stop.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr10", cat:"vulnerable", form:"recall",
    q:"An elderly pedestrian is still crossing when your light turns green. You should:",
    choices:["Wait calmly until they finish — some people need more time","Edge forward to hurry them along","Honk lightly","Drive around behind them"],
    a:0,
    why:"Give every pedestrian the time they need — especially elderly or disabled people using canes and walkers. Never nudge, rev, or honk at someone in a crosswalk.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr11", cat:"vulnerable", form:"recall",
    q:"A crossing guard holds up a STOP paddle, but the traffic signal is green. You must:",
    choices:["Obey the signal only","Obey whichever lets you proceed","Stop only if children are visible","Obey the guard — their directions override signals and signs"],
    a:3,
    why:"Crossing guards direct traffic by legal authority, like flaggers and police: their STOP paddle overrides the signal. Stay stopped until the guard lowers it and clears the crossing.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr12", cat:"vulnerable", form:"recall",
    q:"An e-scooter or e-bike rider is using the bike lane. Treat them:",
    choices:["As a pedestrian","As a motorcycle","Like a bicycle — same rights, same lane, same passing clearance","As a parked object"],
    a:2,
    why:"In most states e-scooters and e-bikes are legally bicycles: same road rights, same lanes, and the same passing-clearance requirements as any other rider. Their riders are less visible and less protected — give extra space.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr13", cat:"vulnerable", form:"recall",
    q:"You approach a horse and rider on a rural road. You should:",
    choices:["Pass quickly to get past","Slow down and pass wide and quiet — no horn, no revving","Honk so the horse knows you're there","Follow closely until they turn off"],
    a:1,
    why:"Horses are flight animals — a horn or a fast pass can panic them and throw the rider. Many states require slowing, a wide berth, or stopping. Pass gently and give the whole lane if you can.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr14", cat:"vulnerable", form:"recall",
    q:"Driving beside a row of parked cars in the city, the safest habit is:",
    choices:["Slow slightly and leave a door-width gap — doors open without warning","Hug the curb to let others pass","Watch only the traffic ahead","Keep your high beams on"],
    a:0,
    why:"The 'door zone' beside parked cars is a constant trap: watch for people inside, reverse lights, and turned front wheels — each predicts a door or a car pulling out. A little space prevents the crash.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh01", cat:"vehicle", form:"recall",
    q:"When should you adjust your seat, mirrors, and steering wheel?",
    choices:["While driving, to save time","Only in rental cars","After the first mile","Before starting the engine — along with fastening your belt"],
    a:3,
    why:"Set your driving position before you move. Fiddling with mirrors at speed takes your eyes off the road, and a bad seat position slows pedal control in emergencies.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh02", cat:"vehicle", form:"recall",
    q:"Can correctly adjusted mirrors eliminate blind spots?",
    choices:["Yes, especially convex mirrors","Yes, on new cars","No — always glance over your shoulder before changing lanes","Only at low speeds"],
    a:2,
    why:"Mirrors minimize but never eliminate blind spots. Signal, check mirrors, then a quick over-the-shoulder check (SMOG: Signal, Mirrors, Over-shoulder, Go) catches what mirrors hide — especially motorcycles.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh03", cat:"vehicle", form:"recall",
    q:"Your car has ABS and you must brake HARD in an emergency. You should:",
    choices:["Pump the brake pedal rapidly","Press hard and KEEP steering — a pulsing pedal is the system working normally","Pull the parking brake","Switch the engine off"],
    a:1,
    why:"With ABS: stomp, stay, steer. Press the pedal hard and steer around the hazard — the vibration and grinding noise mean ABS is preventing lockup. Pumping defeats the system.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh04", cat:"vehicle", form:"recall",
    q:"Where do you find the correct tire pressure for YOUR car?",
    choices:["On the sticker in the driver's door jamb (or in the owner's manual)","On the tire's sidewall","At 32 psi for every car","On the windshield"],
    a:0,
    why:"The door-jamb placard lists the manufacturer's recommended pressures. The sidewall number is the tire's MAXIMUM pressure, not your car's setting. Check monthly, cold, including the spare.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh05", cat:"vehicle", form:"recall",
    q:"The 'penny test' checks:",
    choices:["Brake pad wear","Oil level","Battery charge","Tire tread depth — if you can see all of Lincoln's head, replace the tire"],
    a:3,
    why:"Insert a penny head-down into the groove: seeing all of Lincoln's head means the tread is at or below 2/32 of an inch — legally worn out in most states. Worn tires hydroplane and blow out; many experts replace at 4/32.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh06", cat:"vehicle", form:"recall",
    q:"Your brake pedal suddenly feels spongy or sinks toward the floor. You should:",
    choices:["Pump it and keep driving carefully","Ignore it if the warning light is off","Get the car towed or serviced before driving — the hydraulic system may be failing","Top up any fluid and forget it"],
    a:2,
    why:"A soft or sinking pedal suggests a leak or air in the brake hydraulics — the brakes can fail completely without further warning. Don't drive it; have it serviced or towed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh07", cat:"vehicle", form:"recall",
    q:"The horn should be used:",
    choices:["To greet friends and family","To warn others of immediate danger","To urge slower drivers to move over","Whenever you feel frustrated"],
    a:1,
    why:"Horns exist to prevent collisions — warn a driver drifting into your lane or a pedestrian stepping off a curb. Social or angry honking is illegal in many places and fuels road rage.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh08", cat:"vehicle", form:"recall",
    q:"On a frosty morning you must clear:",
    choices:["ALL windows, mirrors, and lights — full visibility before moving","A peephole on the driver's side","Only the windshield, while driving","Whatever the wipers reach"],
    a:0,
    why:"Driving with blocked windows is illegal and dangerous — you can't check mirrors or blind spots through frost. Scrape everything and let the defroster finish while you buckle up.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh09", cat:"vehicle", form:"recall",
    q:"Loose items inside the passenger compartment:",
    choices:["Are fine on the rear shelf","Only matter in trucks","Are stopped by the airbag","Must be secured — in a crash they strike with many times their weight"],
    a:3,
    why:"In a crash, loose objects keep moving at your pre-crash speed — a phone or water bottle becomes a missile. Use the glovebox and cargo areas, and never place items on the rear shelf or your lap.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh10", cat:"vehicle", form:"recall",
    q:"A backup camera should be used:",
    choices:["Instead of turning your head","Only at night","As an aid — still check mirrors and physically look behind before reversing","Only when parking downhill"],
    a:2,
    why:"Cameras have blind zones at the edges and rear corners and can be blocked by dirt or glare. Use them WITH mirrors and a look back — children and pets hide in every system's gaps.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh11", cat:"vehicle", form:"recall",
    q:"The recommended hand position on the steering wheel is:",
    choices:["12 o'clock only","9 and 3 — balanced control and clear of the airbag's path","10 and 2, always","One hand at the bottom, relaxed"],
    a:1,
    why:"9-and-3 gives smooth, balanced steering and keeps your forearms out of the airbag's deployment path (the older 10-and-2 puts them across it). Turn with push-pull steering rather than crossing hands.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh12", cat:"vehicle", form:"recall",
    q:"Stopped facing uphill in traffic, you should:",
    choices:["Hold the brake until you move — and keep extra space behind the car ahead in case you roll back","Hold the car on the throttle","Roll back a little on purpose","Use the parking brake only, always"],
    a:0,
    why:"Keep your foot on the brake until you're ready to move (or use the handbrake for a manual hill start). A full gap behind you forgives a small roll-back and prevents bumping the car behind.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh13", cat:"vehicle", form:"recall",
    q:"Why keep at least a quarter tank of fuel?",
    choices:["Fuel is cheaper in bulk","The gauge is inaccurate below a quarter","It's required by law","Running dry strands you in emergencies — and a near-empty tank pulls sediment and condensation through the fuel system"],
    a:3,
    why:"A quarter tank is your buffer for detours, winter storms, and emergencies. Regularly running on fumes also feeds the pump sediment and tank condensation — a classic breakdown cause.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh14", cat:"vehicle", form:"recall",
    q:"Your wipers smear and streak in rain. You should:",
    choices:["Drive faster to shed the water","Rely on washer fluid only","Replace the blades before your next trip — worn blades destroy visibility at speed","Turn on your hazards"],
    a:2,
    why:"Streaking blades smear oncoming headlights into glare exactly when you need clear vision. Wipers are cheap and take minutes to swap — replace at the first smear, usually every 6–12 months.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh15", cat:"vehicle", form:"recall",
    q:"One headlight has burned out. You should:",
    choices:["Drive with high beams instead","Replace it promptly — with one light, oncoming drivers misjudge you as a far-away motorcycle","Wait until both fail","Use hazards at night"],
    a:1,
    why:"A single headlight makes you look like a distant motorcycle, so oncoming drivers pull out or turn across you. Replace bulbs promptly and carry a spare — driving with one is illegal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw22", cat:"row", form:"scenario", concept:"junction-priority", scene:"          YOU\n           ↓\n     ──────┼─────\n CAR →   │   BUS ↓\n         │\n    pedestrian",
    q:"You are leaving a parking lot (bottom road) onto the through street. Who must yield?",
    choices:["You — to the car and the bus on the through road","The car, because you are turning","The bus, because it is heaviest","Whoever arrived last"],
    a:0,
    why:"When entering from a driveway, lot or side road you yield to ALL traffic on the through road — vehicle type and arrival order never create priority. Wait for gaps in both directions plus the pedestrian on your path.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw23", cat:"row", form:"scenario", concept:"junction-priority", scene:"      ← CAR A\n   ┌────────┐\n   │ round- │\n   │ about  │\n   └────────┘\n   YOU ↑ (right-hand lane)",
    q:"You approach this roundabout in the right-hand lane intending the first exit. What is required?",
    choices:["Stop completely even when the circle is clear","Enter alongside the car to your left","Signal left before entering","Yield to traffic already circulating from the left, then exit without signalling early"],
    a:3,
    why:"At roundabouts you yield to circulating traffic (it comes from your left where you drive on the right) and never enter beside another vehicle. Signal RIGHT for your first exit after passing the one before it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw24", cat:"row", form:"what-next", concept:"turn-priority", scene:"   YOU ↓ (green light)\n        ║╲\n        ║ ╲  oncoming\n   ▓▓▓▓▓║▓▓╲▓▓▓\n    PEDESTRIAN crossing with walk signal",
    q:"Your light is green and you're turning left across the intersection. The pedestrian crossing has a WALK signal. What happens next?",
    choices:["You complete the turn — green means go","Honk so they hurry","You yield and wait until the pedestrian clears, even if your light turns red","Turn behind them closely"],
    a:2,
    why:"A green light gives permission to ENTER the intersection, not to cross conflicting paths: left-turners yield to oncoming traffic AND pedestrians lawfully in the crosswalk. If your light turns red while they finish, stay put until they clear.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk16", cat:"markings", form:"lane-choice", concept:"lane-selection", scene:"  ║   ║   ║\n  ║ ↰ ║ ↑ ║\n  ╚═══╩═══╝\n   L1  L2  L3   YOU ↑\n   (L1 turn-only arrow, L2 straight arrow, L3 plain)",
    q:"You want to go STRAIGHT through this junction and there's traffic ahead. Which lane may you use?",
    choices:["Only L2 — the straight-arrow lane","L2 or L3 — plain lines allow any movement; arrows lock a lane to its marking","Any lane including L1","Only L3"],
    a:1,
    why:"Arrows painted in a lane confine you to that movement; a lane with only line markings keeps all legal movements. So straight traffic belongs in L2, or L3 if its plain markings allow it — never the turn-only lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk17", cat:"markings", form:"lane-choice", concept:"lane-selection", scene:"  → →  ═══════╗\n              ║ EXIT\n  ← ←  ═══════╝\n  YOUR LANE → approaching gore stripes ▨▨▨",
    q:"You've missed your exit and you're beside the striped gore area. What now?",
    choices:["Continue and take the next exit — diagonal stripes mark an area you must never drive through","Cut across the stripes quickly","Back up along the shoulder","Stop and reverse onto the exit ramp"],
    a:0,
    why:"Diagonal-striped (gore) areas separate traffic streams at exits — driving over or stopping in them causes merge crashes, and reversing on a highway is always prohibited. Miss it? Own the miss: next exit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg41", cat:"signs", form:"sign-combo", signIds:["stop","noUturn"],
    q:"These two signs hang together at an intersection. Combined, they tell you:",
    choices:["Stop, then U-turn if safe","U-turn allowed after stopping","Yield instead of stopping","Stop — and note that U-turns are banned here entirely"],
    a:3,
    why:"Signs apply together: come to a FULL stop as always, and do not attempt a U-turn at this location — the prohibition holds even though a stop gives you time to check.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg42", cat:"signs", form:"sign-combo", signIds:["oneWay","doNotEnter"],
    q:"You meet these signs facing opposite directions at either end of a street. The pair means:",
    choices:["Two-way street ahead","Street closed permanently","ONE WAY — entering against the Do-Not-Enter face would put you head-on into traffic","Trucks only"],
    a:2,
    why:"ONE WAY marks the permitted direction while DO NOT ENTRY faces drivers coming the forbidden way. If you can read DO NOT ENTER facing you, you are already going the wrong way — turn around safely immediately.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf25", cat:"safety", form:"what-next", concept:"following-distance",
    q:"The car ahead passes a mailbox. You count 'one-thousand-one' and reach it. What happens next if they brake hard?",
    choices:["You stop in time comfortably","You likely hit them — at 55 mph one second is roughly 80 feet of travel before braking even starts","Nothing — brakes work instantly","Swerving is automatically safer"],
    a:1,
    why:"Perception plus reaction eats up about one second (~80 feet at 55 mph) BEFORE braking begins. A one-second gap guarantees rear-ending; use three-plus seconds and add more in rain or night.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf26", cat:"safety", form:"scenario", concept:"skid-recovery",
    q:"Mid-corner your rear wheels start sliding outward (oversteer). Sequence the recovery:",
    choices:["Ease off gas, steer smoothly WHERE YOU WANT TO GO, avoid braking until grip returns","Brake hard and steer straight","Accelerate to spin out of it","Pull the handbrake"],
    a:0,
    why:"In a skid, abrupt inputs make it worse: lift off the gas gently and look/steer toward your intended path — the car follows your eyes. Hard braking transfers weight violently and prolongs the slide.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr15", cat:"vulnerable", form:"scenario", concept:"pedestrian-priority", scene:"  SIDEWALK ▓▓▓│▓▓▓\n               │← pedestrian waiting, no crosswalk marked anywhere\n  YOU → (through street)",
    q:"A pedestrian waits at the sidewalk where there is NO crosswalk. You're on the through road. What's the safest legal read?",
    choices:["Pedestrians may not cross — continue at speed","Speed up past the point","Honk to clear the way","Slow and be ready to yield — pedestrians crossing between intersections must still be given room, and predictability protects everyone"],
    a:3,
    why:"Outside marked crossings, pedestrians who step out must generally yield to vehicles — but drivers must exercise due care, slow when visibility is limited, and give them space once they are crossing. Expecting the unexpected is defensive driving.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr16", cat:"vulnerable", form:"prioritisation", concept:"pedestrian-priority",
    q:"Simultaneously: a cyclist wobbles ahead of you, a pedestrian steps off the curb ahead-right, and an oncoming car drifts over the centerline. Rank your response:",
    choices:["Cyclist first — nearest hazard wins","Oncoming car first because it is heaviest","Manage speed and position to create ONE escape buffer covering all three, then address each in order of immediacy","Sound horn continuously and brake late"],
    a:2,
    why:"Good drivers don't pick one hazard — they manage SPACE so every threat has an answer: ease off, add following distance, move within your lane away from the drift. Then handle the most immediate conflict first with room still available.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw17", cat:"laws", form:"recall", concept:"emergency-vehicles",
    q:"An ambulance approaches with siren and flashing lights from behind at a red light. You are first in line. Which sequence is correct AND legal?",
    choices:["Run the red to clear the way","Stay put — running the light is illegal; pull as far right as possible ONLY once you may legally proceed","Reverse onto the sidewalk","Follow the ambulance through"],
    a:1,
    why:"Never break a signal for an emergency vehicle — you become the hazard. Stay stopped at the red, keep the intersection clear, and when your light allows, pull right and stop so the rig can pass. Intersections belong to them once they enter.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw25", cat:"row", form:"diagram", concept:"junction-priority", scene:"        A ↑\n        │      (A going north)\n  C ────┼───→ B\n      YOU ↓\n  All four arrive at the SAME moment.",
    q:"Four-way stop, all four cars arrive simultaneously as drawn. Who goes FIRST?",
    choices:["B — the car on your right","A — through traffic beats turns","You — you are most cautious","C — leftmost yields"],
    a:0,
    why:"When arrival is simultaneous, yield to the car on your RIGHT. B sits to your right, so B proceeds first; the chain continues around (B, then C or A per their rights, and you last among these).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw26", cat:"row", form:"prioritisation", concept:"junction-priority",
    q:"Opposite each other at a four-way stop: you arrived FIRST and will turn RIGHT; the facing car arrived SECOND and will turn LEFT across your path. Correct outcome?",
    choices:["They go first — left turns always yield","Both wait indefinitely","Whoever flashes headlights first","You go first — arrival order wins AND facing right-turn/left-turn can even proceed together safely"],
    a:3,
    why:"First-to-arrive, first-to-go. Bonus geometry: a facing right-turner and left-turner can often execute simultaneously because their paths don't cross — but the arrival rule already settles it here.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw27", cat:"row", form:"scenario", concept:"merge-priority", scene:"  RAMP ↑ (you, accelerating)\n  ══════════════════→\n   HIGHWAY traffic → → →\n   gap opens beside a truck ahead",
    q:"Merging: the highway has a truck closing on the gap ahead of you. Best play?",
    choices:["Stop at the end of the ramp and wait for certainty","Match the truck's speed and squeeze in front","Adjust speed NOW so you enter either ahead of or behind the truck — never alongside it","Stop on the shoulder instead"],
    a:2,
    why:"The ramp exists so you can match highway speed and pick a clean slot. Trucks have huge blind spots — never arrive alongside one. Decide early: take the gap BEFORE it or ease off for the one BEHIND.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk18", cat:"markings", form:"diagram", concept:"lane-selection", scene:"  ┌────────────────┐\n  │ CYCLIST →       │ ← solid green bike lane\n  ├────────────────┤\n  │ YOUR LANE →     │ turning right at corner",
    q:"Turning right across this bike lane as a cyclist approaches in it. Correct sequence?",
    choices:["Turn sharply from your own lane to leave the bike lane untouched","Signal, drift into the bike lane before the corner, then turn — yielding to any cyclist already there","Speed up to beat the cyclist","Stop IN the through lane until the entire block is clear"],
    a:1,
    why:"Right-turners merge INTO the bike lane within ~200 feet of the corner (that's why the line is solid — you cross it deliberately, not casually) and yield to cyclists already riding in it. Cutting across at the last second is the classic right-hook crash.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk19", cat:"markings", form:"what-next", concept:"lane-selection", scene:"  ═══  - - - -  ═══   [two-way left-turn lane: outside lines solid, inside broken] →→\n  You want to turn LEFT mid-block across it.",
    q:"Entering this shared center lane to wait for a gap, what happens next if an oncoming driver is also using it to turn left toward you?",
    choices:["Legal — both enter and pass each other front-bumper to front-bumper","Illegal — only one car may occupy it","You must reverse out","Honk them out of the lane"],
    a:0,
    why:"The two-way left-turn lane exists exactly for this: both directions may enter to await a gap and pass each other within it. Don't travel IN it beyond ~300 feet, and never use it as a passing lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg43", cat:"signs", form:"sign-combo", signIds:["speedLimit","schoolZone"],
    q:"Posted together on this approach: which statement is correct?",
    choices:["The higher limit applies except during school hours","Speed limits are suggestions near schools","Both signs cancel each other","The lower school-zone limit applies whenever the zone is active — children present, lights flashing, or posted hours"],
    a:3,
    why:"When a school zone is active (children present, flashing beacons, or the posted hours), its lower limit overrides the general one — fines usually multiply there too. The general limit resumes past the zone.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg44", cat:"signs", form:"sign-combo", signIds:["slippery","chevron"],
    q:"These appear together before a curve. Read them as one message:",
    choices:["Chevrons mark parking spots","Detour ahead via a winding route","Slippery when wet AND the road bends — slow down BEFORE the curve, keep right","Pass freely — warnings don't apply in daylight"],
    a:2,
    why:"The slippery-highway plaque warns the surface loses grip in rain/ice; chevrons show the curve's direction and sharpness. Together: reduce speed on the STRAIGHT, hold your lane through the bend, never brake mid-curve.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf27", cat:"safety", form:"recall", concept:"following-distance",
    q:"Rain begins. Your THREE-second following gap should now be:",
    choices:["Unchanged — tires handle rain identically","Roughly doubled — wet pavement can double stopping distance, so extend the gap to four-plus seconds","Shortened — spray means you should stay closer to see their line","Zero — hazards replace following distance"],
    a:1,
    why:"Water lengthens braking distance dramatically and hides potholes/paint. Doubling the time-gap restores the same physical safety margin you had on dry pavement — it costs seconds, not minutes.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf28", cat:"safety", form:"what-next", concept:"following-distance",
    q:"Same idea, different angle: when rain starts, which grows FIRST and FASTEST — your braking distance or your reaction distance?",
    choices:["Braking distance — reduced grip stretches how far the car travels once brakes bite; reaction stays ~constant unless visibility also drops","Reaction distance — drivers think slower in rain","Neither changes; only tire grip matters later","Both shrink because everyone slows down"],
    a:0,
    why:"Reaction distance depends mostly on human speed (~1 second regardless). Grip loss attacks BRAKING distance immediately — which is precisely why the FIX is a longer following gap, giving the stretched braking room to fit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr17", cat:"vulnerable", form:"what-next", concept:"pedestrian-priority",
    q:"Step by step: the van in the next lane STOPS at an unmarked intersection. It blocks your view of a child who then steps out crossing. Sequence your best response:",
    choices:["Accelerate past the van's gap — it stopped for nothing","Flash lights and continue at pace","Change lanes away from the van and speed up","Treat any stopped vehicle as a warning: cover the brake, expect the hidden pedestrian, proceed only with a cleared sightline"],
    a:3,
    why:"A stopped vehicle you can't explain is hiding something — most often a pedestrian. Covering the brake kills several meters of reaction distance instantly; creeping with a sightline is what prevents the classic 'multiple-threat' tragedy.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw18", cat:"laws", form:"scenario", concept:"low-visibility",
    q:"Fog rolls in fast: visibility drops to ~100 feet. Order your actions:",
    choices:["① High beams for reach ② maintain speed ③ hazards ON while still driving in-lane","① Stop immediately in-lane ② lights off to preserve battery","① Slow to fit visibility ② low-beams (never highs — they reflect back) ③ if you must stop, pull FULLY off and use hazards off-carriageway","① Follow tail-lights closely for guidance"],
    a:2,
    why:"Fog protocol: speed that matches what you can SEE, low beams (highs bounce glare back), and if stopping becomes necessary, exit the carriageway completely — parked-in-lane cars become the crash. Never chase tail-lights; that's how pileups start.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw19", cat:"laws", form:"scenario", concept:"work-zones",
    q:"Work-zone steps: a flagger waves you forward while the temporary signal across the zone shows RED. Who controls your movement?",
    choices:["The traffic signal — electronics beat humans","The flagger's instructions override the signal; follow the flagger","Whichever was installed most recently","Neither — treat as four-way stop"],
    a:1,
    why:"In active work zones the flagger's directions legally supersede signals and markings — they can see the whole operation. Obey the flagger, expect doubled fines otherwise, and watch for equipment crossing unexpectedly. (A police officer directing traffic outranks even the flagger.)",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ph01", cat:"safety", form:"photo", concept:"low-visibility", scene:"PHOTO: Night, two-lane road. Your headlights catch wet glare ahead. An oncoming truck's high beams bloom. A pedestrian in dark clothing stands at the unmarked crossing, barely visible at the road edge.",
    q:"From this photo, what is the most immediate risk and your best action?",
    choices:["The pedestrian is nearly invisible against glare — ease off, cover brake, and be ready to stop; dim to low beams","The truck will blind you — flash high beams back and hold speed","The wet road means you should accelerate to clear spray","Stop in your lane and turn on hazards"],
    a:0,
    why:"Wet glare + high beams + dark-clothed pedestrian is a classic multiple-threat photo. Reduce speed to match what you CAN see, dim your own highs so you don't blind others, and cover the brake for the near-invisible person. Speed must fit visibility, not the limit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ph02", cat:"row", form:"photo", concept:"junction-priority", scene:"PHOTO: Four-way intersection. Your view: a STOP sign is half-hidden behind a leafy tree branch. A cyclist approaches from the right, also facing a stop.",
    q:"The hidden stop sign is still legally a stop. With the cyclist arriving simultaneously on your right, who goes first?",
    choices:["You, because the sign is obscured","Whoever moves first wins","The larger vehicle","The cyclist on your right — same-time at an all-way stop, yield to the right; an obscured sign still controls you"],
    a:3,
    why:"A sign hidden by foliage legally still applies — you must stop fully and treat it as a normal all-way stop. Same-time arrival = yield to the vehicle on your RIGHT, so the cyclist proceeds and you follow after making eye contact.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ph03", cat:"markings", form:"photo", concept:"lane-selection", scene:"PHOTO: Three lanes ahead. Overhead: left lane shows red X, middle shows yellow diagonal arrow bending right, right lane shows green ↓.",
    q:"Which lane(s) may you use right now?",
    choices:["All lanes — signals are advisory","The middle lane, because diagonal means merge left","Only the right lane under the green arrow; the red X lane is closed and the yellow diagonal means vacate that lane","Any lane except the shoulder"],
    a:2,
    why:"Reversible-lane signals are regulatory: red X = lane closed, yellow diagonal = vacate/merge in its direction, green arrow = open. Never enter or stay in a red-X lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ph04", cat:"vulnerable", form:"photo", concept:"pedestrian-priority", scene:"PHOTO: School parking lot exit. Children cluster near a van. A ball sits in the roadway. Your lane is clear but the van blocks part of the sidewalk view.",
    q:"What does this photo demand before you proceed?",
    choices:["Maintain speed — children are on the sidewalk","Slow to a crawl, cover brake, and expect a child to chase the ball from behind the van","Honk continuously","Swerve into the opposite lane"],
    a:1,
    why:"A ball + children + blocked sightline is the highest-risk photo pattern. Slow and cover the brake — a child often follows a ball within a half-second, emerging from behind the obstruction without looking.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ms01", cat:"safety", form:"multi-step", concept:"hydroplaning", scene:"You are at 55 mph in heavy rain. The steering suddenly feels light and the engine revs slightly.",
    q:"Order the recovery steps:",
    choices:["① Ease off gas → ② Hold wheel straight → ③ Do not brake hard until grip returns","① Brake hard → ② Steer hard left → ③ Accelerate","① Turn on hazards → ② Stop in lane → ③ Reverse","① Swerve to shoulder → ② Brake on shoulder"],
    a:0,
    why:"Hydroplaning = tires on water. Any hard brake or sharp steer prolongs it. Ease off throttle, keep straight, wait for grip to return, then gently brake if needed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ms02", cat:"safety", form:"multi-step", concept:"brake-failure", scene:"You press the brake and the pedal sinks to the floor with no effect. Traffic ahead is stopped.",
    q:"Correct ordered sequence:",
    choices:["① Pull parking brake fully at 50 mph → ② Turn off engine","① Honk and close eyes → ② Steer randomly","① Shift to neutral and coast forever","① Pump pedal rapidly → ② Downshift to low gear → ③ Apply parking brake gradually, steer to escape"],
    a:3,
    why:"Pump for residual pressure, engine-brake by downshifting, then feather the parking brake while steering toward a safe run-off (shoulder, curb, uphill). Cutting the engine kills power assist and can lock the wheel.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ms03", cat:"safety", form:"multi-step", concept:"tire-blowout", scene:"Front left tire blows at highway speed. Car pulls hard left.",
    q:"Correct ordered response:",
    choices:["① Brake hard → ② Swerve right → ③ Stop in travel lane","① Accelerate to restabilize → ② Yank wheel right","① Grip firmly → ② Ease off gas → ③ Steer straight, let speed fall, then ease to shoulder","① Turn off engine → ② Coast"],
    a:2,
    why:"A blowout yanks one side. Firm grip counters the pull, lifting off the gas (not hard braking) lets the car slow with stability before a gentle move to the shoulder.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ms04", cat:"laws", form:"multi-step", concept:"crash-protocol", scene:"You are first to a crash with airbags deployed and fluid on the road. One person is slumped inside.",
    q:"Correct ordered steps:",
    choices:["① Move injured immediately → ② Leave → ③ Find help later","① Park safely off road and protect scene → ② Call 911 → ③ Aid injured without moving them unless danger threatens","① Give water → ② Pull them out by arms","① Direct traffic from the travel lane"],
    a:1,
    why:"Secure the scene first so you don't create a second crash (hazards/flares), summon professionals, then aid without spinal-risk moves unless fire/traffic forces it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw28", cat:"row", form:"diagram", concept:"junction-priority", scene:"        YOU ↓\n          │\n      ────┼────\n CAR →    │\n          │ pedestrian\n    (You and car arrive together)",
    q:"Who has priority and what should you do? (Example from the brief)",
    choices:["Car has priority — you wait for it and the pedestrian to clear","You have priority — wave the car through and go","Pedestrian has no right of way — drive around","Both arrive together so go simultaneously"],
    a:0,
    why:"You face a through street while leaving a minor road: you yield to ALL traffic on the through road plus pedestrians on your path. The diagram tests comprehension, not memorization — yield, make eye contact, go when the conflicting paths are clear.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw29", cat:"row", form:"diagram", concept:"roundabout-priority", scene:"      YOU →  ┐\n             ├──○ roundabout — BUS already circulating\n      CAR →  ┘\n        behind you",
    q:"You are about to enter the roundabout behind the bus already inside. Correct entry?",
    choices:["Enter alongside the bus to keep traffic moving","Stop even though the circle is clear ahead","Enter to the left of the island","Yield to the bus inside, then follow it in without cutting off the car behind you"],
    a:3,
    why:"Traffic inside the circle always has priority. Yield at the line, enter to the right of the island behind the bus, and don't let the car behind you push you into an unsafe gap.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk20", cat:"markings", form:"lane-choice", concept:"lane-selection", scene:"  LEFT LANE: diamond ◇  (HOV 2+)\n  MIDDLE: straight arrow\n  RIGHT: right-turn arrow only\n  YOU: single occupant, want to go straight",
    q:"Which lane is illegal for you right now?",
    choices:["The middle straight lane","The right turn-only lane","The HOV diamond lane — you need 2+ occupants during its hours","Both middle and right"],
    a:2,
    why:"Diamond/HOV lanes require the posted occupancy (often 2–3) during their hours — driving solo there draws a steep fine. Motorcycles and transit are usually exempt; placard EVs only where signed. Pick the middle straight lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk21", cat:"markings", form:"lane-choice", concept:"lane-selection", scene:"  BROKEN white line | SOLID white line\n  YOU ‖ your lane ends with a solid edge ──→ shoulder ▓▓",
    q:"Your solid-edge lane is ending onto a narrow shoulder. What is prohibited?",
    choices:["Crossing the solid edge to the shoulder at speed — stay in lane until a broken section or an exit","Both — solid edges discourage crossing except for emergencies or where signs permit","Using the shoulder as a travel lane anytime","Crossing is always fine"],
    a:1,
    why:"Solid white edges discourage crossing into the shoulder — treat it as a boundary, not a lane. Use the shoulder only for emergencies or where signage/law permits (e.g., disabled vehicle).",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw30", cat:"row", form:"diagram", concept:"merge-priority", scene:"  ACCEL LANE → YOU merging\n  ─────────────────\n  HIGHWAY:  CAR A →  GAP  ← CAR B →",
    q:"Two highway cars leave a single car-length gap. What is the safest merge?",
    choices:["Adjust speed for the gap BEHIND Car B or ahead of Car A — never squeeze a short gap","Force into the gap — they will brake","Stop at the taper","Match Car A's bumper exactly"],
    a:0,
    why:"One car length at highway speed is not a gap — it's a collision. Target the space ahead of the lead car OR behind the trailing car; merging between them with no buffer forces someone to brake hard.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg45", cat:"signs", form:"sign-combo", signIds:["yield","pedCrossing"],
    q:"A YIELD sign with a pedestrian crossing plaque directly below it tells you:",
    choices:["Yield only to cars","The signs cancel each other","Stop for 60 seconds","Yield to pedestrians in the crosswalk before proceeding — the plaque narrows 'traffic' to people on foot here"],
    a:3,
    why:"Supplemental plaques narrow a sign's meaning. Here YIELD is explicitly for pedestrians crossing ahead — stop if needed to let them finish, just as you would for cross traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg46", cat:"signs", form:"sign-combo", signIds:["speedLimit","noPassingZone"],
    q:"You pass a 45-mph limit sign immediately followed by a pennant NO-PASSING. Combined, they mean:",
    choices:["The speed limit cancels the no-passing","Passing is now unlimited","Drive up to 45 where legal, but do not cross the center to pass in this zone at any speed","45 is the minimum"],
    a:2,
    why:"Regulatory signs layer: you may drive up to 45 (conditions permitting) AND you must not pass where the pennant says passing is prohibited — limits never override prohibitions.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf29", cat:"safety", form:"what-next", concept:"hydroplaning", scene:"Heavy rain, cruise control ON at 60 mph. You hit standing water.",
    q:"What happens NEXT if you do nothing?",
    choices:["Cruise will cut throttle and keep you safe","Cruise will try to maintain speed, worsening the skid — you must tap brake or switch it OFF and ease off","Nothing — cruise handles water","Car automatically slows"],
    a:1,
    why:"Cruise doesn't know you're hydroplaning; it will add throttle to hold speed as tires lose grip, prolonging the slide. Cancel cruise immediately in heavy rain and drive with your foot managing speed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr18", cat:"vulnerable", form:"scenario", concept:"pedestrian-priority", scene:"Uncontrolled crosswalk: van in left lane STOPS. Your lane (right) still rolling.",
    q:"The van blocks the view of the crosswalk ahead in your lane. What now?",
    choices:["Stop and do NOT pass the stopped vehicle — it is shielding a crossing pedestrian","Pass the van on the right — its stop doesn't concern you","Honk and go around","Change lanes and accelerate"],
    a:0,
    why:"When a vehicle ahead stops at a crosswalk you must stop and never pass it — it almost always hides a pedestrian stepping out. This 'multiple-threat' crash kills even at low speed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk14", cat:"parking", form:"recall", concept:"curb-distance",
    q:"Maximum distance from the curb when parallel parked (most states):",
    choices:["6 inches","3 feet","As far as two feet is acceptable","12–18 inches"],
    a:3,
    why:"Parallel parking within 12–18 inches is the enforced window (6 inches is too tight for enforcement, 3 feet is a hazard). The alternatives differ by a single digit to force knowing the exact interval.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk15", cat:"parking", form:"recall", concept:"curb-distance",
    q:"Re-phrased: A traffic officer measures your parallel-park gap to the curb. You're legal only if it's:",
    choices:["Exactly at the curb (tires touching)","Up to 2 feet","No more than 12–18 inches — beyond that you risk a ticket and a sideswipe","Up to 3 feet if the street is wide"],
    a:2,
    why:"Same rule, different framing. The curb gap is not aesthetic — beyond 18 inches you block the travel lane and mimic double-parking.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al14", cat:"alcohol", form:"recall", concept:"bac-limits",
    q:"Implied-consent refusal: how much longer is the license suspension compared to a first DUI in many states?",
    choices:["Shorter — refusal is a warning only","Longer — refusal often suspends longer than the DUI itself","About the same as a DUI","No suspension at all"],
    a:1,
    why:"Refusal triggers automatic suspension under implied consent — frequently LONGER than a first 0.08% conviction. The similar phrasing ('same/longer/shorter') tests whether you internalized the paradox: refusing the test punishes more.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al15", cat:"alcohol", form:"recall", concept:"bac-limits",
    q:"Same concept, stricter wording: You politely decline a breath test after an officer lawfully requests one. What happens automatically in most states?",
    choices:["Your license is suspended automatically — even if you were ultimately under the limit","Nothing legally","Only a $10 fine","Only points, no suspension"],
    a:0,
    why:"Implied consent means the request itself creates the suspension trigger. Intent doesn't matter — the system treats refusal as an independent violation, often 6–12 months even on a first refusal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk22", cat:"markings", form:"lane-choice", concept:"two-way-left-turn",
    q:"You wait in the center two-way left-turn lane. An oncoming car enters from the opposite direction to wait too. Who goes first?",
    choices:["The car facing north always goes first","Neither may use it — it's one-direction only","You must reverse out","The first to arrive proceeds first; both may legally share the lane waiting"],
    a:3,
    why:"The shared center lane explicitly allows both directions to use it simultaneously to stage left turns — you pass each other nose-to-nose, then complete your turns when gaps appear. Don't travel along it more than ~300 feet.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk23", cat:"markings", form:"what-next", concept:"gore-area",
    q:"What happens NEXT if you cut across the striped gore to catch your missed exit?",
    choices:["You safely make it","You get extra following distance","Tires hit raised markers or you collide with a merging vehicle — gores separate conflicting paths and are illegal to cross","Nothing — gores are just paint"],
    a:2,
    why:"Gores use raised dots/bars plus diagonal paint to create a neutral island. Crossing them last-second puts you 90° to traffic and surprises drivers behind barriers — take the next exit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf30", cat:"safety", form:"recall", concept:"following-distance",
    q:"Three seconds at 55 mph is roughly how many feet BEFORE braking even starts?",
    choices:["About 80 feet — one second of travel","About 240 feet — three seconds of travel before your foot ever hits the brake","About 10 feet","About 500 feet"],
    a:1,
    why:"At 55 mph you travel ~80 ft/second. Reaction (≈1 s) eats 80 ft; braking distance then adds hundreds more. That's why 1 second is a rear-end guarantee — the 3-second rule restores the braking room.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf31", cat:"safety", form:"recall", concept:"following-distance",
    q:"Reframed: Why does rain demand a larger gap than dry conditions, even if you keep the SAME speed?",
    choices:["Because braking distance grows far faster than reaction distance when grip drops — the gap buys the stretched braking room","Because you see worse only","Because the car gets heavier","Because headlights dim in rain"],
    a:0,
    why:"Reaction distance depends mostly on human speed (~1 second). Grip loss attacks BRAKING distance immediately — which is precisely why the FIX is a longer gap, giving the stretched braking room to fit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw31", cat:"row", form:"diagram", concept:"junction-priority", scene:"     YOU ↑\n      │  (stop sign)\n  ────┼────\n CAR →│  CAR B\n      pedestrian crossing",
    q:"You and the car to your left arrive together at this cross-intersection with a pedestrian starting to cross your exit. Order?",
    choices:["Car on left goes first — left has priority","You go first — straight beats turn","Go together","Pedestrian first, then you, then the left car — crosswalk always wins"],
    a:3,
    why:"Crosswalk users win regardless of vehicle order: stop for the pedestrian first, then resolve the vehicle tie by 'yield to the right' — you are to the right of the left car.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw32", cat:"row", form:"diagram", concept:"roundabout-priority", scene:"  YOU →   ◯   CAR A already inside\n          ◯   CAR B entering from opposite side",
    q:"Two circulating vehicles and you outside. Who do you yield to?",
    choices:["Only the car directly ahead","Only large vehicles","Every vehicle already in the circle, regardless of entry point","No one — enter immediately"],
    a:2,
    why:"Roundabout rule is absolute: traffic inside has priority over entering traffic at every entry. The opposite-entering car's later arrival is irrelevant.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw33", cat:"row", form:"scenario", concept:"junction-priority", scene:"Uncontrolled T: YOU on stem, CAR on through road left, BUS on through road right, all at 25 mph",
    q:"Who must yield here?",
    choices:["The bus, because it is heaviest","You alone — stem yields to through road","The car on the left","All must stop"],
    a:1,
    why:"At an uncontrolled T, the terminating road yields to the through road. Size and direction of through traffic do not matter.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk24", cat:"markings", form:"lane-choice", concept:"lane-selection", scene:"  LEFT LANE: diamond ◇  (HOV 2+)\n  MIDDLE: straight arrow\n  RIGHT: right-turn arrow only\n  YOU: single occupant, want to go straight",
    q:"Driving solo, which lane is forbidden at this junction?",
    choices:["The HOV diamond lane — you need 2+ occupants during its hours","The middle straight lane","The right turn-only lane","Both middle and right"],
    a:0,
    why:"Diamond/HOV lanes require the posted occupancy (often 2–3) during their hours — driving solo there draws a steep fine. Motorcycles and transit are usually exempt; placard EVs only where signed. Pick the middle straight lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk25", cat:"markings", form:"lane-choice", concept:"lane-selection", scene:"  Solid white | Broken white  YOU ||  bike lane green ▓▓ on right, cyclist ahead in it",
    q:"You need to turn right in 100 feet. When may you enter the bike lane?",
    choices:["Immediately — bike lanes are shared","Never — stay in your lane and cut across at the corner","Only if no cyclist is visible for a mile","Only within ~200 ft of the turn after yielding to cyclists, not earlier"],
    a:3,
    why:"Bike lanes are exclusive except near turns: merge into them only within the final block (~200 ft) and only after yielding to riders already there.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk26", cat:"markings", form:"lane-choice", concept:"two-way-left-turn", scene:"  Center lane: ══  - - - -  ══  (shared two-way left-turn)\n  YOU want to turn left mid-block; oncoming TRUCK also wants left",
    q:"Both you and oncoming truck enter the shared center turn lane. Correct?",
    choices:["Illegal — one must wait outside","You must reverse out for the truck","Legal — both may occupy it to stage turns, pass nose-to-nose","Only trucks may use it"],
    a:2,
    why:"The two-way left-turn lane is intentionally shared: both directions enter to wait for a gap and slide past each other. Limit travel within it to ~300 ft.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg47", cat:"signs", form:"sign-combo", concept:"sign-combo-recognition", signIds:["yield","bikeCrossing"],
    q:"Yield sign with a bike-crossing plaque below it tells you:",
    choices:["Yield only to cars","Yield to bicyclists crossing here — the plaque specifies who to yield to","Bikes must yield to you","No bikes allowed"],
    a:1,
    why:"Supplemental plaques narrow who/what to yield to. Here it's bicyclists at this crossing, not just cross traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg48", cat:"signs", form:"sign-combo", concept:"sign-combo-recognition", signIds:["stop","schoolCrossing"],
    q:"Stop sign + school crossing plaque together mean:",
    choices:["Stop and remain stopped while children are crossing — school route, not a generic stop","Stop at any time","Stop only when children are visible, otherwise roll","Yield instead of stop"],
    a:0,
    why:"The plaque adds context: this stop protects a school crossing. Expect children even outside school hours and be ready to wait longer than a normal stop.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg49", cat:"signs", form:"sign-combo", concept:"sign-color", signIds:["workZone","chevron"],
    q:"Orange diamond + chevron together before a curve in a work zone mean:",
    choices:["Detour to parking","Lane ends, merge left","No curve — orange cancels chevrons","Construction curve ahead — slow before the bend and follow chevrons through"],
    a:3,
    why:"Orange tells you it's a temporary work-zone curve; chevrons mark the outside of the bend. Together: temporary sharp curve, reduce speed on the straight.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg50", cat:"signs", form:"sign-combo", concept:"sign-shape", signIds:["railCrossing","stopAhead"],
    q:"Round yellow RR sign followed 500 ft later by yellow diamond STOP AHEAD means:",
    choices:["Railroad and stop are the same location","The stop ahead cancels the crossing","Two separate warnings: crossing ahead, then a stop-controlled crossing — prepare to stop well before the tracks","No action needed"],
    a:2,
    why:"Layered warnings: the round sign announces the crossing itself; STOP AHEAD warns that stop-controlled crossing requires a full stop 15-50 ft before tracks, not a rolling yield.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ph05", cat:"safety", form:"photo", concept:"low-visibility", scene:"PHOTO: Daylight, 4-lane highway. Sun low behind you creates long shadows into the opposite lane. A motorcycle approaches in glare, hard to see.",
    q:"What should you do when deciding to pass here?",
    choices:["Pass quickly — sun behind you helps","Wait — glare hides oncoming motorcycles; if you cannot see clearly, do not pass and dim glare with visor","Use high beams to be seen","Pass on the shoulder"],
    a:1,
    why:"Low sun washes out the road ahead. Motorcycles vanish in glare. If you cannot confirm the opposite lane is clear, hold your lane — glare is a hard visibility limit, not a suggestion.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ph06", cat:"markings", form:"photo", concept:"lane-selection", scene:"PHOTO: Your lane shows a straight + right-turn arrow combined. The next lane shows only a straight arrow. You want to turn right.",
    q:"Where may you turn right?",
    choices:["Only your lane, which explicitly allows straight OR right","Either lane — arrows are suggestions","Only the next lane","Neither lane — U-turn only"],
    a:0,
    why:"Lane-use arrows are mandatory: your lane's combined straight/right arrow permits the turn; the neighbor's straight-only arrow forbids it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf32", cat:"safety", form:"what-next", concept:"following-distance", scene:"You are 2 seconds behind a car at 60 mph. Its brake lights flash briefly then go off.",
    q:"What should you do NEXT in this moment?",
    choices:["Close the gap — they braked for no reason","Accelerate to pass","Sound horn","Ease off gas and add space immediately — an early brake tap often precedes hard braking"],
    a:3,
    why:"A tap often signals traffic ahead or a hazard you cannot yet see. Adding space now prevents a panic stop later and costs you less than a second.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr19", cat:"vulnerable", form:"what-next", concept:"pedestrian-priority", scene:"Bus stopped ahead in your lane, doors open, children stepping off to the right. Oncoming traffic is still moving.",
    q:"What do you expect NEXT?",
    choices:["Children will stay on sidewalk","Bus will back up","Children may cross in front of the bus without looking — be ready to stop even though you are oncoming","Nothing — bus blocks their path"],
    a:2,
    why:"Children often cross immediately after exiting, sometimes not at a crosswalk and without scanning. The bus's stop arm legally requires you to stop regardless of direction on undivided roads.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw20", cat:"laws", form:"prioritisation", concept:"move-over",
    q:"Rank by what you should do FIRST when approaching a stopped emergency vehicle with lights: 1) Check mirror 2) Move over 3) Slow if you cannot move",
    choices:["3 → 2 → 1","1 → 2, and only 3 if 2 is unsafe","2 → 3 → 1","3 → 1 → 2"],
    a:1,
    why:"Sequence matters more than speed here: look at the mirrors FIRST, move the vehicle away from the emergency lane when it is safe to do so, and only drop speed when staying in lane is the better option. Slowing before moving can cause the rear-end crash you are trying to avoid.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw34", cat:"row", form:"prioritisation", concept:"junction-priority", scene:"Three hazards at once: 1) pedestrian crossing ahead, 2) ambulance siren behind, 3) car running red from left",
    q:"Prioritise your actions:",
    choices:["Handle pedestrian first — they are most vulnerable, then clear for ambulance, then avoid red-runner","Chase the red-runner to warn","Pedestrian, ambulance, red-runner — in that order","Ambulance first, pedestrian second"],
    a:0,
    why:"Prioritisation drill: avoid the unavoidable collision first (red-runner), manage speed/space for vulnerable user second, then make way for emergency vehicle once safe. Good drivers keep one escape buffer for all three.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ms05", cat:"safety", form:"multi-step", concept:"hydroplaning", scene:"Multi-step: Rain has just started after a dry spell. Oil film floats. You are at 50 mph.",
    q:"Correct 4-step sequence:",
    choices:["① 60 mph → ② High beams → ③ Cruise on → ④ Brake late","① Speed up to clear water → ② Swerve → ③ Stop in lane","① Same speed → ② Sharp steer → ③ Hard brake","① Ease to safe speed before the curve → ② Gentle inputs → ③ Increase following to 4+ sec → ④ Cancel cruise"],
    a:3,
    why:"First rain is slickest: reduce speed BEFORE the risk, be smooth, double the gap, and drive without cruise so your foot controls traction.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ms06", cat:"laws", form:"multi-step", concept:"crash-protocol", scene:"Multi-step: You witness a minor two-car crash blocking the right lane. No injuries obvious.",
    q:"Best order:",
    choices:["① Drag injured out → ② Leave quickly","① Film it → ② Post online","① Park past scene off road → ② Hazards → ③ Call 911 if needed → ④ Exchange help, don't move injured","① Stop in travel lane indefinitely"],
    a:2,
    why:"Protect the scene (off-road parking, hazards), summon help, then exchange/aid without harmful moves. Parking in the travel lane creates a second crash.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al16", cat:"alcohol", form:"recall", concept:"bac-limits",
    q:"Same BAC limit, different angle: A 150-lb driver has two 12-oz beers in one hour on an empty stomach. Their BAC will most likely:",
    choices:["Be 0.00% — beer is weak","Be measurable and possibly near or over 0.02–0.04%, depending on weight and time — food and time are the only moderators","Be exactly 0.08%","Be 0.15% immediately"],
    a:1,
    why:"Two standard beers on an empty stomach measurably raise BAC; weight and elapsed time determine the peak. No trick lowers it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp17", cat:"speed", form:"recall", concept:"speed-limits",
    q:"Unposted residential street, no signs, you drive 30 mph. Legally:",
    choices:["Likely illegal — 25 mph is the default residential limit where unposted","Always legal — 30 is safe","Legal only at night","Legal only with hazards on"],
    a:0,
    why:"Without signage, the 25-mph residential default applies in most states — even if 30 feels slow. Signage only raises it where posted.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp18", cat:"speed", form:"recall", concept:"speed-limits",
    q:"Rephrased: You see no speed sign on a neighborhood street. What speed keeps you unquestionably safe from a citation?",
    choices:["30 mph","40 mph","55 mph","25 mph"],
    a:3,
    why:"Same default-limit concept, tested via recognition rather than recall. When uncertain, 25 mph protects you in residential areas.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk27", cat:"markings", form:"lane-choice", concept:"lane-selection", scene:"  LEFT: HOV ◆◆ (2+)   |   MIDDLE: ↑ straight arrow   |   RIGHT: ↺ U-turn only\n  YOU have 1 passenger and need to go straight.",
    q:"Which lane may you legally use to go straight?",
    choices:["Left HOV lane","Right U-turn-only lane","Middle straight-arrow lane","Any lane"],
    a:2,
    why:"HOV requires 2+ occupants; the right lane is reserved for U-turns. With one passenger going straight, only the middle straight-arrow lane serves you.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk28", cat:"markings", form:"diagram", concept:"lane-selection", scene:'  ┌ ONLY —   YOUR LANE shows "ONLY" plus a straight arrow ahead.',
    q:'The word ONLY painted in your lane means:',
    choices:["The lane is closed","You must make the indicated movement — other movements from this lane are illegal","It is a suggestion","You must stop"],
    a:1,
    why:"Painted ONLY turns the arrow into a mandate: this lane serves that movement exclusively. Move over early if you need a different direction.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg51", cat:"signs", form:"sign-combo", concept:"sign-combo-recognition", signIds:["yield","schoolZone"],
    q:"A YIELD sign posted with a school-zone plaque means:",
    choices:["Yield for school traffic — slow and give way to children crossing","Yield only to buses","No stopping at any time","School is closed"],
    a:0,
    why:"Together they mark a school crossing where you must slow, prepare to stop fully, and give way to children and crossing guards rather than merely rolling through.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg52", cat:"signs", form:"sign-combo", concept:"sign-color", signIds:["oneWay","keepRight"],
    q:"ONE WAY paired with KEEP RIGHT at a divided start tells you:",
    choices:["Go either side of the island","Left of the island is fine if clear","The road ends","Stay right of the divider and follow the one-way direction"],
    a:3,
    why:"KEEP RIGHT directs you around the island's right side; ONE WAY confirms the street beyond flows that direction. Together: keep right and continue one-way.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg53", cat:"signs", form:"sign-combo", concept:"sign-shape", signIds:["pedCrossing","schoolZone"],
    q:"A yellow diamond pedestrian sign with a yellow-green school pentagon warns:",
    choices:["A playground only","No walking permitted","Pedestrians and school children share this corridor — scan for both","School buses only"],
    a:2,
    why:"One diamond flags general pedestrian crossings; the fluorescent pentagon flags a school area. Combined, this corridor demands heightened scanning for people of all ages, especially near arrival/dismissal times.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw35", cat:"row", form:"diagram", concept:"junction-priority",
    scene:"        N (walk signal ON)\n        │ ped crossing\n  W ─────┼───── E\n        │\n      YOU from S, going straight on green",
    q:"You're proceeding straight on green while the pedestrian crosses the north side with the walk signal. Who yields?",
    choices:["The pedestrian must wait for cars","You — the pedestrian in the crosswalk has priority","Whoever is faster","Both proceed together"],
    a:1,
    why:"Green gives you the right to enter, not to cross a lawfully occupied crosswalk: straight traffic yields to pedestrians already crossing, even on green. Wait until they clear your path.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw36", cat:"row", form:"diagram", concept:"roundabout-priority",
    scene:"  YOU at the yield line\n     — truck already circulating, car behind you honks",
    q:"The car behind honks for you to enter the roundabout. What do you do?",
    choices:["Wait for a safe gap behind the truck — honking doesn't create priority","Enter to avoid blocking","Enter alongside the truck","Reverse off the yield line"],
    a:0,
    why:"Circulating traffic has priority and a horn grants nothing — trucks especially hide whole cars beside them. Hold at the line until a genuinely safe gap appears; pressure never changes the rules.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ph07", cat:"safety", form:"photo", concept:"low-visibility",
    scene:"PHOTO: dusk, residential. A ball rolls into the road; a parked van blocks the sidewalk view; small feet visible under the van.",
    q:"What's the 'what happens next' read of this photo?",
    choices:["Child stays behind the van","Van will move away","Nothing — balls are irrelevant","Child may dart out chasing the ball — cover the brake and creep with a cleared sightline"],
    a:3,
    why:"Ball + van + visible feet is the classic hidden-child setup: expect a child to emerge at speed without looking, and slow until the full sidewalk is in view.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ph08", cat:"markings", form:"photo", concept:"lane-selection",
    scene:"PHOTO: your lane's dotted divider becomes SOLID approaching an intersection; ONLY is painted ahead.",
    q:"What does this photo tell you about lane changes here?",
    choices:["Change lanes freely","You must change lanes","Lane changes are prohibited once solid — stay in lane before the intersection","You must stop"],
    a:2,
    why:"Solid lines before intersections mean no lane changes; combined with ONLY markings, commit to your lane early and hold it through the junction.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ms07", cat:"safety", form:"multi-step", concept:"low-visibility",
    scene:"MULTI-STEP: dense fog rolls in — speed 55, visibility ~100 ft, wipers on, high beams currently ON.",
    q:"Order the corrections:",
    choices:["① Keep 55 → ② high beams → ③ follow taillights closely","① Slow to match visibility → ② switch to low beams → ③ extend following gap → ④ pull fully OFF the road if you must stop","① Stop in-lane → ② hazards while moving","① Speed up to exit the fog faster"],
    a:1,
    why:"Fog protocol in order: drive at sight-distance speed, low beams cut glare-back, stretch the gap to six-plus seconds, and any stop happens fully off the carriageway — in-lane stops cause chain crashes.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"ms08", cat:"laws", form:"multi-step", concept:"emergency-vehicles",
    scene:"MULTI-STEP: siren behind you at a red light; you are SECOND in line and the car ahead hasn't moved.",
    q:"Correct sequence?",
    choices:["Stay put; when the light allows, pull right and stop — never run the red to make way","Honk the car ahead to push them through the red","Run the red immediately","Reverse onto the sidewalk"],
    a:0,
    why:"You cannot legally enter the intersection to 'make room' — you'd become the hazard. Hold position, then clear normally when permitted, pulling as far right as possible so the rig can pass.",
    sourceId:"us-dmv-handbooks-composite" },
  /* US transfer batch 1 — second and third variants for 24 single-question
     universal concepts, so each reaches 3 questions across 2+ forms and can
     genuinely evidence wording/form transfer (see js/mastery.js). */
  { id:"vh16", cat:"vehicle", form:"scenario", concept:"abs-emergency-braking",
    q:"You're doing 60 when traffic ahead stops dead. Your car has ABS. What's the stop?",
    choices:["Pump the pedal fast","Stomp the pedal hard, hold it, and steer around the hazard","Brake gently to save the tires","Yank the parking brake"],
    a:1,
    why:"ABS only works under full, steady pressure — stomp and stay on the pedal while steering where you need to go. The pulsing pedal and grinding noise are the system working, not failing; pumping or easing off throws that away.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh17", cat:"vehicle", form:"what-next", concept:"abs-emergency-braking",
    q:"You brake hard in the rain and feel the pedal pulsing under your foot. What happens next?",
    choices:["The ABS failed — release the pedal","Pump around the pulsing","Turn the engine off","Keep pressing hard and steer — the pulsing means ABS is working"],
    a:3,
    why:"A pulsing pedal during hard braking is ABS cycling pressure many times a second to keep the tires gripping. Hold firm pressure and keep steering; releasing or pumping hands control back to locked, skidding wheels.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw21", cat:"laws", form:"scenario", concept:"address-change-notification",
    q:"You move across town and your license still shows the old address. A renewal notice goes missing and your license lapses. What should you have done?",
    choices:["Nothing — addresses update automatically","Wait until the next renewal","Notify the DMV promptly after moving, usually within days","Only tell your insurer"],
    a:2,
    why:"Most states require you to report a new address within days of moving so licenses, suspension notices, and recall letters reach you. It's a quick online update, and 'I never got the notice' won't excuse driving on an invalid license.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw22", cat:"laws", form:"what-next", concept:"address-change-notification",
    q:"Your friend moves and shrugs: 'I'll update my license when it expires in three years.' What happens next if the state suspends it for an unpaid ticket in the meantime?",
    choices:["The notice goes to the old address and they may drive suspended without knowing","The suspension waits until renewal","Friends can forward the notice legally","Out-of-state mail is re-sent free"],
    a:0,
    why:"Suspension and violation notices go to the address on file, and driving on a suspended license brings fines or arrest whether you saw the letter or not. Updating promptly after a move keeps you reachable and legal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp19", cat:"speed", form:"scenario", concept:"advisory-speed-sign",
    q:"A yellow sign on a freeway ramp suggests 35 while the white limit nearby says 65. A driver holds 65 onto the ramp. What's wrong?",
    choices:["Nothing — white signs always govern every stretch","Ramps have no speed rules","Trucks only must slow","Yellow advisory speeds are the safe maximum for that curve; the 65 limit doesn't cover it"],
    a:3,
    why:"Yellow advisory speeds are engineering recommendations for ideal conditions on that specific curve — not legal limits, but the safe maximum there. Holding the through-road limit onto a tight ramp is how rollovers happen.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp20", cat:"speed", form:"what-next", concept:"advisory-speed-sign",
    q:"Rain starts pounding on a winding road posted with a yellow 40-mph curve sign. You're doing 40. What happens next?",
    choices:["40 stays safe — the sign accounts for rain","Grip drops, so 40 may now be too fast — slow below the advisory speed","Speed up to clear the curves faster","Move to the shoulder and stop in the curve"],
    a:1,
    why:"Advisory speeds assume ideal conditions: dry pavement, good visibility, a car in good order. Rain halves your margin, so treat the yellow number as a ceiling for good weather and go slower when conditions turn.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf33", cat:"safety", form:"scenario", concept:"aggressive-driver-response",
    q:"A driver you accidentally cut off pulls alongside, shouting and waving you over. What's the safest move?",
    choices:["Slow down so they pass, avoid eye contact, and head for a busy public place if followed","Pull over and apologize face to face","Match their speed to talk","Follow them to get their plate"],
    a:0,
    why:"Distance dissolves road rage: letting them go removes the contest, and a public place or police station gives you witnesses if they persist. Stopping to argue or following them turns a scare into a confrontation.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf34", cat:"safety", form:"what-next", concept:"aggressive-driver-response",
    q:"Someone is tailgating and flashing headlights behind you on a two-lane road. You keep your speed and stare them down in the mirror. What happens next?",
    choices:["They calm down and back off","Police arrive automatically","Your attention on the mirror steals it from the road ahead — ease right, let them pass, and reset your space","Speed up to teach them patience"],
    a:2,
    why:"A mirror-staring contest trades the road ahead for the threat behind. Moving right and letting the aggressor through restores your following gap and ends the encounter in seconds.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf35", cat:"safety", form:"scenario", concept:"airbag-and-child-seat-distance",
    q:"A petite driver sits with her chest 5 inches from the steering wheel to reach the pedals. Why is this dangerous?",
    choices:["Seatbelts fail under 6 inches","Airbags need room to inflate — sit about 10 inches back and adjust the seat, not your spine","Steering feel is lost","Airbags only work at 5 inches"],
    a:1,
    why:"An airbag explodes outward at over 100 mph in the first milliseconds — a driver crowded against the wheel takes that force in the face and chest. Sliding the seat back to roughly 10 inches gives the bag room to cushion instead of strike.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf36", cat:"safety", form:"what-next", concept:"airbag-and-child-seat-distance",
    q:"Parents buckle their rear-facing infant seat into the front passenger seat 'to keep an eye on the baby.' What happens in a frontal crash?",
    choices:["The airbag gently holds the seat","The baby is safest in front","Front seats have softer belts","The passenger airbag strikes the back of the infant seat with lethal force — rear-facing seats always go in the back"],
    a:3,
    why:"Passenger airbags deploy upward and outward directly into where a rear-facing seat sits. The back seat is the only safe place for a rear-facing child — no angle or careful driving changes the physics.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al17", cat:"alcohol", form:"scenario", concept:"alcohol-first-effect",
    q:"After two drinks your friend says, 'I feel totally fine — my judgment is great.' What's the flaw?",
    choices:["Alcohol improves judgment first","Two drinks never affect anyone","Judgment and self-criticism fade before you notice — feeling fine is the impairment talking","Only coordination matters"],
    a:2,
    why:"Alcohol anesthetizes self-monitoring first: the ability to judge your own impairment is itself impaired early. That's why drinkers insist they're fine while missing risks they'd normally catch — coordination fails next.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al18", cat:"alcohol", form:"what-next", concept:"alcohol-first-effect",
    q:"A driver has one beer and feels sharper and more confident. What happens next on the road?",
    choices:["False confidence meets slower reactions — small risks get accepted that a sober driver would refuse","Driving improves for an hour","Reaction time drops to zero","Only speech is affected"],
    a:0,
    why:"Even small amounts lift confidence while dulling hazard perception and reaction. The danger isn't passing out — it's the slightly faster entry into a curve or the slightly later brake press, made with full confidence.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg54", cat:"signs", form:"scenario", concept:"animal-crossing-sign",
    q:"At dusk on a rural highway you pass a leaping-deer sign. Nothing is visible. What should you do?",
    choices:["Maintain speed — signs are just advisory","Flash high beams continuously","Stop on the highway and wait","Slow down and scan the shoulders — deer move at dawn and dusk, and rarely travel alone"],
    a:3,
    why:"Deer-crossing signs mark corridors where collisions cluster, especially in low-light hours. Slowing buys stopping distance, and expecting a second animal after the first is what turns a scare into a non-event.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg55", cat:"signs", form:"sign-combo", concept:"animal-crossing-sign", signIds:["deerCrossing","speedLimit"],
    q:"A deer-crossing warning stands beside a 55-mph limit sign. Together they mean:",
    choices:["55 applies only to trucks here","The limit stays 55 but the warning tells you to drive below it where animals are likely","Deer are guaranteed on the road","Warnings cancel the limit"],
    a:1,
    why:"Regulatory limits and warnings work as a pair: 55 is the legal ceiling, the deer sign says conditions demand less. The basic speed law expects you under the number when a signed hazard is present.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf37", cat:"safety", form:"scenario", concept:"animal-on-road",
    q:"A large dog darts from a driveway into your lane. A cyclist rides the lane to your left. What's the call?",
    choices:["Brake firmly in your lane — never swerve into the cyclist to miss an animal","Swerve left around the dog","Accelerate past before it moves","Close your eyes and hold speed"],
    a:0,
    why:"Swerving trades a fender-bender for a possible fatality: the cyclist has no protection. Hard straight-line braking minimizes harm to everyone, and the horn may still send the animal back.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf38", cat:"safety", form:"what-next", concept:"animal-on-road",
    q:"One deer bounds across the road and disappears into the trees. You relax and resume speed. What happens next?",
    choices:["The road is clear — deer travel alone","Your headlights recharge","More deer often follow seconds behind — hold your slowed speed and keep scanning","Honk continuously for a mile"],
    a:2,
    why:"Deer move in groups, and the second or third animal typically trails the first by seconds on the same path. Drivers who speed up after one crossing meet the next one at full speed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al19", cat:"alcohol", form:"scenario", concept:"bac-determining-factors",
    q:"Two friends each have three beers in an hour: a 250-lb man who ate dinner and a 130-lb woman drinking on an empty stomach. Who's more impaired?",
    choices:["Equally — three beers is three beers","The man — men always peak higher","Neither — food cancels alcohol","Likely the woman — lower weight and no food mean a higher peak BAC from the same drinks"],
    a:3,
    why:"Alcohol dilutes through body water and absorbs faster on an empty stomach, so the same drinks produce very different BACs. Drink count alone never tells you impairment — weight, food, pace, and time do.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al20", cat:"alcohol", form:"what-next", concept:"bac-determining-factors",
    q:"Someone chugs four shots in 30 minutes, then sips water for another 30 and feels 'okay to drive.' What happens next to their BAC?",
    choices:["Water flushes it out","It's still climbing — alcohol keeps absorbing after you stop drinking, so impairment can worsen while you feel better","It peaked at the last shot","Only beer keeps absorbing"],
    a:1,
    why:"Alcohol absorbs over 30–90 minutes, so BAC keeps rising well after the last drink — especially after rapid rounds. Feeling steadier while the number climbs is exactly how post-party crashes happen.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al21", cat:"alcohol", form:"scenario", concept:"bac-legal-limit",
    q:"A 22-year-old blows 0.06% at a checkpoint and says, 'Under 0.08, I'm legal.' The officer still arrests for DUI. How?",
    choices:["Officers can arrest below the limit when driving shows impairment — 0.08 is per-se guilt, not a safe harbor","The limit is actually 0.10","Checkpoints allow any arrest","Only under-21 drivers can be arrested below 0.08"],
    a:0,
    why:"The 0.08 figure makes guilt automatic, but it never made lower numbers safe: weaving, slow reactions, or a failed field test support a DUI below the limit. 'Under the number' is not a defense to visibly impaired driving.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al22", cat:"alcohol", form:"what-next", concept:"bac-legal-limit",
    q:"A teen driver with a junior license has one drink at dinner and drives home carefully. What happens next if stopped?",
    choices:["Teens get the adult limit","Careful driving excuses it","Zero-tolerance laws punish any detectable alcohol for under-21 drivers — often from 0.00–0.02%","Parents can authorize it"],
    a:2,
    why:"Every state holds under-21 drivers to near-zero limits: any measurable alcohol brings suspension and fines, careful driving or not. One drink is enough to end a teen license.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al23", cat:"alcohol", form:"scenario", concept:"bac-reduction-myth",
    q:"After drinking, a student downs two espressos and splashes cold water on his face, then feels alert. Can he drive?",
    choices:["Yes — alertness equals sobriety","No — stimulants mask drowsiness but BAC and impairment fall only with time","Yes if he eats a burger too","Yes after a 10-minute walk"],
    a:1,
    why:"Caffeine and cold water wake you up without removing a molecule of alcohol: reaction time and judgment stay degraded for hours. A wide-awake drunk driver is still a drunk driver.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al24", cat:"alcohol", form:"what-next", concept:"bac-reduction-myth",
    q:"Friends put their drunk buddy through jumping jacks and a cold shower 'to sober him up' before his drive. What happens next?",
    choices:["Exercise burns off BAC fast","Cold water shocks the liver into gear","Sweating removes most alcohol","He feels sharper but drives with the same BAC — only time lowers it, roughly one drink per hour"],
    a:3,
    why:"The liver clears alcohol at a fixed rate nothing accelerates — not sweat, showers, coffee, or exercise. Feeling energized only makes an impaired driver more confident about a bad decision.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr20", cat:"vulnerable", form:"scenario", concept:"ball-into-street",
    q:"You're driving a residential street lined with parked cars when a ball bounces out between two bumpers. No child is visible. Your move?",
    choices:["Keep speed — brake only for people","Swerve into the opposite lane","Brake early and cover the pedal — a child chasing the ball is likely seconds behind, hidden by the cars","Honk and maintain pace"],
    a:2,
    why:"Parked cars hide small children completely, and a chasing child sprints without looking. Early braking buys the two seconds that separate a scare from a tragedy — the ball is the warning, not the hazard.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr21", cat:"vulnerable", form:"what-next", concept:"ball-into-street",
    q:"Kids play catch on a front lawn sloping toward the road. One chases an overthrow toward the curb. What happens next?",
    choices:["The game pulls them into the street without a glance — slow now and be ready to stop fully","Children always look first","Lawns are fenced by default","The child will stop at the curb — keep driving normally"],
    a:0,
    why:"Children under ten can't reliably judge car speed and fixate on the game, not traffic. Any play near the road means a child in your lane with no warning — slow early enough that a full stop is easy.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp21", cat:"speed", form:"scenario", concept:"basic-speed-law",
    q:"Thick fog cuts visibility to 100 feet on a 55-mph highway. Traffic around you still does 55. What's legal for you?",
    choices:["55 — match traffic to stay safe","60 to get out of the fog faster","Stop in your lane with hazards","Slow to a speed that fits what you can see — the basic speed law can cite 55 as too fast for conditions"],
    a:3,
    why:"Posted limits assume clear sightlines; the basic speed law demands a speed where you can stop within what you see. In 100-foot visibility at 55, you're overdriving your headlights and the fog — tickets and pileups follow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp22", cat:"speed", form:"what-next", concept:"basic-speed-law",
    q:"You're doing the posted 45 through a downpour when the car ahead disappears into spray. You hold 45. What happens next?",
    choices:["Spray is harmless at the limit","Hydroplaning risk climbs — ease off until you can see and your tires reconnect, even far below the limit","Turn on high beams to see through it","Tailgate their taillights for guidance"],
    a:1,
    why:"Standing water lifts tires off the road, and no posted number prevents that — only slower speed restores grip. The basic speed law means the limit is a ceiling for good weather, not a promise for bad.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg56", cat:"signs", form:"scenario", concept:"bike-crossing-sign",
    q:"A yellow diamond shows a bicycle symbol ahead on a road with no bike lane. A rider appears on the shoulder. What do you do?",
    choices:["Slow, expect riders crossing or sharing the road, and pass wide with care","Hold speed — the sign is for cyclists, not drivers","Honk to keep them on the shoulder","Pass close to save time"],
    a:0,
    why:"Bicycle-warning signs mark stretches where riders cross or share the lane, often where a trail meets the road. Slowing early and giving wide clearance turns a startle into a routine pass.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg57", cat:"signs", form:"sign-combo", concept:"bike-crossing-sign", signIds:["bikeCrossing","pedCrossing"],
    q:"A bicycle warning and a pedestrian warning stand together at a trail crossing. The pair means:",
    choices:["Bikes only — pedestrians use another crossing","The trail is closed to traffic","Expect both riders and walkers crossing — slow and yield to whichever is in the road","Pedestrians must yield to bikes there"],
    a:2,
    why:"Paired warnings describe a shared trail crossing used both ways by bikes and pedestrians. Either can enter the road with little warning, so slow down and be ready to yield to whoever arrives first.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk29", cat:"markings", form:"lane-choice", concept:"bike-lane-use",
    scene:"  ║ CAR ║ BIKE ‾‾‾ ║\n  YOU → in car lane, bike lane at right (solid line + bicycle symbol)\n  Need: RIGHT TURN in 100 ft — a cyclist rides in the bike lane.",
    q:"You need to turn right across the bike lane with a cyclist in it. Which movement is legal?",
    choices:["Cut across now to beat the cyclist","Signal, yield to the cyclist, then merge into the lane only near the turn","Drive in the bike lane for the last block","Turn from the car lane across the cyclist's path"],
    a:1,
    why:"Bike lanes stay exclusive except where a turn requires crossing: signal early, let the rider through, then enter the lane briefly at the intersection. Passing, cruising, or cutting across the rider is never allowed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk30", cat:"markings", form:"what-next", concept:"bike-lane-use",
    q:"Traffic is gridlocked and the empty bike lane beside you looks tempting. You slip in to skip the queue. What happens next?",
    choices:["Legal — empty lanes are usable","Fine if you stay under 20","Cyclists will move aside","You're breaking the law and forcing riders into traffic — a ticket or a collision follows"],
    a:3,
    why:"A bike lane is never a passing or queuing lane, empty or not. Entering it squeezes riders toward moving cars and earns a citation — the queue is your lane, however slow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw37", cat:"row", form:"scenario", concept:"blind-pedestrian-priority",
    q:"A person with a white cane stands at an unmarked crossing mid-block, listening to traffic. No signal exists here. What do you do?",
    choices:["Continue — unmarked crossings give cars priority","Flash lights and wave them across","Stop and yield the way fully, staying stopped until they are across","Edge forward to show you've seen them"],
    a:2,
    why:"White-cane and guide-dog travelers get the full right of way at any crossing, marked or not. Stop well short, stay quiet and still, and wait until they're completely across before moving.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw38", cat:"row", form:"what-next", concept:"blind-pedestrian-priority",
    q:"You honk a friendly tap to let a blind pedestrian know you're holding for them. What happens next?",
    choices:["The honk startles or misleads them — hold silently instead and let them cross on their own judgment","They wave thanks and hurry","Horns guide blind pedestrians well","They cross faster toward the sound"],
    a:0,
    why:"A horn blast near a person navigating by sound destroys the cues they're using — traffic direction, distance, your position. Silence plus a full stop is the help; noise is a hazard.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw39", cat:"row", form:"scenario", concept:"blind-pedestrian-signal",
    q:"At a signalized intersection, a traveler with a guide dog waits while your light is green and no pedestrian signal is lit. Who goes?",
    choices:["You — green with no walk signal means clear","The traveler with the guide dog — yield regardless of your green","Whoever moves first","The pedestrian — honk them through"],
    a:1,
    why:"Guide-dog teams cross on their own judgment of traffic gaps, not on signals they can't see. Your green never overrides their absolute priority — stop and wait for them to finish crossing.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw40", cat:"row", form:"what-next", concept:"blind-pedestrian-signal",
    q:"A guide-dog team steps off the curb against your fresh green. You creep forward to 'encourage' them to hurry. What happens next?",
    choices:["The dog speeds up helpfully","Creeping is the recommended signal","Your green protects you legally","You crowd a team that reads your car as a threat — stop fully and give them the whole crossing"],
    a:3,
    why:"Guide dogs are trained to disobey cues that lead into danger — a creeping car looks like an attack, freezing or scattering the team. A full, patient stop is the only move that helps them cross.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf39", cat:"safety", form:"scenario", concept:"blind-spot-checks",
    q:"Mirrors show the next lane empty, but you haven't turned your head. A motorcycle sits exactly in your blind spot. What's the check?",
    choices:["Mirrors are enough at speed","Honk before moving over","Signal, check mirrors, then glance over your shoulder before moving","Change lanes fast to minimize exposure"],
    a:2,
    why:"Mirrors leave a wedge where an entire motorcycle vanishes — the over-shoulder glance covers exactly that wedge. Signal, mirrors, shoulder, go: skipping the glance is how 'I never saw them' crashes happen.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf40", cat:"safety", form:"what-next", concept:"blind-spot-checks",
    q:"You merge on mirrors alone and sideswipe a small car that was hidden in the blind spot. What went wrong?",
    choices:["You skipped the head check — mirrors plus a shoulder glance is the full lane-change sequence","The car was speeding","Mirrors cover everything","The other car was invisible — nothing you could do"],
    a:0,
    why:"Every merge needs the full sequence because mirrors physically cannot show the blind wedge. The glance takes half a second and catches exactly the car that mirrors hide.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw41", cat:"row", form:"diagram", concept:"blocked-intersection",
    scene:"  YOU → ┼───■ ■ ■ (queue fills the far side)\n  GREEN ● — no room beyond the crosswalk",
    q:"Your light is green but the far side is packed with stopped cars. Where do you wait?",
    choices:["Enter and wait in the middle","Behind the crosswalk until your exit clears — even through the whole green","Join the queue inside the intersection","On the crosswalk, hazards on"],
    a:1,
    why:"Blocking the box gridlocks the cross street when their light changes — and earns a ticket in many cities. A green you can't clear is a wait, not an invitation: hold the line until the far side fits your whole car.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw42", cat:"row", form:"what-next", concept:"blocked-intersection",
    q:"You pull into the intersection on green and traffic freezes — you're stranded across the crosswalk as cross traffic gets the green. What happens next?",
    choices:["Cross traffic must wait for you","Back up through the crosswalk","Hazards make it legal","You block ambulances, buses, and turning cars — and sit through their whole cycle as the jam you caused"],
    a:3,
    why:"A stranded car chokes the entire crossing: cross traffic can't flow, pedestrians weave around you, and emergency vehicles lose their lane. One impatient entry cascades into a gridlocked intersection for everyone.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh18", cat:"vehicle", form:"scenario", concept:"brake-pedal-fault",
    q:"Halfway down a hill the brake pedal sinks low and feels mushy, though the car still slows. What's happening and what do you do?",
    choices:["Normal ABS behavior — keep driving","Worn wipers — replace soon","Air or a leak in the hydraulics — downshift, use the parking brake gently, and stop driving it until serviced","Low fuel — fill up"],
    a:2,
    why:"A sinking pedal means hydraulic pressure is escaping — braking can vanish entirely with one more push. Engine braking plus a gentle parking-brake application gets you stopped; then it's a tow, not a drive home.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh19", cat:"vehicle", form:"what-next", concept:"brake-pedal-fault",
    q:"Your pedal felt soft yesterday but firmed up this morning, so you skip the shop. What happens next?",
    choices:["Intermittent softness can precede sudden total failure — get it inspected before driving further","Brakes heal themselves","Soft pedals are seasonal","Top up washer fluid and forget it"],
    a:0,
    why:"Brake faults come and go as fluid leaks and air shifts — a firm pedal today doesn't refill yesterday's leak. The next soft press can be the one with no brakes at all, so any change in feel means immediate inspection.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk31", cat:"markings", form:"scenario", concept:"broken-yellow-line",
    q:"On a two-lane road, the centerline on YOUR side is dashed yellow while the far side is solid. A slow tractor is ahead and no traffic is coming. Can you pass?",
    choices:["No — any yellow forbids passing","Only motorcycles may pass","Only at night","Yes — the broken line on your side permits passing when the way is clear"],
    a:3,
    why:"The line on your side is the one that governs you: broken means passing allowed with clear sightlines, solid means stay put. Here the tractor is legally passable — the solid line binds only oncoming drivers.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk32", cat:"markings", form:"what-next", concept:"broken-yellow-line",
    q:"You start passing on a dashed yellow, then the line turns solid beside you with a car now visible far ahead. What happens next?",
    choices:["Floor it to beat the car","The solid line ahead cancels your pass — drop back into your lane promptly","Swerve onto the shoulder to continue","Flash high beams to claim the lane"],
    a:1,
    why:"A line turning solid mid-pass is the road withdrawing permission: sight distance has shrunk below safe passing length. Abort early and slot back in — the gap you saw is already gone.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf41", cat:"safety", form:"scenario", concept:"carbon-monoxide-risk",
    q:"After a blizzard your exhaust pipe is buried in a snowbank and you idle the car to warm up with the windows shut. What's the danger?",
    choices:["Blocked exhaust forces odorless CO into the cabin — clear the pipe and crack a window, or don't idle","Snow filters exhaust safely","Cold air neutralizes CO","Only diesel makes CO"],
    a:0,
    why:"Snow seals the exhaust outlet and pushes carbon monoxide under and into the car, where it builds silently. Clear the tailpipe fully before idling, ventilate, and never nap in an idling car.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf42", cat:"safety", form:"what-next", concept:"carbon-monoxide-risk",
    q:"A family warms up the car inside a closed garage 'just for a minute' while loading luggage. What happens next?",
    choices:["Garages ventilate automatically","A minute is always safe","CO builds to lethal levels in minutes in an enclosed space — back the car out first, then load","Opening the trunk airs it out"],
    a:2,
    why:"A running engine can poison a single-car garage in under two minutes — and CO's first symptoms feel like drowsiness, so victims sit down instead of escaping. The car leaves the garage before it warms up, never after.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg58", cat:"signs", form:"scenario", concept:"centre-line-passing-rule",
    q:"Two-way road, no signs: your side shows a SOLID yellow line, the far side broken. The car ahead crawls at 15. Can you cross to pass?",
    choices:["Yes — slow traffic may always be passed","No — the solid line on your side bans crossing to pass, however slow they go","Yes if you honk first","Yes on weekdays"],
    a:1,
    why:"A solid yellow on your side is an absolute no-passing line for you, even behind a crawl — the far side's broken line permits only oncoming drivers to cross. Wait for your side to break or a passing lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg59", cat:"signs", form:"sign-combo", concept:"centre-line-passing-rule", signIds:["noPassingZone","twoWayTraffic"],
    q:"A pennant-shaped NO PASSING ZONE sign points at a centerline that's solid on your side. The pair tells you:",
    choices:["Passing is fine downhill","The pennant is decorative","Only trucks are restricted","The sign and the line agree — stay in lane; the zone ends where your side breaks or a sign says so"],
    a:3,
    why:"Pennant signs mark the start of state-surveyed no-passing zones, and the solid line paints the same message on the road. Two independent warnings mean sight distance is genuinely too short — obey both until the restriction ends.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg60", cat:"signs", form:"scenario", concept:"chevron-sign",
    q:"At night a row of yellow chevrons glows on the outside of a bend, arrows pointing left. A driver holds highway speed into it. What's the risk?",
    choices:["Chevrons are decorative lighting","Left-pointing arrows mean turn around","The curve bends sharply left — enter too fast and momentum carries you off the outside edge","Chevrons mark rest areas"],
    a:2,
    why:"Chevrons trace the outside of curves sharp enough to warrant their own signs, with arrows showing the bend's direction. They are a slow-down-before-the-curve warning: braking mid-bend unloads the tires that need grip most.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg61", cat:"signs", form:"sign-combo", concept:"chevron-sign", signIds:["chevron","slippery"],
    q:"Chevron arrows line a curve beneath a slippery-when-wet warning. In rain, the pair means:",
    choices:["Slow before the curve and expect reduced grip through it — the warnings multiply, not overlap","Rain washes the curve straight","Chevrons cancel in wet weather","Only the lower sign applies"],
    a:0,
    why:"A sharp curve plus a wet surface is worse than either alone: less grip exactly where turning demands most. Slow earlier than you would for a dry curve and make no sudden inputs until straight.",
    sourceId:"us-dmv-handbooks-composite" },
  /* US transfer batch 2 — second and third variants for the next 24
     single-question universal concepts, so each reaches 3 questions across
     2+ forms and can genuinely evidence wording/form transfer. */
  { id:"vr22", cat:"vulnerable", form:"what-next", concept:"bike-passing-distance",
    q:"You start passing a cyclist with full lane clearance when a parked car's door swings open ahead of the rider. What happens next?",
    choices:["The rider holds a straight line regardless","The rider may swerve left toward you — hold back and pass only when the door zone is clear","Speed up to clear the door first","Honk to freeze the rider in place"],
    a:1,
    why:"An opening door pushes riders left without warning — the 'door zone' is exactly why wide clearance matters. Hanging back until past the parked cars costs seconds; threading through risks a swerve you can't miss.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr23", cat:"vulnerable", form:"recall", concept:"bike-passing-distance",
    q:"Why do cyclists sometimes ride well out from the edge, even with no bike lane?",
    choices:["To slow traffic deliberately","To show off","They are required to hug the gutter","To avoid doors and debris and stay visible — pass with generous clearance"],
    a:3,
    why:"The gutter holds grates, glass, and opening doors, and edge-riding makes riders invisible at junctions. Riding out is defensive positioning, not rudeness — treat it as a signal to pass wide, not close.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf43", cat:"safety", form:"scenario", concept:"child-restraint-seat",
    q:"Your 6-year-old outgrew the forward-facing seat and begs to ride with just a belt 'like a grown-up.' What's the rule?",
    choices:["Belts fit all sizes","Backless cushion only on highways","Move them to a booster in the back until the adult belt fits properly","Front seat with the belt behind their back"],
    a:2,
    why:"Adult belts are sized for adult hips and shoulders — on a small child the lap belt rides up onto the belly and the shoulder belt cuts the neck. A booster lifts them into the belt's design range, in the back seat away from airbags.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf44", cat:"safety", form:"what-next", concept:"child-restraint-seat",
    q:"A friend installs a booster in front of an active airbag 'for the legroom.' What happens in a hard stop?",
    choices:["The deploying airbag can seriously injure a child up front — boosters always go in the back","The airbag supplements the booster safely","Boosters deactivate airbags","The child is fine if belted"],
    a:0,
    why:"Airbags punch outward with enormous force tuned for adult chests at adult distances. A child in front takes that full force to the head and neck — the back seat removes the risk entirely.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf45", cat:"safety", form:"scenario", concept:"collision-information-exchange",
    q:"A fender-bender blocks a lane. The other driver says 'let's just go, no damage really.' You notice their bumper is cracked. What do you do?",
    choices:["Agree and drive off","Take a photo of their car and leave","Chase them for an apology","Exchange license, contact, insurance, and plate details before anyone leaves"],
    a:3,
    why:"Damage hides under bumpers and injuries surface hours later — without exchanged details you own the whole bill. A two-minute exchange plus photos protects both drivers; leaving first is hit-and-run even when it felt minor.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf46", cat:"safety", form:"what-next", concept:"collision-information-exchange",
    q:"You swap details after a scrape, then the other driver admits they have no insurance. What happens next?",
    choices:["Let them go — nothing to collect","Document everything and report to police and your insurer at once","Accept cash on the spot","Delete their number"],
    a:1,
    why:"Uninsured drivers still owe for damage they cause, but only a police report plus prompt insurer notice preserves your claim and your uninsured-motorist cover. Cash at the curb waives all of that for a guess.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw23", cat:"laws", form:"scenario", concept:"crash-duty-to-stop",
    q:"You clip a parked car at night with nobody around. No note is left and you drive on. Legally, what just happened?",
    choices:["Hit-and-run: you must stop, leave your details, and report the crash as required","Leaving was fine since nobody was hurt","Only felonies need reporting","Parking scrapes don't count"],
    a:0,
    why:"The duty to stop covers property damage too — parked cars included. Leaving without details is hit-and-run even with no injuries, while a note plus a prompt report keeps a scrape a scrape.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw24", cat:"laws", form:"what-next", concept:"crash-duty-to-stop",
    q:"You stop after a crash, exchange details, then realize a passenger complains of neck pain an hour later. What happens next?",
    choices:["Too late — the scene is closed","Pain always fades","Call emergency services and report the injury — delayed symptoms still require a report","Drive them home and wait"],
    a:2,
    why:"Soft-tissue injuries often surface after the adrenaline fades, and injury crashes carry reporting duties beyond a property-damage exchange. Getting checked and updating the report protects both health and any claim.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf47", cat:"safety", form:"scenario", concept:"crash-scene-first-action",
    q:"You round a bend to find a fresh two-car crash blocking your lane, fluids on the road. What's your first sequence?",
    choices:["Drive through the gap quickly","Stop safely short, switch hazards on, warn oncoming traffic, call 911","Stop past the scene and walk back","Pull the drivers out of their cars first"],
    a:1,
    why:"A second crash at the same spot is the immediate threat — position, lights, and warning come before treatment. Once the scene is protected, call it in and help without moving anyone unless fire or traffic forces it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf48", cat:"safety", form:"what-next", concept:"crash-scene-first-action",
    q:"At a crash scene someone yells to drag an unconscious driver clear 'before the car explodes.' What happens if you do?",
    choices:["Explosions are imminent — always drag first","Unconscious people prefer moving","Fires are routine","You risk turning a survivable spinal injury into paralysis — move them only for immediate danger like fire"],
    a:3,
    why:"Car fires after crashes are rare; spinal damage from rough handling is not. Unless flames, smoke, or oncoming traffic make staying worse than moving, stabilize in place and wait for responders.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr24", cat:"vulnerable", form:"scenario", concept:"crossing-guard-authority",
    q:"A guard steps out with the paddle while your lane still flows and no children are visible yet. Drivers behind honk. What do you do?",
    choices:["Follow the flow — no kids, no stop","Creep forward slowly","Stop and stay stopped until the guard clears the crossing","Wave the kids across yourself"],
    a:2,
    why:"The paddle is a legal stop command whether or not you see children yet — they're often still behind a bus or hill. Stopping holds the lane safe for their arrival; the honks behind change nothing.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr25", cat:"vulnerable", form:"what-next", concept:"crossing-guard-authority",
    q:"The guard lowers the paddle and steps back, but a straggler child still hurries across. You start rolling. What happens next?",
    choices:["Stay stopped until the last child clears — pedestrians in the road keep priority after the paddle drops","The lowered paddle ends your duty","Children clear fast","Other lanes cover them"],
    a:0,
    why:"The paddle controls traffic flow, but pedestrians lawfully in the roadway keep the right of way regardless. Rolling early toward a hurrying child is how school-zone tragedies happen.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk33", cat:"markings", form:"scenario", concept:"crosswalk-markings",
    q:"Zebra bars stretch across your lane ahead with a pedestrian waiting at the curb, looking at you. What's expected?",
    choices:["Maintain speed — waiting isn't crossing","Flash headlights as a warning","Stop only if they step out","Slow and stop to let them cross — waiting at a marked crosswalk is asking to cross"],
    a:3,
    why:"At a marked crosswalk a waiting pedestrian is asserting priority, not requesting a favor. Stopping early and fully, before the bars, keeps the crossing predictable for everyone.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk34", cat:"markings", form:"what-next", concept:"crosswalk-markings",
    q:"You stop for a crosswalk and the SUV behind swerves into the next lane to pass you. What happens next?",
    choices:["Normal — they saw it was clear","Stay stopped — they may drive into the pedestrian hidden by your car","Honk them back","Follow them through"],
    a:1,
    why:"A stopped car at a crosswalk is itself a warning sign — passing it unsighted is one of the deadliest moves on urban roads. Hold your stop and let the pedestrian finish; the passer learns nothing good.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw43", cat:"row", form:"scenario", concept:"crosswalk-pedestrian-priority",
    q:"Rain pours at an unmarked intersection and a pedestrian without an umbrella darts halfway across your lane. What's the call?",
    choices:["Brake and let them finish — pedestrians in the roadway get room, signal or not","Swerve around ahead of them","Honk them back to the curb","Hold speed; unmarked means your priority"],
    a:0,
    why:"Marked or not, a pedestrian already in your lane is a hazard you must not hit — unmarked crossings still carry pedestrian rights in most states. Braking costs seconds; asserting priority over a person risks everything.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw44", cat:"row", form:"what-next", concept:"crosswalk-pedestrian-priority",
    q:"You wave a pedestrian through, then a car in the next lane keeps coming. What happens next?",
    choices:["Your wave controls all lanes","The pedestrian is safe now","Your wave binds only you — stay alert and be ready to honk a warning to the other lane","Wave harder"],
    a:2,
    why:"A wave is a promise you can't keep for other drivers — multi-lane crossings need every lane stopped. Never beckon someone into a lane you haven't verified, and watch the adjacent lane until they're across.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr26", cat:"vulnerable", form:"scenario", concept:"cyclist-swerve",
    q:"A rider ahead keeps glancing back at you over their shoulder. What does that glance most likely mean?",
    choices:["A greeting","They're checking to move out around something — ease off and expect a lateral move","They want to race","They're lost"],
    a:1,
    why:"A shoulder check is a rider's turn signal: something ahead — drain, debris, door, junction — is about to push them sideways. Backing off the moment you see it buys the room their move will need.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr27", cat:"vulnerable", form:"what-next", concept:"cyclist-swerve",
    q:"The cyclist ahead suddenly raises their left arm horizontally. You hold speed beside them. What happens next?",
    choices:["They're stretching","They're slowing down","Wave back and pass","They're signaling a left turn across your path — hold back and let them go"],
    a:3,
    why:"An extended left arm is the universal hand signal for a left turn — the rider is about to cross your lane. Overtaking through the signal turns their legal turn into your collision.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg62", cat:"signs", form:"scenario", concept:"dead-end-sign",
    q:"A yellow diamond with an arrow ending in a bar appears on an unfamiliar rural road at night. How do you read it?",
    choices:["Detour marker","No entry ahead","Dead end ahead — slow early and plan a turnaround","Merge warning"],
    a:2,
    why:"The T-with-a-bar means the road terminates with no through connection. Reading it early lets you slow and turn calmly instead of discovering the end at speed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg63", cat:"signs", form:"what-next", concept:"dead-end-sign",
    q:"You miss the dead-end sign and reach the road's end facing a field gate. What's the safe recovery?",
    choices:["Turn around with full all-round observation — never reverse blindly back along the road","Reverse at speed to the last junction","U-turn without looking","Park and walk"],
    a:0,
    why:"A long blind reverse down a road you just drove is how pedestrians and ditches get hit. A slow, observed turn at the wide end — or a driveway done properly — gets you out facing forward.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg64", cat:"signs", form:"scenario", concept:"divided-highway-sign",
    q:"After miles of single carriageway, a sign shows the road splitting around a grass median. A driver asks if U-turns are now easier. What's the answer?",
    choices:["Yes — medians are for turning","Only at night","Yes for small cars","Crossing a median is prohibited except at designated openings — opposing traffic now passes at full speed feet away"],
    a:3,
    why:"A divided highway means high-speed opposing lanes separated only by the median. Treating the divider as a turning aid invites a head-on; use proper interchanges and signed crossovers.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg65", cat:"signs", form:"sign-combo", concept:"divided-highway-sign", signIds:["dividedHighwayBegins","twoWayTraffic"],
    q:"A 'divided highway begins' sign stands near a two-way-traffic warning. Together they tell you:",
    choices:["The road is now one-way","A median now separates opposing flows — keep right of it and never cross except at openings","U-turns are now encouraged","The median is a parking lane"],
    a:1,
    why:"The pair describes the transition: two-way road becoming divided. From the split on, the median is a barrier, not a line — crossing it outside an opening means entering high-speed oncoming lanes.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg66", cat:"signs", form:"scenario", concept:"do-not-enter-sign",
    q:"Turning at night you glimpse a red circle with a white bar facing you mid-turn. What's happening and what now?",
    choices:["You're entering against traffic — stop, back out safely if possible, and turn around","It's decorative — continue","Speed up to clear the area","Turn off headlights and continue"],
    a:0,
    why:"A DO NOT ENTER face means your lane opposes the legal flow — you're the wrong-way driver. Stopping before fully committing, then extracting carefully, beats pressing on into head-on traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg67", cat:"signs", form:"sign-combo", concept:"do-not-enter-sign", signIds:["doNotEnter","oneWay"],
    q:"DO NOT ENTER faces you while a ONE WAY arrow points the opposite direction. The pair means:",
    choices:["Two-way street","Street closed to all traffic","You're facing the wrong way on a one-way street — turn back and re-enter with the arrow","One-way applies to trucks only"],
    a:2,
    why:"The two signs are one message from opposite ends: the street flows with the arrow, and your face of it is forbidden. Reading the pair tells you both the error and the fix — go back, come again with the flow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw25", cat:"laws", form:"scenario", concept:"documents-to-carry",
    q:"Borrowing a friend's car, you're stopped and have your license but no registration or insurance proof. What's your position?",
    choices:["License is enough in a borrowed car","You're in violation — registration and insurance proof must be producible for the car you're driving","Borrowed cars are exempt","A promise to mail them later fixes it"],
    a:1,
    why:"Document duties follow the driver-car combination: whoever drives must be able to produce license plus the vehicle's papers. Borrowing the car means borrowing the duty to check its documents first.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw26", cat:"laws", form:"what-next", concept:"documents-to-carry",
    q:"Your insurance card expired last week and the new one 'is in the mail.' You're stopped today. What happens next?",
    choices:["Grace periods are automatic","Officers always wait","Mail delays excuse everything","Expired proof counts as no proof — fines follow until valid cover is shown"],
    a:3,
    why:"Coverage must be current and producible on the day, not merely paid for or posted. Most insurers offer instant electronic cards precisely so 'in the mail' never has to be the answer — carry valid proof of cover.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk35", cat:"markings", form:"scenario", concept:"double-solid-yellow",
    q:"Double solid yellow lines run down a road with shops on both sides. You need the store directly left. When may you cross?",
    choices:["Never — find another route always","Only on Sundays","You may cross to turn left into a driveway where permitted — never to pass or travel","Only to pass slower cars"],
    a:2,
    why:"Double yellow bans passing and through-travel in the opposing lane, but most states allow crossing it for a left turn into property where safe. The distinction is purpose: access yes, overtaking never.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk36", cat:"markings", form:"what-next", concept:"double-solid-yellow",
    q:"Stuck behind a garbage truck on double solid yellow, you swing out to pass and meet an oncoming car. What happens next?",
    choices:["Brake and tuck back in behind the truck at once — the lines warned sight distance is too short","Accelerate past both","Swerve onto the shoulder to continue","Honk the oncoming car aside"],
    a:0,
    why:"Double solid marks stretches where engineers measured passing as unsafe — the oncoming car is exactly what the lines predicted. Aborting early is the only move; committing converts a delay into a head-on.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al25", cat:"alcohol", form:"scenario", concept:"drink-driving-planning",
    q:"Two friends plan a night out: one says 'we'll figure out rides later.' What's the flaw in waiting?",
    choices:["Rides get cheaper later","Planning ruins fun","Later decisions are sharper","Decide the sober ride before going — impaired brains approve impaired plans"],
    a:3,
    why:"Alcohol degrades exactly the judgment needed to choose safety, so 'later' means deciding drunk. A ride fixed while sober removes the decision from the impaired version of you.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al26", cat:"alcohol", form:"what-next", concept:"drink-driving-planning",
    q:"The designated driver has 'just two beers' early and feels fine to keep the role. What happens next?",
    choices:["Two is always safe for a designated driver","A driver who drinks is no longer the designated driver — hand over the keys","Only the group can judge","Experience compensates"],
    a:1,
    why:"Designated means sober, not least-drunk — even small amounts dull the reactions a driver sells to the group. The role transfers the moment a drink is taken, no exceptions.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf49", cat:"safety", form:"scenario", concept:"drowsy-driving",
    q:"On a night highway you catch yourself unable to recall the last few miles. What's the correct response?",
    choices:["Pull off safely and rest — missing miles means micro-sleep has started","Open the window wider and push on","Turn the music up","Drink coffee and continue at speed"],
    a:0,
    why:"Highway amnesia is the brain sleeping in slices with eyes open — the next slice can last seconds at 70 mph. Only sleep repays sleep debt; every stimulant just schedules the crash later.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf50", cat:"safety", form:"what-next", concept:"drowsy-driving",
    q:"Your eyelids keep drooping, so you let a passenger 'watch the road' while you blink-rest. What happens next?",
    choices:["Passengers make good spotters","Blinking rests the brain","A passenger can't brake or steer in time — take the next exit and sleep properly","Short naps at the wheel work"],
    a:2,
    why:"No passenger can grab the wheel faster than a drift becomes a departure — reaction needs hands already on it. The exit ramp is minutes away; the nap you need can't happen at speed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr28", cat:"vulnerable", form:"scenario", concept:"e-scooter-in-bike-lane",
    q:"A standing e-scooter doing 15 mph wobbles over a pothole in the bike lane beside you. How do you treat them?",
    choices:["As a pedestrian to ignore","As a rider with bicycle rights — same clearance, more caution for small wheels and wobbles","As a parked obstacle","As a car that should keep up"],
    a:1,
    why:"Small wheels transmit every bump as a swerve, and standing riders are narrow and quiet. Bicycle-level clearance is the floor here, not the ceiling — their instability spends your margin fast.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr29", cat:"vulnerable", form:"what-next", concept:"e-scooter-in-bike-lane",
    q:"An e-bike silently approaches from behind in your blind spot as you prepare a right turn across the bike lane. What happens next?",
    choices:["E-bikes yield to cars","Silence means safety","Turn quickly before it arrives","E-bikes close faster and quieter than expected — check, yield, then turn"],
    a:3,
    why:"Assisted bikes reach car-like speeds with bicycle silence, arriving in mirrors later than instinct expects. The turn waits until the lane is verified empty — speed you can't hear still hits.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr30", cat:"vulnerable", form:"scenario", concept:"elderly-pedestrian",
    q:"A pedestrian with a walker steps off the curb slowly, halfway judging the gap. Traffic builds behind you. What's right?",
    choices:["Wave them back to wait","Honk gently to focus them","Stop, wait patiently, and shield them with your car until they're across","Edge around them"],
    a:2,
    why:"Older pedestrians misjudge gaps and can't hurry — once committed they're fully exposed. Your stopped car is their shield; a few seconds of patience is the entire cost of their safety.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr31", cat:"vulnerable", form:"what-next", concept:"elderly-pedestrian",
    q:"An elderly person freezes mid-crosswalk as the signal changes against them. Drivers rev. What happens next?",
    choices:["Hold your stop and let them finish — a frozen pedestrian needs time, not pressure","Rev back to encourage them","They forfeited priority at the change","Squeeze past behind them"],
    a:0,
    why:"Freezing is panic, and engine noise deepens it — pressure can't speed a person who can't move faster. Holding still until they complete the crossing is the only response that helps.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw45", cat:"row", form:"scenario", concept:"emergency-vehicle-approach",
    q:"A fire truck wails behind you as you sit first at a red light with nowhere to pull right. What's legal?",
    choices:["Run the red to make room","Reverse into the car behind","Abandon the car","Stay put — never cross a red to yield; shift right if you can and clear when permitted"],
    a:3,
    why:"Running the light trades one emergency for another — cross traffic can't know why you moved. The law wants a yielded path, not a violated signal: hold, make room without entering, then clear normally.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw46", cat:"row", form:"what-next", concept:"emergency-vehicle-approach",
    q:"You pull right for an ambulance, then immediately tailgate it through the parted traffic. What happens next?",
    choices:["Smart — ride the wake","Following an emergency vehicle closely on a call is illegal and dangerous — drop back","The wake is a legal lane","Ambulances appreciate escorts"],
    a:1,
    why:"Most states set a keep-back distance around responding vehicles — and the gap ahead of you fills with cars pulling back in. Tailgating the rescue is a ticket wrapped around a crash.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf51", cat:"safety", form:"scenario", concept:"engine-stall",
    q:"Your engine dies coasting downhill and the steering suddenly feels like concrete. What's happening?",
    choices:["Keep calm — power assist is gone but steering and brakes still work heavy; coast to the shoulder","The wheels have locked — brace","Steering is gone forever","Slam the parking brake"],
    a:0,
    why:"Stalls kill the assistance, not the systems: the wheel still turns and the pedal still brakes, both demanding real muscle. Fighting the heaviness calmly to the shoulder beats any panic input.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf52", cat:"safety", form:"what-next", concept:"engine-stall",
    q:"After a stall you restart while still rolling in gear and the car lurches. What happens next?",
    choices:["Lurching is normal — keep going","Restarting in gear is correct","Shift to neutral (or park if stopped) before restarting — cranking in gear lunges the car","Turn the key longer"],
    a:2,
    why:"A starter motor in gear drives the wheels — that lurch can throw you into traffic or a curb. Neutral (or park at rest) plus foot brake makes every restart a non-event.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk16", cat:"parking", form:"scenario", concept:"exiting-parked-car",
    q:"Parked on a busy street, your passenger reaches for the door as a cyclist approaches from behind. What should happen?",
    choices:["Passengers decide for themselves","Warn them to hold — you're responsible for every door that opens into traffic","Open it for them quickly","Cyclists must dodge doors"],
    a:1,
    why:"Dooring liability lands on the vehicle's occupants, and the driver briefing passengers is part of the job. A shouted 'bike coming' plus the far-hand reach habit keeps every door from opening into traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk17", cat:"parking", form:"what-next", concept:"exiting-parked-car",
    q:"You fling your door open without checking and clip a passing cyclist. What happens next?",
    choices:["The cyclist pays for their speed","No harm if they stay up","Minor incident, drive on","You're typically at fault for dooring — plus injuries, a ticket, and a claim"],
    a:3,
    why:"Opening into traffic without looking is the driver's error in almost every state — fault, fine, and civil liability follow even when the rider 'should have' ridden wider. The check takes one second; the claim takes months.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk18", cat:"parking", form:"scenario", concept:"fire-hydrant-distance",
    q:"The only open curb on the block is directly in front of a hydrant, and 'it's just for a minute.' What's the rule?",
    choices:["Fine for quick stops","Fine with hazards on","No parking or stopping within about 15 feet — even for a minute, even occupied","Fine if you stay in the car"],
    a:2,
    why:"Hydrant clearances ban stopping, not just parking — hoses need the space whether you're in the car or not. 'Just a minute' is exactly when the fire call comes, and crews will run hose through your windows.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk19", cat:"parking", form:"what-next", concept:"fire-hydrant-distance",
    q:"You park 10 feet from a hydrant overnight and find a ticket at dawn. Can you fight it?",
    choices:["The ticket can't stand — 10 feet from a hydrant is inside the usual 15-foot clearance, so it was correctly written","Hydrants don't apply overnight","Tickets need a fire first","Curb paint decides everything"],
    a:0,
    why:"The 15-foot clearance runs around the clock — fires don't keep business hours, and faded paint doesn't void the rule. The only winning move was parking further down the block.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp23", cat:"speed", form:"scenario", concept:"fog-driving",
    q:"Fog closes in on the highway and brake lights bloom ahead in clusters. What's the pattern to avoid?",
    choices:["Speed up between clusters","Join the cluster for safety","Stop where you are","Slow early and space out with low beams — clusters of brake lights mean crashes forming"],
    a:3,
    why:"Fog pileups come from bunched cars at full speed finding stopped traffic — the cluster IS the warning. Shedding speed early and opening space keeps you out of the chain reaction.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp24", cat:"speed", form:"what-next", concept:"fog-driving",
    q:"In fog you follow the taillights ahead closely so you won't get lost. What happens next?",
    choices:["Taillight-following is recommended","If they brake or hit something, you arrive at full speed with zero margin — back off and navigate by the road edge","The leader knows the road","Fog lifts faster in groups"],
    a:1,
    why:"Taillights give direction but no stopping distance — drafting them borrows their visibility at double the risk. Dropping back and tracking the right-hand edge line keeps you oriented with room to stop.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw47", cat:"row", form:"scenario", concept:"four-way-stop-simultaneous",
    q:"Three cars arrive together at a 4-way stop — you on the left, one opposite, one on your right. What's the order?",
    choices:["Right goes, then opposite and you by arrival order — you, on the left, go last","All go at once carefully","Left goes first","Biggest first"],
    a:0,
    why:"Right-of-way flows rightward: the rightmost car leads, and the rest follow in turn. As the left car you're last — going early forces the very tie the rule exists to break.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw48", cat:"row", form:"what-next", concept:"four-way-stop-simultaneous",
    q:"At a 4-way stop the driver on your right waves you through first. You go. What happens next?",
    choices:["Politeness rules — always accept","Waves are legally binding","You move only when the way is truly clear — a wave doesn't stop their foot slipping or a third car jumping","Honk thanks and accelerate fast"],
    a:2,
    why:"A wave is courtesy, not control — the waver may still roll, and other approaches never saw the gesture. Accept it only as information, and enter when every approach is actually yielding.",
    sourceId:"us-dmv-handbooks-composite" },
  /* US transfer batch 3 — second and third variants for thin universal concepts,
     so each reaches 3 questions across 2+ forms and can genuinely evidence
     wording/form transfer (see js/mastery.js). */
  { id:"sg68", cat:"signs", form:"scenario", concept:"green-arrow-light",
    q:"You wait to turn left on a green arrow; it changes to a steady green ball while oncoming traffic keeps flowing. What changes?",
    choices:["Nothing — the arrow's protection continues","Your protected turn ended — yield to oncoming traffic and pedestrians before turning","Oncoming traffic must now stop for you","Turn immediately before the cycle ends"],
    a:1,
    why:"A green arrow grants a protected movement; a steady green ball does not. Once the arrow drops, you turn only through gaps in oncoming traffic, still yielding to pedestrians.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg69", cat:"signs", form:"what-next", concept:"green-arrow-light",
    q:"You are halfway through a left turn on a green arrow when the signal goes dark in a power flicker, then blinks yellow. What happens next?",
    choices:["The turn stays protected — finish fast","Reverse out of the intersection","You may have lost protection — yield to oncoming traffic and clear carefully","Treat it as a stop sign and wait for green"],
    a:2,
    why:"Protection exists only while the arrow shows it. A dark or flashing signal means the phasing may have changed — finish the turn only when oncoming lanes actually yield, and never back up in an intersection.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw49", cat:"row", form:"scenario", concept:"freeway-merge-priority",
    q:"Your acceleration lane is short and a truck holds the freeway's right lane beside you. Who goes first, and what do you do?",
    choices:["You do — merge in and force the gap","Freeway traffic has priority — adjust speed to slip in behind the truck, using the shoulder only as a last resort","Stop dead at the end of the ramp","Match the truck exactly and merge alongside"],
    a:1,
    why:"Merging traffic always yields to traffic already on the freeway. Adjust speed early for a gap behind the truck; stopping at the ramp end or squeezing alongside trades a merge problem for a collision.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw50", cat:"row", form:"what-next", concept:"freeway-merge-priority",
    q:"You cruise the freeway's right lane as a car enters from an on-ramp, matching your speed but slightly behind. What happens next?",
    choices:["Hold your lane and speed — the merger must fit around you; move left early only if the lane is clear and it helps","Speed up to block them","Brake hard to wave them in","Swerve onto the shoulder to make room"],
    a:0,
    why:"The legal duty sits with the merger, but a safe driver holds a predictable line and, when clear, moves left a lane early to open the gap. Speed games and shoulder swerves create the crash courtesy was meant to prevent.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw51", cat:"row", form:"scenario", concept:"headlight-flash-response",
    q:"Oncoming cars flash you twice, but your lights are already on low beam and your fog lamps are off. What is the sensible response?",
    choices:["Flash back angrily and keep driving","Your lamps may be misaimed, overloaded, or one is out — check them at the next stop instead of retaliating","Switch everything off to prove compliance","Speed up so fewer drivers meet you"],
    a:1,
    why:"Flashes usually mean dazzle, and dazzle with low beams on points at misaimed lamps, a heavy trunk tilting the nose up, or a failed bulb. A quick check at the next stop fixes it; flashing back fixes nothing.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw52", cat:"row", form:"what-next", concept:"headlight-flash-response",
    q:"You dim to low beams for an oncoming car, and the driver answers with a grateful tap of their own highs-to-lows. What happens next?",
    choices:["Nothing changes — both drivers can see again, so hold low beams until past each other","Switch back to highs immediately","Both cars stop to confirm","Turn on hazards to say thanks"],
    a:0,
    why:"The exchange worked: both drivers hold low beams until past each other, then highs can return when the road ahead is empty. Courtesy only counts if it lasts through the pass.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp25", cat:"speed", form:"scenario", concept:"freeway-entrance-ramp",
    q:"The entrance ramp has a red metering light with two cars queued ahead of you. What do you do?",
    choices:["Stop at the light, then go on green and accelerate to freeway speed before merging","Run the meter — it is advisory only","Stop and wait for a huge gap on the freeway","Crawl the whole ramp at 20, lights or not"],
    a:0,
    why:"Ramp meters are real signals: stop, then launch on green so you reach highway speed with space between you and the car ahead. Crawling or running the meter dumps a slow car into fast traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp26", cat:"speed", form:"what-next", concept:"freeway-entrance-ramp",
    q:"You accelerate down the ramp and see the merge lane is blocked by a stalled car with flashers on. What happens next?",
    choices:["Swerve left into freeway traffic immediately","Slow early, signal, and merge into the freeway lane before the blockage — stopped cars do not move for you","Stop behind the stalled car and wait for a tow","Pass it on the shoulder at speed"],
    a:1,
    why:"A blocked merge lane means you join the traffic lane itself, early and slowly, with a signal — freeway drivers may not see the stalled car in time to help. Waiting behind it or shoulder-passing at speed both end badly.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk20", cat:"parking", form:"scenario", concept:"highway-shoulder-stop",
    q:"A blowout forces you onto a narrow freeway shoulder with trucks passing inches away. What is the safest sequence?",
    choices:["Change the tire immediately on the traffic side","Pull as far off as possible, hazards on, stay belted inside, and call for help — exit away from traffic only if you must leave","Stand behind the car waving traffic over","Drive on the rim to the next exit at full speed"],
    a:1,
    why:"On a narrow shoulder the car is your cage: get fully off the lane, flashers on, belted, and call roadside help. A tire changed inches from trucks, or a body standing in the lane, is how stops become fatalities.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk21", cat:"parking", form:"what-next", concept:"highway-shoulder-stop",
    q:"Help is coming and you must rejoin the freeway from a short, gravel shoulder. What happens next?",
    choices:["Pull out the moment the lane looks empty — you have the right of way","Wait for a large gap, signal, accelerate hard on the shoulder, and merge at traffic speed","Re-enter at 25 mph so others can pass","Back up the shoulder for a longer run-up"],
    a:1,
    why:"Re-entering traffic yields and needs speed: a big gap, a signal, and hard acceleration to match the lane before merging. Crawling in or reversing on a shoulder invites the rear-end crash you just avoided.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf53", cat:"safety", form:"scenario", concept:"headlight-use-required",
    q:"At dusk you can still see the road clearly, so your lights stay off — but oncoming cars keep appearing late in your mirror. What is wrong?",
    choices:["Nothing — headlights are for your own vision only","Your headlights also make YOU visible: at dusk, in murk, or whenever judgment is needed, switch them on","Daytime running lights are illegal here","Only high beams count at dusk"],
    a:1,
    why:"Headlights are conspicuity devices, not just headlamps: other drivers judge distance and closing speed from your lights long before they resolve your car's shape. If you have to ask whether it is dark enough, it is.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf54", cat:"safety", form:"what-next", concept:"headlight-use-required",
    q:"You enter a long, lit tunnel at noon with sunglasses on and lights off. What happens next?",
    choices:["The tunnel lighting is enough — keep sunglasses and lights off","Remove the sunglasses, switch headlights on, and keep distance — tunnels hide stopped traffic and eyes adapt slowly","Stop at the tunnel mouth to adjust","Switch to high beams for the tunnel"],
    a:1,
    why:"Tunnels defeat sunglasses and dark-adapted eyes at once: lights on marks you for others, glasses off restores your contrast, and extra following distance covers the adaptation lag. High beams in a tunnel just bounce glare back at you.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf55", cat:"safety", form:"scenario", concept:"high-beam-dimming",
    q:"You follow a car at night on an empty highway, high beams on, about four seconds behind. The driver keeps tapping their mirror. What should you do?",
    choices:["Stay on highs — four seconds is plenty of distance","Dim to low beams: your highs fill their mirrors and cabin no matter the gap","Flash your highs to signal a pass","Pull alongside to get out of their mirror"],
    a:1,
    why:"High beams blinding through mirrors is the same dazzle as head-on — dim within about 300 feet when following, and sooner if the driver signals distress. Distance dilutes brightness far less than drivers assume.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf56", cat:"safety", form:"what-next", concept:"high-beam-dimming",
    q:"Over a blind hillcrest at night your high beams show empty road, then headlights pop over the crest toward you. What happens next?",
    choices:["Hold highs until you see their car fully","Dim to lows before the crest confrontation — their driver is blind exactly when alignment matters most","Look straight into their lamps to judge distance","Speed up to clear the crest first"],
    a:1,
    why:"A crest compresses the meeting time to a second or two, and your highs strike their eyes before either car is visible. Dimming early trades a moment of your own range for their ability to hold their lane past you.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw27", cat:"laws", form:"scenario", concept:"headphones-while-driving",
    q:"You take work calls on earbuds in both ears during your commute, volume low, and miss an ambulance siren until it is beside you. What does that tell you?",
    choices:["The siren was too quiet","Both-ears coverage blocks the directional hearing sirens rely on — switch to one earpiece or the car speakers","Low volume makes both-ears legal","Emergency vehicles should use louder sirens"],
    a:1,
    why:"Two covered ears destroy the stereo cues that locate sirens, horns, and crossing bells — which is why most states ban it. One earpiece for calls, or the car's own speakers, keeps the emergency audible and you legal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw28", cat:"laws", form:"what-next", concept:"headphones-while-driving",
    q:"A motorcyclist beside you wears a helmet headset in one ear and hears your horn in time to avoid your lane change. What happens next for a driver copying them with two earbuds?",
    choices:["The same awareness — earbuds and helmet speakers are equivalent","The driver misses cues the rider caught: one open ear preserves direction hearing that two sealed earbuds erase","Louder music compensates for the seal","Nothing differs; hearing plays no role in driving"],
    a:1,
    why:"The rider kept one ear on the world; the two-earbud driver sealed both. Direction hearing needs the contrast between ears — remove both inputs and sirens become a surprise instead of a warning.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw29", cat:"laws", form:"scenario", concept:"gps-while-driving",
    q:"Mid-trip your GPS reroutes through unfamiliar streets and the next turn is 400 feet away. Your phone sits in a dash mount. What is the legal move?",
    choices:["Grab the phone and retype the destination while rolling","Follow the voice prompts and glance at the mounted screen — never hold or program the device while moving","Pull onto the shoulder of the freeway to study the map","Close the app and navigate by memory"],
    a:1,
    why:"Mounted glance plus voice guidance is the lawful pattern; holding and typing while rolling is handheld distracted driving in most states. A missed turn costs minutes — programming at speed risks the whole trip.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw30", cat:"laws", form:"what-next", concept:"gps-while-driving",
    q:"You program the GPS at a red light, the light turns green mid-typing, and traffic behind starts moving. What happens next?",
    choices:["Finish typing — you started legally while stopped","Eyes up, phone down, drive: a green light ends the stop, and typing through it is driving distracted","Honk back while finishing the address","Throw the phone aside"],
    a:1,
    why:"A red light pauses driving; it does not license a typing session that runs through green. Put the device down the moment traffic moves — the address can wait one block, the intersection cannot.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr32", cat:"vulnerable", form:"scenario", concept:"group-of-cyclists",
    q:"A charity ride strings twenty cyclists along a blind curve with a double yellow line. You are late. What do you do?",
    choices:["Cross the double yellow to pass the whole line at once","Wait behind until sight distance opens, then pass the group completely in one legal move","Honk continuously until they single up","Thread between small gaps in the group"],
    a:1,
    why:"A double yellow plus a blind curve means no pass exists yet — crossing it into unseen oncoming traffic gambles twenty lives against your schedule. Patience until a legal zone, then one full pass of the whole group, is the only safe shape.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr33", cat:"vulnerable", form:"what-next", concept:"group-of-cyclists",
    q:"You begin a legal pass of a cycling group when the lead rider raises a hand and slows — a car pulls from a driveway ahead of them. What happens next?",
    choices:["Accelerate through before the driveway car moves","Hold back and let the group reform — their slowdown warns of a hazard you cannot see yet","Squeeze past on the shoulder","Honk the driveway car out of the way"],
    a:1,
    why:"A group's sudden slowdown is information: something ahead changed. Abandon the pass, drop back, and let the situation resolve — the riders' hand signal just saved you from meeting the driveway car head-on in their lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh20", cat:"vehicle", form:"scenario", concept:"frost-clearance",
    q:"Late for work, you scrape the driver's windshield only and pull out, side windows still white. At the first junction you must check the mirror — what is the consequence?",
    choices:["None — the front view is what matters","You cannot see the blind spot or the mirror at all, so the check is fiction — clear every window before moving","Open the window instead of clearing it","Drive faster so frost blows off"],
    a:1,
    why:"Mirrors and side glass are the junction check: frost turns them into white plastic. A peephole windshield leaves every lane change and turn a guess — full clearance takes minutes, a blind junction takes none.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh21", cat:"vehicle", form:"what-next", concept:"frost-clearance",
    q:"You cleared everything, but ten minutes later the inside of the windshield fogs white in traffic. What happens next?",
    choices:["Wipe a peephole with your sleeve and continue","Defroster and fan on hot, window cracked to equalise — restore full vision before the next manoeuvre","Switch the wipers to full","Turn the heater off to stop the fog"],
    a:1,
    why:"Interior fog is condensation from warm breath on cold glass: heat plus airflow plus a cracked window clears it in under a minute. A sleeve-wiped peephole smears and refogs exactly when traffic demands vision.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh22", cat:"vehicle", form:"scenario", concept:"fuel-reserve",
    q:"The low-fuel light glows on a rural highway at night, next services 30 miles, gauge reads an eighth of a tank. What is the right call?",
    choices:["Push on — gauges always under-read","Slow slightly, kill unneeded electrics, and take the first fuel well before the needle bottoms — an eighth is not a plan","Speed up to reach services sooner","Stop on the shoulder to conserve fuel"],
    a:1,
    why:"An eighth of a tank against 30 unknown miles is a gamble with a walk home in the dark. Ease off, cut the load, and refuel at the first chance — stations close, detours appear, and estimates lie.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh23", cat:"vehicle", form:"what-next", concept:"fuel-reserve",
    q:"You ignored the light and the engine sputters dead on an unlit road. What happens next?",
    choices:["Crank repeatedly until it catches","Hazards on, coast fully off the road, stay belted inside, and call for help — a dark stopped car is a target","Walk the center line for help","Leave the car unlocked with lights on"],
    a:1,
    why:"A fuel-starved stop is still a breakdown stop: off the lane, flashers on, visible and belted while help comes. Repeated cranking drains the battery you need for lights, and walking an unlit road multiplies the danger.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh24", cat:"vehicle", form:"scenario", concept:"headlight-failure",
    q:"At night your dashboard dims and oncoming drivers start flashing — your headlights have died but parking lights still glow. What do you do?",
    choices:["Keep driving on parking lights — you can still see a little","Pull fully off the road, hazards on: parking lights mark you but do not light the road, and motion without headlights is illegal","Drive faster to reach town before full dark","Follow the taillights ahead closely"],
    a:1,
    why:"Parking lights are position markers with almost no beam — at speed you outrun them in seconds. Stop fully off the road with flashers, then fix or call help; creeping on in the dark endangers everyone you meet.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh25", cat:"vehicle", form:"what-next", concept:"headlight-failure",
    q:"One headlight dies on a two-lane road and an oncoming driver starts a left turn across your path, reading you as a distant motorcycle. What happens next?",
    choices:["Hold speed — they will correct themselves","Slow, cover the horn and brake, and be ready to stop: single-light vehicles get misjudged exactly this way","Flash highs to prove you are a car","Swerve right onto the shoulder at speed"],
    a:1,
    why:"This is the classic single-headlight trap: you look narrow, far, and slow. Assume the turn is coming, shed speed early, and make noise — being right about priority helps nothing from inside their fender.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw31", cat:"laws", form:"recall", concept:"bike-lane-turns",
    q:"To turn right across a bike lane, you should:",
    choices:["Turn across it from your lane without entering it","Merge into the bike lane near the junction after yielding to riders, then turn from it","Stop in your lane until every bike passes","Turn from the far left lane"],
    a:1,
    why:"Turning across a bike lane from outside it hooks cyclists riding straight through. Merge into the lane near the turn after yielding, so bikes pass on your left or wait behind — the turn then starts from the lane itself.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw32", cat:"laws", form:"what-next", concept:"bike-lane-turns",
    q:"You signal right and start merging toward the bike lane when a cyclist accelerates to pass you on the right. What happens next?",
    choices:["Continue merging — you signalled first","Hold your lane, let the cyclist clear, then merge behind them — a signal never overrides a rider already there","Speed up to merge ahead of them","Honk to hold your claim"],
    a:1,
    why:"A signal announces intent; it grants no right to the space. The rider alongside owns the lane until past — forcing the merge squeezes them toward the curb or under your wheels.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk37", cat:"markings", form:"recall", concept:"center-turn-lane",
    q:"A center lane marked for two-way left turns may be used to:",
    choices:["Overtake a slow bus","Make left turns from either direction, entering just before the turn","Park while waiting for a gap","Drive through to skip a red light"],
    a:1,
    why:"The shared center lane exists only for left turns from either side — enter it just before turning. Passing, cruising, parking, or signal-skipping in it head you straight into oncoming turners.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk38", cat:"markings", form:"what-next", concept:"center-turn-lane",
    q:"You wait in the center turn lane for a gap when an oncoming car also swings into the lane facing you. What happens next?",
    choices:["Both turn simultaneously from the lane — it serves both directions at once","One of you must wait: the lane stages one turn at a time, so yield if they entered first, then complete your turn","Back out into your lane at speed","Flash highs until they leave"],
    a:1,
    why:"A two-way turn lane stages turns, it does not stack them side by side. First in turns first; the other holds position inside the lane — never backs into live traffic over a misunderstanding.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf57", cat:"safety", form:"scenario", concept:"child-restraint",
    q:"Your 5-year-old has outgrown the forward-facing seat by height but the car's adult belt cuts across their neck. What is the correct move?",
    choices:["Switch to the adult belt — height is what matters","Keep them in the outgrown seat until it breaks","Move them to a booster so the belt crosses hip and shoulder correctly, in the back seat","Put them in front where you can watch the belt"],
    a:2,
    why:"Belts are sized for adult bones: on small bodies they ride the neck and belly, causing the injuries they should prevent. A booster lifts the child into the belt's designed path — always in the back, away from airbags.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf58", cat:"safety", form:"what-next", concept:"child-restraint",
    q:"You buckle a child into a booster and the seat slides sideways on the leather cushion with every turn. What happens next?",
    choices:["Nothing — boosters are meant to move","Remove the booster; the belt alone is safer loose than a shifting seat","Re-install: press the booster flat, route the belt exactly as marked, and test for less than an inch of movement — a sliding seat aims the belt wrong","Wedge it with luggage"],
    a:2,
    why:"A booster that walks across the seat walks the belt off the child's hips with it. Re-seat it flat, belt it exactly as the guides show, and check the inch-test — installation is the restraint, not the plastic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw33", cat:"laws", form:"recall", concept:"driveway-exit",
    q:"Exiting a driveway or alley across a sidewalk, you must:",
    choices:["Stop before the sidewalk and yield to pedestrians and traffic","Roll across slowly without stopping","Honk to clear the sidewalk, then go","Block the sidewalk until traffic clears"],
    a:0,
    why:"The sidewalk has priority over an exiting vehicle: stop before it, yield to everyone on foot, then ease out yielding to road traffic too. Rolling through blind treats pedestrians as your lookout — they are not.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw34", cat:"laws", form:"what-next", concept:"driveway-exit",
    q:"You stop before the sidewalk at a driveway exit, but a hedge blocks your view of the road. A pedestrian waves you forward. What happens next?",
    choices:["Go — the pedestrian checked for you","Creep forward only to where you can see, still yielding to everyone — the wave covers the sidewalk, not the blind road","Skip the stop; visibility is hopeless anyway","Turn the radio down and listen, then pull out"],
    a:1,
    why:"A wave clears only what the waver sees — the sidewalk, not the hidden lane. Edge forward to visibility in stages, prepared to stop again; the exit is complete only when both the sidewalk and the road are actually clear.",
    sourceId:"us-dmv-handbooks-composite" },
  /* US transfer batch 4 — second and third variants for the next thin universal
     concepts, so each reaches 3 questions across 2+ forms and can genuinely
     evidence wording/form transfer (see js/mastery.js). */
  { id:"sp27", cat:"speed", form:"scenario", concept:"hill-crest-speed",
    q:"You crest a hill at full speed and find a farm tractor crawling just beyond it. What should you have done differently?",
    choices:["Nothing — the tractor should not be there","Slowed before the crest and stayed right, so your stopping distance fits inside your sight distance","Honked continuously over the crest","Moved left for a better view over the top"],
    a:1,
    why:"A crest hides the road beyond it, so speed must fit what you can see — slow early, hold right, and assume something slow or stopped waits on the far side. The tractor has every right to be there.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp28", cat:"speed", form:"what-next", concept:"hill-crest-speed",
    q:"You slow for a blind crest and spot a stalled car over the top with its flashers on. What happens next?",
    choices:["Swerve left around it immediately","Stop well short in your lane, hazards on, and wait or pass only when fully clear — your early slowdown bought exactly this option","Speed past before traffic builds","Push it off the road yourself"],
    a:1,
    why:"Slowing for the crest pays off the moment something is actually there: you stop short with room to assess instead of arriving at speed with nowhere to go. The hazard you imagined is the one you can now handle.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk22", cat:"parking", form:"scenario", concept:"hill-parking-rationale",
    q:"You park facing downhill with a curb on your right and skip turning the wheels. If the brakes fail, where does the car go?",
    choices:["Straight into the curb, safely","Backward into traffic","Forward into traffic — the wheels should have been turned toward the curb to catch it","Nowhere — parked cars never roll"],
    a:2,
    why:"Facing downhill, wheels turned toward the curb make the curb a backstop: a rolling car noses into concrete instead of traffic. Straight wheels downhill aim a runaway straight at the lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk23", cat:"parking", form:"what-next", concept:"hill-parking-rationale",
    q:"Parked uphill with no curb, you turned the wheels toward the road edge and set the brake. Months later the brake cable snaps overnight. What happens next?",
    choices:["The car rolls into traffic anyway","The turned wheels steer the rolling car off the road edge instead of into the lane — the backup works even years later","The transmission alone holds it","Nothing — cables never snap"],
    a:1,
    why:"Without a curb, wheels turned away from traffic make the shoulder the runaway's destination. The habit costs one second at parking time and works when every other system has failed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg70", cat:"signs", form:"scenario", concept:"hill-sign",
    q:"A yellow diamond shows a truck on a steep slope. Your loaded SUV starts the descent behind a semi. What is the correct setup?",
    choices:["Ride the brakes lightly all the way down","Slow before the grade, shift to a low gear, and let engine braking hold speed — saving the brakes for when you truly need them","Shift to neutral to save fuel","Pass the semi on the descent"],
    a:1,
    why:"Long descents cook friction brakes into fade: gear down first so the engine absorbs the grade, keeping the brakes cool and ready. Neutral surrenders that braking entirely.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg71", cat:"signs", form:"what-next", concept:"hill-sign",
    q:"Halfway down a posted grade you smell hot brakes and the pedal feels soft. What happens next?",
    choices:["Pump harder and keep descending","Pull into the next runaway ramp or turnout and stop to let the brakes cool — fade only gets worse downhill","Pour water on the wheels while rolling","Shift up for more speed to reach the bottom faster"],
    a:1,
    why:"Soft pedal plus hot smell is brake fade in progress: the only fix is stopping the heat input. A turnout or runaway ramp exists for exactly this moment — the bottom of the hill will still be there after a cooldown.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh26", cat:"vehicle", form:"scenario", concept:"horn-use",
    q:"A driver beside you drifts toward your lane, eyes down at their lap. Your horn's proper role is:",
    choices:["A long blast to punish the distraction","A short warning tap to alert them before the drift becomes a collision — then create space","Silence — horns never help","A greeting honk so they notice you"],
    a:1,
    why:"The horn is a collision-avoidance tool: one short tap buys the drifting driver's attention while you open an escape gap. Punishment blasts and social honks spend its meaning where no danger exists.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh27", cat:"vehicle", form:"what-next", concept:"horn-use",
    q:"You tap the horn at the drifting driver and they jerk the wheel away from you — straight toward a curb. What happens next?",
    choices:["Lay on the horn until they stabilise","Back off the horn, slow, and give them room to recover — the warning worked, and more noise now only adds panic","Speed past while they are distracted","Flash your highs repeatedly"],
    a:1,
    why:"A startled driver needs space, not a soundtrack: one tap delivered the message, and continued blasting while they overcorrect turns a warning into a cause. Slow, widen the gap, let the situation settle.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr34", cat:"vulnerable", form:"scenario", concept:"horse-and-rider",
    q:"A horse ahead shies sideways as you approach, ears pinned, rider fighting for control. What do you do?",
    choices:["Stop or crawl past at a walk's pace, wide and silent — a panicking horse is unpredictable in any direction","Honk to move it along","Rev gently to show your position","Pass quickly before it bolts"],
    a:0,
    why:"A frightened horse can spin, bolt, or kick with no warning — speed and noise decide which. Stopping, or creeping past wide at idle with no horn, is the only pass a panicking animal allows.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr35", cat:"vulnerable", form:"what-next", concept:"horse-and-rider",
    q:"You stop for a nervous horse and the rider raises a hand asking you to wait. What happens next?",
    choices:["Creep forward slowly to show you are waiting","Wait, engine idling quietly, until the rider signals or the horse settles — passing a held-up hand risks the exact spook you stopped to avoid","Honk once to acknowledge","Turn around and leave"],
    a:1,
    why:"The raised hand is traffic control by the person who knows the animal: waiting costs half a minute, while creeping forward restarts the panic. Move again only on the rider's wave, wide and slow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk39", cat:"markings", form:"scenario", concept:"hov-lane-marking",
    q:"Diamond-marked lane, posted 2+ persons, 7–9 AM. You drive solo at 8 AM beside a crawling queue. May you use it?",
    choices:["Yes — traffic is slow", "No — solo drivers stay out during posted hours no matter the congestion", "Yes, if you exit within a mile", "Yes, on motorcycles only — wait, you are in a car"],
    a:1,
    why:"Posted HOV hours bind everyone below the occupancy minimum, however tempting the empty lane looks — congestion is the reason the lane exists, not an exemption from it. Motorcycles usually qualify; solo cars never do.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk40", cat:"markings", form:"what-next", concept:"hov-lane-marking",
    q:"You enter the diamond lane solo at 8:55 AM and the posted hours end at 9. A patrol car sits ahead. What happens next?",
    choices:["You are fine — hours nearly over", "You are in violation until 9:00 sharp — exit the lane safely at the next permitted point, not across solid lines", "Stop in the lane until 9", "Speed through to beat the clock"],
    a:1,
    why:"Restrictions run to the posted minute, and patrols watch the boundary exactly because drivers test it. Leave at the next legal exit — crossing solid lines to escape adds a second violation to the first.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al27", cat:"alcohol", form:"scenario", concept:"implied-consent-refusal",
    q:"Stopped on suspicion of DUI, you refuse the breath test believing refusal leaves no evidence. What actually follows?",
    choices:["Nothing can happen without a test result", "Automatic license suspension under implied consent — plus officers can still testify to your driving, appearance, and field tests", "A thank-you and a ride home", "Only a small fine, no suspension"],
    a:1,
    why:"Refusal triggers its own suspension and never erases the stop: weaving, slurred speech, and failed field sobriety all testify without any number. The test measures; the driving already spoke.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al28", cat:"alcohol", form:"what-next", concept:"implied-consent-refusal",
    q:"You refused the test and the officer confiscates your license at the roadside. What happens next?",
    choices:["You keep driving until trial — the paper means nothing", "The suspension process starts immediately; driving on it adds criminal charges to an already bad night", "A friend vouches and the license returns", "Refusal expires at midnight"],
    a:1,
    why:"Roadside confiscation starts the administrative suspension clock, not a negotiation. Driving suspended converts a licensing penalty into a criminal one — arrange a ride and a lawyer instead.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg72", cat:"signs", form:"scenario", concept:"keep-right-sign",
    q:"A white sign with an arrow bending around a dot stands before a construction island at night. A tired driver reads it as optional. What does it command?",
    choices:["Pass on either side if clear", "Keep right of the obstruction — the island must stay on your left", "Stop before the island", "Turn around"],
    a:1,
    why:"Keep Right is a regulatory command, not advice: the obstruction stays left, you stay right. Reading it as optional at night is how islands get climbed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg73", cat:"signs", form:"what-next", concept:"keep-right-sign",
    q:"You obey the Keep Right sign and find a second, identical sign fifty feet later facing the opposite lane. What happens next?",
    choices:["The signs contradict — pick a side", "Each lane keeps its own right: stay right of the island in your lane and let oncoming traffic do the same in theirs", "Stop between the signs", "The second sign cancels the first"],
    a:1,
    why:"Paired Keep Right signs split traffic around one obstruction, each governing its own approach. They agree, not conflict — the island passes between the two streams.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk41", cat:"markings", form:"scenario", concept:"lane-end-merge",
    q:"Your freeway lane ends in 500 feet and the next lane is packed bumper-to-bumper. The worst choice is:",
    choices:["Merging early into a gap while you still have options", "Racing to the taper end to jump two cars ahead — forced merges at the pinch point cause the collisions and the rage", "Signalling your intent early", "Matching the neighbouring lane's speed"],
    a:1,
    why:"The taper end removes all options: a forced merge there makes someone brake hard or swerve. Early, signalled merges cost seconds; the race to the front costs the lane's whole flow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk42", cat:"markings", form:"what-next", concept:"lane-end-merge",
    q:"In crawling traffic everyone approaches the taper and the car beside you matches speed, blocking your merge. What happens next?",
    choices:["Force your nose in — they must yield", "Ease off, fall behind them, and merge into the space you just made — the zipper only works if someone yields first", "Straddle the line until they back down", "Honk continuously while merging"],
    a:1,
    why:"The zipper fails the moment both drivers insist: yielding first manufactures the gap the merge needs. A forced nose-in trades paint and tempers for a position worth three seconds.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk24", cat:"parking", form:"scenario", concept:"leaving-parking-space",
    q:"Parallel-parked on a busy street, you edge backward and see headlights approaching fast in the mirror. What is your duty?",
    choices:["Continue — you signalled, so the lane is yours", "Stop and wait: traffic in the lane has priority over a car leaving the curb, signal or not", "Pull out quickly before they arrive", "Honk them into slowing down"],
    a:1,
    why:"A signal requests space; it never takes it. The car leaving the curb yields to everything already moving — impatience here reverses into someone else's quarter panel and your liability.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk25", cat:"parking", form:"what-next", concept:"leaving-parking-space",
    q:"You wait at the curb with your signal on when a driver stops and waves you out — but a cyclist filters up your blind side. What happens next?",
    choices:["Pull out — the wave covers all hazards", "Stay put until the cyclist passes: the wave cleared the lane, not the blind spot you still must check", "Pull out fast to thank the waver", "Wave the cyclist through your car"],
    a:1,
    why:"A courtesy wave sees only what the waver sees — the lane, not your blind spot. The over-shoulder check is non-transferable: the cyclist you never looked for is the one you hit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw53", cat:"row", form:"scenario", concept:"left-turn-priority",
    q:"You wait to turn left on a green ball while an oncoming bus approaches going straight, and the driver flashes their lights at you. What should you do?",
    choices:["Turn — the flash means they yield", "Hold position: a headlight flash is not a legal yield, and a bus cannot stop quickly if you misread it", "Turn halfway and wait in the intersection", "Wave back and go"],
    a:1,
    why:"Flashes are ambiguous courtesy, not right-of-way — and buses need long stopping distances. Turn only on a genuine gap you judged yourself, never on someone else's lights.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw54", cat:"row", form:"what-next", concept:"left-turn-priority",
    q:"The light turns yellow as you wait to turn left, with oncoming traffic still flowing through. What happens next?",
    choices:["Turn immediately before red", "Wait for oncoming traffic to stop for the red, then clear the intersection promptly — never back up or sit through the cross traffic", "Reverse out of the intersection", "Stay until the next green"],
    a:1,
    why:"Yellow means the intersection is about to belong to cross traffic: let the last oncoming cars stop, then complete your turn and clear. Reversing or camping in the box trades your turn for everyone's gridlock.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw35", cat:"laws", form:"scenario", concept:"licence-points",
    q:"Two speeding tickets in a year have added points to your license and your insurer just raised your premium. What connects the two?",
    choices:["Nothing — insurance ignores tickets", "Points record the violations insurers price on: convictions raise premiums for years, and enough points suspend the license itself", "Premiums rise only after suspension", "Points expire when the fine is paid"],
    a:1,
    why:"Points are the shared language of courts, licensing agencies, and insurers: each conviction is priced into premiums for years while accumulating toward suspension. Paying the fine closes the ticket, not the record.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw36", cat:"laws", form:"what-next", concept:"licence-points",
    q:"A letter warns your license will suspend in 30 days unless you complete a driver-improvement course. What happens next?",
    choices:["Ignore it — warnings are automatic and expire", "Complete the approved course within the deadline and confirm the suspension is lifted — the state acts on the calendar, not your intentions", "Drive carefully for 30 days instead", "Change insurance companies"],
    a:1,
    why:"Point suspensions run on deadlines, not vibes: the course must be done and recorded before day 30. Careful driving afterward is wise, but only the completed requirement stops the suspension.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk43", cat:"markings", form:"scenario", concept:"line-colour-system",
    q:"On a two-lane road at night you notice the center line beside you is white, not yellow. What does that tell you?",
    choices:["The paint crew made an error", "You are on a one-way road or a divided lane: white divides same-direction traffic, so no oncoming cars share your pavement", "Passing is now legal everywhere", "The road is closed ahead"],
    a:1,
    why:"Line colour is direction information: yellow means opposing traffic may be inches away, white means everyone beside you travels your way. A white center line reclassifies the whole road in one glance.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk44", cat:"markings", form:"what-next", concept:"line-colour-system",
    q:"The white dashes beside you turn to a solid white line as an exit approaches. What happens next?",
    choices:["Cross it freely — white lines are advisory", "Stay in lane across the solid stretch: solid white discourages lane changes where merging traffic needs predictability", "Speed up to pass before the exit", "Stop and reconsider the route"],
    a:1,
    why:"Solid white marks places where lane changes endanger others — exits, tolls, intersections. Crossing it to gain a car length gambles against drivers who trusted the line to hold you.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw37", cat:"laws", form:"scenario", concept:"littering",
    q:"Your pickup bed carries loose branches to the dump, nothing tying them down. On the highway a branch flies into the car behind. Your liability:",
    choices:["None — road debris is the follower's problem", "Full: unsecured loads are illegal, and debris damage and injuries trace back to the loader", "Only if the branch was painted", "Only on weekends"],
    a:1,
    why:"Every load must be secured — tarped, tied, or contained. Flying debris kills following drivers yearly, and the law treats an unsecured load as the loader's negligence, not bad luck.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw38", cat:"laws", form:"what-next", concept:"littering",
    q:"You watch the car ahead toss a lit cigarette onto dry highway grass in August. What happens next, and what should you do?",
    choices:["Nothing — butts cannot start fires", "The butt can ignite the verge: drop back, note the car if safe, and report it — wildfire starts carry serious penalties", "Stop and stamp it out on the freeway", "Throw water from your window"],
    a:1,
    why:"A lit cigarette in dry grass is arson-scale recklessness with felony-grade consequences when it burns. Dropping back protects you from the smoke and the sudden braking ahead; reporting protects everyone else.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh28", cat:"vehicle", form:"scenario", concept:"loose-objects",
    q:"A heavy toolbox rides unsecured on your back seat. Traffic ahead brakes hard. What becomes of the toolbox?",
    choices:["It stays put — seat fabric grips it", "It keeps moving at your pre-braking speed and strikes the cabin with multiplied force — secure it in the trunk or footwell", "The seatbelt holds it", "Airbags catch cabin objects"],
    a:1,
    why:"Braking stops the car, not its contents: everything loose continues at speed, gaining destructive force with weight. The trunk exists partly to be the crash cage for cargo.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh29", cat:"vehicle", form:"what-next", concept:"loose-objects",
    q:"Your phone slides off the passenger seat under the brake pedal as you approach a red light. What happens next?",
    choices:["Bend down and grab it — the light is red", "Leave it: a phone under the pedal can jam the brakes when the light changes — stop fully, secure the car, then retrieve it", "Kick it aside while rolling", "Ask a passenger to dive for it immediately"],
    a:1,
    why:"Reaching under the pedals trades a phone for braking: a jammed pedal at green means no stop when traffic moves. Full stop, park brake, then fish it out — the phone survived the fall, it survives the wait.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al29", cat:"alcohol", form:"scenario", concept:"marijuana-and-driving",
    q:"A friend who smokes daily insists tolerance makes them safe to drive. The evidence says:",
    choices:["Tolerance restores reaction time fully", "Regular use still impairs lane tracking, following distance, and reaction — tolerance hides the feeling, not the deficit", "Daily users are exempt from DUID laws", "Only edibles impair driving"],
    a:1,
    why:"Tolerance dulls the subjective high while objective impairment persists — the oldest trap in drug-driving. Tests measure metabolites for days, but impairment is proven by the driving, high or not.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al30", cat:"alcohol", form:"what-next", concept:"marijuana-and-driving",
    q:"After smoking, a driver waits two hours, feels sober, and drives — then drifts across the center line. What happens next?",
    choices:["Feeling sober equals being sober — keep driving", "Pull over and stop: cannabis impairment outlasts the feeling of being high by hours, and the drift is the proof", "Open windows to finish sobering while driving", "Drive slower to compensate"],
    a:1,
    why:"Cannabis effects on tracking and reaction persist well past the perceived high — 'feeling fine' is the impairment talking. The center-line drift is data: the only safe response is to stop driving entirely.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al31", cat:"alcohol", form:"scenario", concept:"medicine-and-driving",
    q:"Your new allergy pills warn 'may cause drowsiness — do not drive.' The morning dose feels fine, so you drive to work. Legally you are:",
    choices:["Safe — prescribed and felt fine", "Driving impaired under DUI law if the drug affects you: labels warn because the impairment is real, felt or not", "Exempt on the first dose", "Covered if you drive slowly"],
    a:1,
    why:"DUI covers any impairing drug, prescription included — 'may cause drowsiness' is the manufacturer telling you the risk is documented. Feeling fine at dawn is no defense when reactions fade by noon.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al32", cat:"alcohol", form:"what-next", concept:"medicine-and-driving",
    q:"Halfway home on a new sleep aid taken last night, your eyelids grow heavy at 60 mph. What happens next?",
    choices:["Push through — home is close", "Exit or pull fully off the road immediately and rest: hangover impairment from sleep aids is documented impairment, and microsleeps do not negotiate", "Turn the radio up and open windows", "Drink coffee while driving"],
    a:1,
    why:"Residual sedation is still sedation, and heavy eyelids at speed are the final warning before a microsleep. Every countermeasure except stopping is folklore — the off-ramp nap is the only one that works.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg74", cat:"signs", form:"scenario", concept:"merge-sign",
    q:"The yellow diamond shows a side arrow joining your arrow from the right. Traffic beside you is dense. Your job as the through driver:",
    choices:["Hold speed and lane no matter what — mergers must solve it", "Ease off early or shift left to open a gap: merging is shared work between the entering driver and you", "Speed up to close gaps before mergers arrive", "Move onto the shoulder to help"],
    a:1,
    why:"The sign warns YOU, not just the merger: traffic will enter ahead, and the through driver's adjustment — a lifted foot or a lane change — is what converts a pinch point into a zipper.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg75", cat:"signs", form:"what-next", concept:"merge-sign",
    q:"Past the merge sign, a truck enters beside you and the driver clearly has not seen your car. What happens next?",
    choices:["Hold position to teach them to look", "Yield the space even though you have priority: being right and being hit are different outcomes, and the sign already told you this was coming", "Honk and accelerate past", "Swerve left without checking"],
    a:1,
    why:"Priority is a legal fact, not armor: a blind merger converts your right-of-way into a crash site unless you spend a little speed to buy the missing awareness. The sign's warning was your head start — use it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh30", cat:"vehicle", form:"scenario", concept:"mirror-limits",
    q:"Before a highway lane change you check the center and side mirrors — both clear — but skip the shoulder glance to save time. The risk:",
    choices:["None — modern mirrors cover everything", "A motorcycle or car sitting in the blind wedge mirrors cannot show — the glance is the check, not a formality", "Only for trucks", "Only at night"],
    a:1,
    why:"Mirrors leave a wedge beside each rear quarter exactly where a motorcycle fits whole. The shoulder glance exists because optics cannot bend — skipping it bets the lane change on empty geometry.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh31", cat:"vehicle", form:"what-next", concept:"mirror-limits",
    q:"Mid-glance you spot a motorcycle in the blind spot as you already start steering over. What happens next?",
    choices:["Complete the change quickly — commitment matters", "Straighten immediately and reclaim your lane: aborting a lane change is always allowed, finishing into a rider is not", "Brake hard in the new lane", "Wave the rider past while continuing over"],
    a:1,
    why:"A started lane change can always be un-started — the wheel turns both ways. Straightening costs pride; continuing costs the rider. Abort first, breathe, change lanes behind them.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf59", cat:"safety", form:"scenario", concept:"hot-car",
    q:"A dog naps in a parked car with windows cracked on an 85-degree day while the owner 'just runs in for a minute.' What is the reality?",
    choices:["Cracked windows keep it safe", "A minute is harmless", "Interior heat climbs to lethal levels in minutes even with cracked windows — the dog is in danger now", "Dogs tolerate heat better than people"],
    a:2,
    why:"Cracked windows barely slow the greenhouse climb: interiors pass 110+ fast, and dogs overheat sooner than humans because they cannot sweat. Minutes, not hours, is the killing scale.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf60", cat:"safety", form:"what-next", concept:"hot-car",
    q:"You spot a toddler alone in a parked car on a hot day, sweating and listless. What happens next?",
    choices:["Wait for the owner to return", "Call emergency services immediately and stay with the car — heatstroke kills children in minutes, and every state protects rescuers acting in good faith", "Break in silently", "Leave a note on the windshield"],
    a:1,
    why:"A listless child in a hot car is a medical emergency on a minute-scale clock: professionals first, presence second. Waiting or note-leaving spends the child's remaining margin on politeness.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al33", cat:"alcohol", form:"scenario", concept:"ignition-interlock",
    q:"After a DUI conviction a court orders an ignition interlock. A friend offers their car 'without the device' for errands. What is the truth?",
    choices:["Borrowing is fine — the order covers only your car", "Interlock orders typically cover ANY vehicle the offender drives: borrowing to evade extends the restriction and risks jail", "Short errands are exempt", "Out-of-state cars are exempt"],
    a:1,
    why:"Interlock restrictions follow the driver, not the dashboard: driving any unequipped vehicle violates the order and can mean custody plus a longer restriction. The friend lending the car may face charges too.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al34", cat:"alcohol", form:"what-next", concept:"ignition-interlock",
    q:"The interlock rejects a morning test after mouthwash, and the driver is late for work. What happens next?",
    choices:["Have a passenger blow into it", "Rinse, wait, and retest honestly: having someone else blow is a separate offense, and the device logs every attempt", "Disconnect the battery to reset it", "Drive without starting it"],
    a:1,
    why:"Circumvention — proxy blows, tampering, disconnection — is punished harder than the failed test it dodges, and the device's log testifies. Rinse out the mouthwash alcohol and pass legitimately instead.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr36", cat:"vulnerable", form:"recall", concept:"motorcycle-indicators",
    q:"A motorcycle ahead keeps its turn signal blinking for several blocks without turning. You should:",
    choices:["Assume a turn is coming and pull out ahead of it", "Honk until the rider cancels the signal", "Treat the signal as unreliable — most bike signals don't self-cancel, so read the rider's head checks and lane position instead", "Pass on the signal side at once"],
    a:2,
    why:"Most motorcycle signals don't self-cancel, so a blinking light is unreliable: read the rider's head checks and lane position before you act on any signal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr37", cat:"vulnerable", form:"what-next", concept:"motorcycle-indicators",
    q:"You're waiting to turn left across a motorcycle whose right signal blinks — but the rider's head stays left and the bike holds lane center. What next?",
    choices:["Hold your turn: the blinking signal is often meaningless, and the rider's head and line say straight ahead", "Turn quickly while the signal is on", "Trust the blinker over the rider", "Edge out to force them to decide"],
    a:0,
    why:"Hold the turn — on a bike the rider's head and line outrank a blinking signal that often means nothing. Turning across their path on a bad read is fatal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr38", cat:"vulnerable", form:"recall", concept:"motorcycle-lane-sharing",
    q:"Two motorcyclists ride side by side sharing one lane. As a car driver, you:",
    choices:["May squeeze between them to pass", "Must never enter their lane to share it — change lanes fully to pass, as you would for a car", "May follow inches behind one of them", "May use the shoulder to get by"],
    a:1,
    why:"Never share a lane with a motorcycle: each bike owns its full lane, so pass only with a complete lane change, exactly as you would for a car.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr39", cat:"vulnerable", form:"what-next", concept:"motorcycle-lane-sharing",
    q:"At a red light a rider waves you up to share their lane so you both fit. What next?",
    choices:["Accept — it helps everyone", "Ride the lane line beside them", "Creep past inside the lane", "Stay back or take the next lane: cars must never share a lane with a motorcycle, waved in or not"],
    a:3,
    why:"Stay back or take the next lane — a car must never share a motorcycle's lane, invitation or not. The rider misjudges your width, not their own.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr40", cat:"vulnerable", form:"recall", concept:"motorcycle-position-in-lane",
    q:"A motorcyclist keeps shifting position inside their own lane. Usually this means:",
    choices:["The rider is showing off", "They're staying visible, dodging slick spots, and keeping an escape path — expect movement and give them the full lane", "They're about to stop", "They want you to pass"],
    a:1,
    why:"Constant lane movement keeps the rider visible, off oil and grease, and near an escape path — expect it and give them the full lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr41", cat:"vulnerable", form:"what-next", concept:"motorcycle-position-in-lane",
    q:"A bike ahead drifts to the left third of its lane as you both near an intersection with a turning truck. What next?",
    choices:["Pass on the right immediately", "Honk to hold them in place", "Follow closer to block the truck", "Hang back and cover your brake: the rider is buying visibility and an escape path around the truck — don't steal either"],
    a:3,
    why:"Hang back and cover the brake: the rider moved for visibility and an escape path around the truck, and crowding them steals both.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr42", cat:"vulnerable", form:"recall", concept:"motorcycle-sharing-lane",
    q:"Following a motorcycle in traffic, you should:",
    choices:["Keep 3–4 seconds back and never share its lane — bikes can brake far harder than cars", "Tailgate; bikes stop slowly", "Share the lane to save space", "Ride in their blind spot"],
    a:0,
    why:"Keep 3–4 seconds back and never share the lane: motorcycles can brake far harder than cars, so tailgating one ends under it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr43", cat:"vulnerable", form:"what-next", concept:"motorcycle-sharing-lane",
    q:"Rain starts and the motorcycle ahead slows suddenly with no brake light you can see. What next?",
    choices:["Swerve around it", "Speed up to get clear of the spray", "Drop back to a full 4+ seconds and stay out of its lane: wet roads stretch everyone's stop, and the bike's small lamp is easy to miss", "Flash your brights at them"],
    a:2,
    why:"Drop back to 4+ seconds and stay out of its lane — wet roads stretch every stop and a bike's small brake lamp is easy to miss in spray.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr44", cat:"vulnerable", form:"recall", concept:"motorcycle-visibility",
    q:"Most car-motorcycle crashes happen because:",
    choices:["Bikes are always speeding", "Bikes run without lights", "Riders never signal", "Drivers look but fail to see the narrow profile — scan every intersection twice, specifically for two wheels"],
    a:3,
    why:"Drivers look but fail to see: the narrow profile vanishes in blind spots and clutter, so scan every intersection twice, hunting specifically for two wheels.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr45", cat:"vulnerable", form:"what-next", concept:"motorcycle-visibility",
    q:"You're about to turn left across two lanes at dusk and the far lane looks empty. What next?",
    choices:["Turn promptly to clear the junction", "Look twice for a motorcycle's single headlight before turning — one lamp in the gloom is easy to miss", "Trust the first glance", "Turn with your eyes on the exit"],
    a:1,
    why:"Look twice for the single headlight before turning: one lamp in the gloom is easy to miss, and left-turning cars are the classic motorcycle killers.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr46", cat:"vulnerable", form:"recall", concept:"parked-car-door-risk",
    q:"The 'door zone' beside parked cars is dangerous because:",
    choices:["Parked cars move suddenly", "It's always illegal to drive there", "Doors can swing open without warning — ride a door-width out, watch for occupants and front wheels turning", "Only taxis open doors"],
    a:2,
    why:"Doors swing open without warning, so ride a door-width out and watch for occupants and front wheels turning — both telegraph a door or a pull-out.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr47", cat:"vulnerable", form:"what-next", concept:"parked-car-door-risk",
    q:"You spot an occupant's head inside a parked car ahead and its brake lights glow. What next?",
    choices:["Slide a door-width left, slow, and cover the horn and brake: that driver may door you or pull out", "Hold speed and line — they see you", "Squeeze between it and traffic", "Stop and wait behind it"],
    a:0,
    why:"Slide a door-width left, slow, and cover horn and brake: an occupied car with brake lights glowing may door you or pull out at any second.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw55", cat:"row", form:"recall", concept:"narrow-road-priority",
    q:"On a single-track mountain road, a car climbing uphill meets your car coming down. You should:",
    choices:["Hold your line — downhill has priority", "Race to the wide spot first", "Stop and argue it out", "Yield: back to a wide spot or pull over, because restarting uphill is far harder — the climber keeps the right of way"],
    a:3,
    why:"Yield to the climber — restarting on an uphill grade is far harder, so the downhill car backs to a wide spot or pulls over.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw56", cat:"row", form:"what-next", concept:"narrow-road-priority",
    q:"Descending a narrow grade, you meet a truck laboring uphill with no wide spot behind you. What next?",
    choices:["Squeeze past on the cliff edge", "Reverse carefully to the last turnout and let the truck climb through — downhill yields, especially to heavy vehicles", "Make the truck reverse", "Turn around"],
    a:1,
    why:"Reverse to the last turnout and let the truck climb through: downhill yields, and a loaded truck cannot restart on the grade at all.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp29", cat:"speed", form:"recall", concept:"night-driving-risk",
    q:"At night you must slow down because:",
    choices:["Your stopping distance must fit inside your headlight range — overdriving your lights is the core night-driving killer", "Night air slows engines", "Tires grip less after dark", "Police watch more closely"],
    a:0,
    why:"Darkness shrinks what you can see to the reach of your beams — any speed you cannot shed inside that pool of light is borrowed against a hazard you have not met yet.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp30", cat:"speed", form:"what-next", concept:"night-driving-risk",
    q:"On a dark rural road your headlights show a stopped vehicle late, and you brake hard to avoid it. What next?",
    choices:["Resume speed — you proved your reactions", "Switch to high beams permanently", "Ease off until you could stop within what you can see: you just out-drove your lights, so slow to the range of your beams", "Drive by memory of the road"],
    a:2,
    why:"Ease off until you can stop within what you can see — that late stop proves you out-drove your lights, so slow to the range of your beams.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp31", cat:"speed", form:"recall", concept:"passing-and-speed-limit",
    q:"The car ahead does 55 in a 55 zone and you want to pass. Legally you:",
    choices:["May touch 65 briefly to complete the pass", "Must stay within 55 — the limit binds every lane, so a car already at the limit cannot be legally passed", "May exceed it on dotted yellow", "May exceed it if no police are visible"],
    a:1,
    why:"The limit binds every lane at all times: a car already traveling at it cannot be legally passed, so stay within 55 and stay behind.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp32", cat:"speed", form:"what-next", concept:"passing-and-speed-limit",
    q:"You start passing at the limit and the other driver speeds up, leaving you hung out in the oncoming lane. What next?",
    choices:["Floor it past the limit to finish", "Hold position until they yield", "Swerve back regardless", "Brake and fall back into your lane: never break the limit to win a pass someone else turns into a race"],
    a:3,
    why:"Brake and fall back into your lane: never break the limit to win a pass the other driver turns into a race — living to re-pass beats dying to finish.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg76", cat:"signs", form:"recall", concept:"no-left-turn-sign", signId:"noLeftTurn",
    q:"You approach an intersection posted with this sign. It means:",
    choices:["Left lane ends", "U-turns allowed", "Left turns are prohibited here — continue on and circle back instead", "Detour left"],
    a:2,
    why:"The slashed left arrow prohibits left turns here — continue on and circle back (three rights make a left) instead of turning illegally.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg77", cat:"signs", form:"what-next", concept:"no-left-turn-sign", signId:"noLeftTurn",
    q:"You reach the intersection and realize your destination needs the now-prohibited left. What next?",
    choices:["Go straight through, then circle the block with rights: the prohibited left never becomes legal just because you need it", "Turn anyway — need beats signs", "Stop and reverse", "Turn from the far-right lane"],
    a:0,
    why:"Go straight and circle the block with rights: a prohibited left never becomes legal because you need it, so route around it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg78", cat:"signs", form:"recall", concept:"no-parking-sign", signId:"noParking",
    q:"Curb parking on this block is governed by this sign. It means:",
    choices:["No parking — you may stop briefly to load, but you may not leave the vehicle", "5-minute parking", "No stopping at all", "Residents only"],
    a:0,
    why:"No parking means no leaving the vehicle — you may stop briefly to load or unload, but the car must stay attended.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg79", cat:"signs", form:"what-next", concept:"no-parking-sign", signId:"noParking",
    q:"Your passenger needs 'just a minute' in a shop on a no-parking stretch. What next?",
    choices:["Park and wait with hazards on", "Circle the block or find legal parking: waiting in the car under a no-parking sign still risks a ticket — and double-parking never fixes it", "Double-park with hazards", "Stop in the travel lane"],
    a:1,
    why:"Circle the block or find legal parking: sitting under a no-parking sign still risks a ticket, and double-parking with hazards fixes nothing.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg80", cat:"signs", form:"recall", concept:"no-passing-zone-sign", signId:"noPassingZone",
    q:"This pennant appears on the left shoulder ahead. It marks:",
    choices:["A school zone", "End of the no-passing zone", "A scenic overlook", "The start of a no-passing zone — stay right and do not cross the center line to pass"],
    a:3,
    why:"The left-side pennant marks the start of a no-passing zone: stay right and do not cross the center line until the zone ends.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg81", cat:"signs", form:"what-next", concept:"no-passing-zone-sign", signId:"noPassingZone",
    q:"A tractor crawls at 15 mph just past the pennant sign with a long line behind it. What next?",
    choices:["Pass on the shoulder", "Stay behind until the zone ends: the pennant means no passing even for slow farm equipment — patience beats a head-on", "Cross the solid line briefly", "Tailgate until it pulls off"],
    a:1,
    why:"Stay behind until the zone ends: the pennant bans passing even for crawling farm equipment — patience beats a head-on every time.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg82", cat:"signs", form:"recall", concept:"no-u-turn-sign", signId:"noUturn",
    q:"This sign faces you at the intersection. It tells you:",
    choices:["No U-turns here — find another way to reverse direction", "Left turns banned", "Roundabout ahead", "U-turns encouraged"],
    a:0,
    why:"The slashed U-turn arrow bans U-turns here — overshoot and reroute rather than spinning around illegally.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg83", cat:"signs", form:"what-next", concept:"no-u-turn-sign", signId:"noUturn",
    q:"You miss your turn where U-turns are prohibited. What next?",
    choices:["Continue to the next legal turnaround — a missed turn never licenses a prohibited U-turn", "Spin around quickly while clear", "Reverse down the street", "Stop and ask traffic to let you turn"],
    a:0,
    why:"Continue to the next legal turnaround: a missed turn never licenses a prohibited U-turn, so drive on and reroute.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg84", cat:"signs", form:"recall", concept:"one-way-sign", signId:"oneWay",
    q:"This arrow sign is posted at the corner. It means:",
    choices:["Merge ahead", "Two-way traffic", "Traffic on this street moves only in the arrow's direction — never enter against it", "Dead end"],
    a:2,
    why:"The ONE WAY arrow means traffic moves only in the arrow's direction — entering against it puts you head-on into everyone.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg85", cat:"signs", form:"what-next", concept:"one-way-sign", signId:"oneWay",
    q:"You turn a corner and face a ONE WAY arrow pointing straight at you. What next?",
    choices:["Continue — it may be a mistake", "Speed through before traffic comes", "Turn around in the intersection", "Stop, and back or turn out of the street immediately: you entered against the arrow and are head-on to all traffic"],
    a:3,
    why:"Stop and get out of the street immediately: against the arrow you are head-on to all traffic, so back out or turn around at once.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf61", cat:"safety", form:"recall", concept:"oncoming-headlight-glare",
    q:"Oncoming high beams hit your eyes on a dark road. You should:",
    choices:["Stare at the center line only", "Glance to the right edge of your lane and ease off the gas until your vision clears — never stare into the lights", "Close both eyes briefly", "Speed up to pass the glare faster"],
    a:1,
    why:"Glance to the right edge of your lane and ease off until your vision clears — staring into the lights burns your night vision for seconds.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf62", cat:"safety", form:"what-next", concept:"oncoming-headlight-glare",
    q:"A truck's brights stay on behind a hill crest and you can't see the road at all. What next?",
    choices:["Hold speed — it will pass", "Look at its lights to track it", "Pull toward the center for room", "Slow right down, track the right edge line, and flash your own beams once: blind means slow, not straight"],
    a:3,
    why:"Slow right down, track the right edge line, and flash once: fully blind means slow, not straight — hold your lane by its edge, not by hope.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf63", cat:"safety", form:"recall", concept:"oncoming-vehicle-drift",
    q:"An oncoming car drifts over the center line toward you. Your first move is:",
    choices:["Brake, steer right, and sound the horn — shrink the closing speed and get out of their path, never into the oncoming lane", "Swerve left around them", "Accelerate past", "Stop dead in your lane"],
    a:0,
    why:"Brake, steer right, and sound the horn: shrink the closing speed and escape right — never left into the oncoming lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf64", cat:"safety", form:"what-next", concept:"oncoming-vehicle-drift",
    q:"The drifting car keeps coming and the shoulder is a ditch. What next?",
    choices:["Meet it head-on at speed", "Swerve left into their lane", "Keep braking hard straight ahead and lay on the horn: a controlled stop in your lane beats any swerve into traffic or a ditch at speed", "Close your eyes"],
    a:2,
    why:"Keep braking hard straight ahead and lay on the horn: a controlled stop in your lane beats swerving into traffic or taking a ditch at speed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk26", cat:"parking", form:"recall", concept:"one-way-parking-side",
    q:"Parking on a one-way street, you may:",
    choices:["Park facing either direction anywhere", "Use the left curb only if no police watch", "Never use the left curb", "Use either curb as long as you face the direction of travel — the left curb is legal on a one-way street"],
    a:3,
    why:"On a one-way street either curb is legal as long as you face the direction of travel — the left curb is fair game, unlike on two-way streets.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk27", cat:"parking", form:"what-next", concept:"one-way-parking-side",
    q:"Both right-curb spots are taken on a one-way street but the left curb is open. What next?",
    choices:["Take the left-curb spot facing with traffic: one-way streets allow either side when you face the flow", "Double-park on the right", "Park facing oncoming flow on the left", "Block the driveway briefly"],
    a:0,
    why:"The left curb is legal parking on a one-way street, provided the car points with the flow — pass up the open spot only if you would rather keep circling.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk28", cat:"parking", form:"recall", concept:"parallel-parking-curb-distance",
    q:"After parallel parking, how do you know you're close enough to the curb?",
    choices:["Anywhere in the lane is fine", "Within 12–18 inches — about a foot, close enough to keep the lane clear but not scrape", "Touching the curb", "Over 3 feet out"],
    a:1,
    why:"Finish within 12–18 inches — about a foot: close enough to keep the lane clear for passing traffic, far enough not to scrape.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk29", cat:"parking", form:"what-next", concept:"parallel-parking-curb-distance",
    q:"You finish parallel parked nearly 3 feet from the curb on a test route. What next?",
    choices:["Leave it — distance doesn't matter", "Pull out and redo it: nearly 3 feet out blocks the lane and fails most road tests, which score the 12–18-inch finish", "Open the door to check", "Deflate a tire"],
    a:1,
    why:"Examiners score the finish, and three feet out fails it — a car that far from the curb is both a test fault and a sideswipe invitation, so take another run at the curb.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al35", cat:"alcohol", form:"recall", concept:"open-container-law",
    q:"Your passenger holds an open beer in the back seat while you drive sober. This is:",
    choices:["Fine — the driver is sober", "Illegal almost everywhere: open containers are banned in the passenger area for drivers and passengers alike", "Fine on highways", "Fine if the windows are down"],
    a:1,
    why:"The ban follows the container, not the drinker — an open bottle in the cabin breaks the law even when the driver has not touched a drop.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"al36", cat:"alcohol", form:"what-next", concept:"open-container-law",
    q:"A friend climbs in with an open bottle and says the trunk is full. What next?",
    choices:["Let them hold it carefully", "Pour it into a cup", "Hide it under the seat", "Refuse the ride until it's sealed and stowed in the trunk or locked compartment: an open bottle in the cabin is illegal however you hide it"],
    a:3,
    why:"Refuse until it's sealed and stowed in the trunk or a locked compartment: an open bottle in the cabin is illegal however you hide it — under a seat is still in the car.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp33", cat:"speed", form:"recall", concept:"passing-distance",
    q:"On a two-lane road at 55 mph, a safe pass typically needs:",
    choices:["Only a few car lengths of clear road", "About a third of a mile or more of clear road — enough to accelerate, pass, and return with room", "Just 3 seconds of empty lane", "No more than 100 feet"],
    a:1,
    why:"A two-lane pass burns distance fast: you must see far enough ahead to finish the whole move and get back before meeting oncoming traffic — when in doubt, abort the pass.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp34", cat:"speed", form:"what-next", concept:"passing-distance",
    q:"Halfway through a two-lane pass, an oncoming car appears sooner than you judged. What next?",
    choices:["Floor it to finish the pass", "Swerve onto the shoulder to squeeze by", "Hold your line and flash your lights", "Abort at once: brake and tuck back behind the passed car — a bad pass is survivable only if you give it up early"],
    a:3,
    why:"Once oncoming traffic appears, the pass is over: brake and tuck back behind the car you tried to pass, because finishing a doomed pass trades paint at combined speed.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk45", cat:"markings", form:"recall", concept:"passing-on-the-right",
    q:"A driver asks when moving past on the right is permitted. The answer:",
    choices:["Never, under any circumstance", "Only after midnight", "The road has two or more lanes in your direction, or the ahead vehicle is turning left — always in a real travel lane, never the shoulder", "Whenever you are in a hurry"],
    a:2,
    why:"Multi-lane roads and left-turning leaders open a legal right-side pass, but only in a marked travel lane — the shoulder is never a passing lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk46", cat:"markings", form:"what-next", concept:"passing-on-the-right",
    q:"The car ahead signals left at an intersection with one lane each way and no shoulder room. Traffic stacks up behind you. What next?",
    choices:["Squeeze past on the right via the shoulder", "Cross the double yellow to pass on the left", "Wait for the left-turning car to clear: with no second lane there is no legal right-side pass — patience, not the shoulder", "Back up and find another route"],
    a:2,
    why:"With a single lane each way, no legal pass exists: wait behind the left-turning car rather than inventing one on the shoulder or across the double yellow.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr48", cat:"vulnerable", form:"recall", concept:"pedestrian-against-signal",
    q:"A jaywalker steps off the curb mid-block, straight into your lane, while you hold a green light. You must:",
    choices:["Hold speed — the green gives you priority", "Honk and keep rolling", "Brake and yield: no right of way is worth a collision with a person on foot", "Swerve into oncoming traffic to miss them"],
    a:2,
    why:"Green or not, steel always yields to flesh: brake and give the jaywalker the road, because the pedestrian loses every collision regardless of who was right.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vr49", cat:"vulnerable", form:"what-next", concept:"pedestrian-against-signal",
    q:"The jaywalker freezes in your lane, panicked, looking the wrong way. What next?",
    choices:["Stay stopped until they commit to a direction: a frozen pedestrian may bolt either way, so wait them out", "Creep forward to hurry them along", "Swerve around them at speed", "Reverse back down the street"],
    a:0,
    why:"Stay stopped until the frozen pedestrian picks a direction: panic makes people dart without looking, so waiting them out beats guessing which way they'll jump.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg86", cat:"signs", form:"recall", concept:"pedestrian-crossing-sign", signId:"pedCrossing",
    q:"This yellow diamond shows a walking figure. It warns:",
    choices:["A school zone begins here", "No pedestrians are allowed", "An intersection lies ahead", "A pedestrian crossing lies ahead — slow, scan the sidewalks, and be ready to stop"],
    a:3,
    why:"The walking-figure diamond marks a crossing ahead: ease off, watch both sidewalks, and be ready to stop, because crosswalk pedestrians hold the right of way.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg87", cat:"signs", form:"what-next", concept:"pedestrian-crossing-sign", signId:"pedCrossing",
    q:"Just past this sign, a pedestrian stands at the curb making eye contact with you. What next?",
    choices:["Maintain speed — they have not stepped out", "Stop well back and let them cross: at a marked crossing the pedestrian has priority once they show intent", "Wave them across while rolling slowly", "Change lanes to pass them"],
    a:1,
    why:"Stop well back and yield: a pedestrian showing intent at a marked crossing has priority, and stopping early shields them from traffic in the next lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw39", cat:"laws", form:"recall", concept:"police-pull-over",
    q:"Blue lights flash behind you on a busy road with no shoulder in sight. You should:",
    choices:["Stop dead in your lane at once", "Drive on until you feel like stopping", "Signal, slow, and take the first safe side street or wide spot — then stop fully off the road, engine off, hands on the wheel", "Stop on the nearest bridge"],
    a:2,
    why:"Never stop where you block traffic or invite a rear-end: signal, roll to the first safe spot fully off the road, then hands on the wheel while you wait for instructions.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw40", cat:"laws", form:"what-next", concept:"police-pull-over",
    q:"Stopped, the officer approaches as darkness falls. What next?",
    choices:["Turn on the dome light, keep hands on the wheel, and move only when directed — officers read sudden reaches as threats", "Step out to meet the officer", "Dig out your documents before being asked", "Call out loudly through the closed window"],
    a:0,
    why:"Light the cabin and freeze your hands on the wheel: every sudden reach reads as a possible threat, so let the officer direct each move.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh32", cat:"vehicle", form:"recall", concept:"pre-drive-adjustment",
    q:"Why adjust seat, mirrors, and wheel before moving?",
    choices:["It warms up the engine faster", "It is logged for insurance", "Only shorter drivers need it", "Because every adjustment at speed steals eyes and hands — and a wrong seat position slows emergency pedal work"],
    a:3,
    why:"Adjustments cost attention you cannot spare at speed, and a seat too far back delays full braking by critical inches — set everything before the wheels roll.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh33", cat:"vehicle", form:"what-next", concept:"pre-drive-adjustment",
    q:"A mile down the road you realize the mirror shows mostly sky. What next?",
    choices:["Fix it now with a quick glance away", "Pull over or wait for a full stop, then adjust — no mirror is worth a stretch of blind road", "Lean your head to compensate", "Ignore it for the rest of the trip"],
    a:1,
    why:"Park the adjustment until the car is parked: a two-second mirror fix at 40 mph is over 100 feet of blind travel, so wait for a full stop.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw57", cat:"row", form:"recall", concept:"private-drive-yield",
    q:"Nosing out of an alley across a sidewalk, your first duty is to:",
    choices:["Road traffic only — the sidewalk is the pedestrian's lookout", "Yield to sidewalk users first, then to road traffic: entering vehicles give way to everything already there", "Nobody if you pull out quickly", "Only other cars, not people"],
    a:1,
    why:"Driveways and alleys sit at the bottom of the priority ladder: sidewalk users first, then every vehicle on the road — entering traffic yields to everything already there.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw58", cat:"row", form:"what-next", concept:"private-drive-yield",
    q:"A cyclist rides along the sidewalk toward your driveway exit, staring at their phone. What next?",
    choices:["Pull out — their distraction is not your problem", "Honk and go", "Stop before the sidewalk and wait: exiting drivers yield to sidewalk traffic even when the other person is not paying attention", "Edge out to block them"],
    a:2,
    why:"Stop short of the sidewalk and wait: your yield duty does not shrink because the cyclist is distracted — exiting vehicles always give way to sidewalk traffic.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk47", cat:"markings", form:"recall", concept:"railroad-crossbuck",
    q:"A crossbuck plaque reads '3'. This tells you:",
    choices:["Stop three times before crossing", "Three trains are approaching", "The speed limit is 30", "Three tracks cross here — check every one, since a train can hide behind another in either direction"],
    a:3,
    why:"The number counts tracks, not trains: with three rails to watch, a passing train can mask another coming the other way — look down all of them before crossing.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk48", cat:"markings", form:"what-next", concept:"railroad-crossbuck",
    q:"One freight clears the crossing but the lights keep flashing. What next?",
    choices:["Cross immediately behind it", "Wait: a second train may be hidden behind the first — stay put until the lights stop and you can see all tracks clear", "Drive around the gate", "Follow the car ahead closely across"],
    a:1,
    why:"Stay put while the lights flash: the classic multi-track killer is the second train hidden behind the first, so wait for silence and a clear view down every track.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg88", cat:"signs", form:"recall", concept:"railroad-crossing-response",
    q:"Gates are down and lights flash, but no train is visible yet. You must:",
    choices:["Stop 15–50 feet back and wait until the lights stop and the gates rise — trains close faster than they look", "Weave around the gate while clear", "Park on the tracks to see down the line", "Tailgate a truck across"],
    a:0,
    why:"Stop well back and wait out the gates: trains arrive faster than they appear, and going around the barrier is both illegal and frequently fatal.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg89", cat:"signs", form:"what-next", concept:"railroad-crossing-response",
    q:"Your car stalls on the tracks with a train horn sounding. What next?",
    choices:["Keep cranking the starter until it catches", "Get out immediately, move away from the tracks at an angle, and call for help — never stay in the car", "Run down the tracks toward the train", "Wave other cars around to push you"],
    a:1,
    why:"Abandon the car at once and get clear of the rails at an angle: no vehicle is worth a life, and staying inside turns a stall into a tragedy.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg90", cat:"signs", form:"recall", concept:"railroad-crossing-sign", signId:"railCrossing",
    q:"This round yellow sign with an X and 'RR' means:",
    choices:["A roundabout lies ahead", "A rest area lies ahead", "A railroad crossing lies ahead — slow, look and listen, and cross only when you can clear completely", "A weigh station lies ahead"],
    a:2,
    why:"The round advance sign warns the tracks are coming: slow early, look both ways, and only cross when the whole vehicle can clear the far side.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg91", cat:"signs", form:"what-next", concept:"railroad-crossing-sign", signId:"railCrossing",
    q:"Traffic ahead is stopped with cars sitting on the tracks past this sign. What next?",
    choices:["Join the line — it will clear soon", "Honk the line forward", "Cross via the shoulder to get past", "Stop before the tracks and wait for room on the far side: never enter unless your full vehicle fits beyond the rails"],
    a:3,
    why:"Stop before the rails and wait for far-side room: Queuing onto the tracks bets your life that the line moves, so stay off until your full vehicle fits beyond them.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk49", cat:"markings", form:"recall", concept:"raised-pavement-markers",
    q:"Blue raised markers in the center of the road mark:",
    choices:["A fire hydrant location — so crews can find water at night", "A school zone boundary", "A toll lane entrance", "A bike lane crossing"],
    a:0,
    why:"Blue markers flag a nearby fire hydrant location so crews can find water at night — yellow marks left and center lines, white marks lane lines, and red facing you means wrong way.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk50", cat:"markings", form:"what-next", concept:"raised-pavement-markers",
    q:"At night you notice red reflectors staring back from the lane markers ahead. What next?",
    choices:["Continue — marker colors vary by county", "Pull off safely and turn around: red facing you means you are driving against traffic, often up an exit ramp", "Speed up to clear the section", "Switch to high beams and press on"],
    a:1,
    why:"Red markers face wrong-way drivers: you are likely entering an exit ramp against flow, so get off the roadway safely and turn around before meeting traffic head-on.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw41", cat:"laws", form:"recall", concept:"reckless-driving",
    q:"Which behavior can earn a reckless-driving charge even with no crash?",
    choices:["Missing one turn signal", "Driving 2 mph over once", "An older vehicle with loud exhaust", "Willful disregard for safety — racing, extreme speed, aggressive weaving"],
    a:3,
    why:"Recklessness is about willful disregard — racing or violent weaving qualifies on its own, and it carries misdemeanor penalties with possible jail even when nobody gets hit.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw42", cat:"laws", form:"what-next", concept:"reckless-driving",
    q:"Another driver challenges you to race from the light. What next?",
    choices:["Let them launch alone: street racing is reckless driving — jail, fines, and impound ride along win or lose", "Race to the next light only", "Chase them to photograph the plate", "Match their speed to shame them"],
    a:0,
    why:"Let them go: a street race risks jail, fines, and impound for both drivers, so your license is never the wager — arrive late rather than arrested.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg92", cat:"signs", form:"recall", concept:"regulatory-vs-warning",
    q:"An orange diamond sign ahead means:",
    choices:["A permanent traffic regulation", "A construction or maintenance zone warning — slow and follow the work-zone directions", "A scenic route turnoff", "A parking area ahead"],
    a:1,
    why:"Orange is the construction color: it warns of work zones where lanes shift, workers stand close, and fines often double — slow down and obey the posted work-zone signs.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg93", cat:"signs", form:"what-next", concept:"regulatory-vs-warning",
    q:"You cannot read a yellow diamond yet, but its color already tells you to:",
    choices:["Stop immediately", "Treat it as law like a white sign", "Slow and prepare for a hazard ahead — yellow warns before you can read the details", "Ignore it until it becomes legible"],
    a:2,
    why:"Yellow means warning: ease off and get ready for the hazard — curves, merges, crossings — before the words resolve.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh34", cat:"vehicle", form:"recall", concept:"reversing-camera",
    q:"A backup camera's biggest blind spots are:",
    choices:["Directly behind the bumper at ground level — low children, pets, and short posts hide below the lens", "The sky above the car", "The dashboard reflection", "Oncoming traffic ahead"],
    a:0,
    why:"The lens misses low ground right behind the bumper — exactly where small children and pets stand — so cameras assist but never replace mirrors and a look back.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"vh35", cat:"vehicle", form:"what-next", concept:"reversing-camera",
    q:"The camera shows clear but you hear a shout behind the car. What next?",
    choices:["Keep reversing — the screen is clear", "Stop at once and look: cameras miss edges, corners, and glare blind spots, so a shout beats the screen", "Reverse faster to clear the zone", "Turn up the radio to hear better"],
    a:1,
    why:"Stop and look: camera edges, corners, and sun glare all hide hazards the screen will not show, so a shout means foot on the brake, not trust in the lens.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw59", cat:"row", form:"recall", concept:"reversing-yield",
    q:"Two cars back out of opposite spaces at the same time. Who yields?",
    choices:["The car further out of its space", "Both must yield to through traffic — and to each other, so whoever spots the other first stops", "The newer vehicle", "Neither — horns decide"],
    a:1,
    why:"Backing vehicles never hold right of way: both yield to everything moving through the aisle, and when two back at once, whoever spots the other first stops.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw60", cat:"row", form:"what-next", concept:"reversing-yield",
    q:"Backing out, a shopping cart rolls behind you while a car approaches in the aisle. What next?",
    choices:["Stop and wait: you yield to all aisle traffic and pedestrians, so hold until the lane is truly clear", "Back out fast to beat the approaching car", "Honk the cart out of the way", "Open the door for one look, then go"],
    a:0,
    why:"Stop and hold: a reversing car yields to everyone — the approaching vehicle, the pedestrian chasing the cart, all of it — until the aisle is genuinely clear.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw43", cat:"laws", form:"recall", concept:"right-turn-on-red",
    q:"A 'NO TURN ON RED' sign faces you at the red light. You must:",
    choices:["Stop, then turn anyway — signs are advisory", "Wait for the green light: a posted ban removes right-on-red entirely", "Turn from whichever lane is open", "Go only when it turns yellow"],
    a:1,
    why:"The sign cancels the permission: at that intersection red means red until green, with no stop-and-go exception.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw44", cat:"laws", form:"what-next", concept:"right-turn-on-red",
    q:"No sign bans it; you have stopped fully and the way looks clear. What next?",
    choices:["Roll through without fully stopping", "Turn without checking for pedestrians", "Yield to pedestrians and cross traffic, then turn: the full stop plus the double yield is the whole maneuver", "Wait for green anyway"],
    a:2,
    why:"Stop, yield twice, then turn: pedestrians first, then cross traffic — rolling the stop or skipping either yield is the classic red-light ticket.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw61", cat:"row", form:"recall", concept:"right-turn-pedestrian-yield",
    q:"Turning right on green with pedestrians still in the far half of the crosswalk, you should:",
    choices:["Thread through behind them", "Honk to hurry them along", "Swing wide into the far lane", "Hold behind the line until your path is clear — turning vehicles yield the whole crossing"],
    a:3,
    why:"Turning traffic yields the entire crossing: wait behind the line until your path is fully clear, because pedestrians change pace and direction mid-crosswalk.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw62", cat:"row", form:"what-next", concept:"right-turn-pedestrian-yield",
    q:"A runner enters the crosswalk from behind a parked van as you start your right turn. What next?",
    choices:["Complete the turn — you are committed", "Stop mid-turn if needed and yield: hidden entrances are why turning cars wait and watch, not squeeze", "Speed up to clear the crossing", "Wave them back to the curb"],
    a:1,
    why:"Stop and yield even mid-turn: parked vans hide entering pedestrians, which is exactly why turning drivers watch the whole crossing instead of squeezing through.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw63", cat:"row", form:"recall", concept:"roundabout-entry-yield",
    q:"At a yield-marked roundabout entry with steady circulating traffic, you should:",
    choices:["Force your way into the circle", "Stop and wait permanently", "Wait at the yield line for a safe gap, then enter right of the island — circulating traffic never yields to you", "Enter left of the island"],
    a:2,
    why:"The yield line is a promise: circulating traffic keeps priority, so wait for a real gap and enter to the right of the island, moving counterclockwise.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw64", cat:"row", form:"what-next", concept:"roundabout-entry-yield",
    q:"A large truck beside you enters the roundabout at the same moment. What next?",
    choices:["Race it to your exit", "Hang back and give it the full lane: trucks straddle lanes in the circle, so never drive alongside one inside", "Pass it inside the circle", "Stop inside the circle to let it pass"],
    a:1,
    why:"Hang back and give the truck the whole circle: long vehicles straddle lanes around the island, and riding alongside one leaves you nowhere when it needs your lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg94", cat:"signs", form:"recall", concept:"roundabout-sign", signId:"roundabout",
    q:"This circular-arrow sign ahead means:",
    choices:["A traffic circle lies ahead — slow down and prepare to yield to vehicles already circulating", "A sharp curve lies ahead", "A one-way street begins", "A detour begins"],
    a:0,
    why:"The circular arrows announce a roundabout: ease off early, pick your lane, and be ready to yield at the entry line to traffic already in the circle.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg95", cat:"signs", form:"what-next", concept:"roundabout-sign", signId:"roundabout",
    q:"You miss your exit inside the roundabout. What next?",
    choices:["Stop and reverse to the exit", "Cut straight across the island", "Circle again: never stop or reverse in a roundabout — take another lap and exit cleanly", "Pull over inside the circle"],
    a:2,
    why:"Take another lap: stopping or reversing in the circle endangers everyone behind you, while one more loop costs seconds and keeps every bumper intact.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw65", cat:"row", form:"recall", concept:"school-bus-divided",
    q:"A painted median — no raised barrier — separates you from a stopped school bus with reds flashing. You must:",
    choices:["Stop: paint is not a median, so both directions stop like an undivided road", "Proceed normally past the bus", "Stop only if children are visible", "Speed up to clear the zone"],
    a:0,
    why:"Only a raised median or physical barrier excuses oncoming traffic — painted lines do not divide the road, so both directions stop exactly as on an undivided street.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw66", cat:"row", form:"what-next", concept:"school-bus-divided",
    q:"A raised concrete median separates you from the stopped bus, but children gather near your side. What next?",
    choices:["Maintain speed — the median excuses you", "Slow and stay alert: the median lifts the legal stop, not the duty of care around children near the road", "Stop in the travel lane", "Honk to scatter them"],
    a:1,
    why:"Slow and cover the brake: the barrier removes the stop requirement, never the danger — children near any roadside deserve a slow, watchful pass.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw67", cat:"row", form:"recall", concept:"school-bus-undivided",
    q:"On an undivided road, a school bus stops with yellow lights flashing (not yet red). You must:",
    choices:["Speed up to pass before red", "Slow and prepare to stop — yellow means reds and children are seconds away", "Stop dead instantly", "Pull alongside the bus"],
    a:1,
    why:"Yellow on a bus is the final warning: slow at once and prepare to stop, because red — and children in the road — follow within seconds.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw68", cat:"row", form:"what-next", concept:"school-bus-undivided",
    q:"Stopped for the bus, its reds switch off and the stop arm folds. What next?",
    choices:["Go immediately at full speed", "Wait for the bus to move first, then follow", "Check for children still crossing, then proceed with caution: the all-clear is lights off plus a clear road, not lights off alone", "Honk the bus forward"],
    a:2,
    why:"Look for stragglers before rolling: the all-clear is lights off plus an empty road, since the last child often crosses seconds after the arm folds.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg96", cat:"signs", form:"recall", concept:"school-crossing-vs-zone", signId:"schoolCrossing",
    q:"This pentagon sign shows walking figures but no crosswalk lines. It means:",
    choices:["A marked school crossing", "A closed school", "A school zone ahead — slow, scan for children, and obey the posted school speed limit", "A bus-only lane"],
    a:2,
    why:"Walking figures without the crosswalk mark the school zone itself: reduce speed, scan both sides, and expect the lower school-zone limit when signs post it.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg97", cat:"signs", form:"what-next", concept:"school-crossing-vs-zone", signId:"schoolCrossing",
    q:"Cars ahead stop inside the school zone though you see no children. What next?",
    choices:["Pass them — no children are visible", "Honk them forward", "Pull around via the bike lane", "Stop behind them and wait: cars stopped in a school zone may hide crossing children — never pass a stopped car there"],
    a:3,
    why:"Stop behind them and wait: a halted car in a school zone often screens crossing children, so passing it risks the very crash the zone exists to prevent.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf65", cat:"safety", form:"recall", concept:"brake-failure",
    q:"The pedal sinks to the floor with no braking on a descent. You should:",
    choices:["Yank the parking brake fully at once", "Pump the pedal, downshift for engine braking, then ease the parking brake on gradually while steering to a run-off", "Kill the engine immediately", "Shift to neutral and coast it out"],
    a:1,
    why:"Pump the pedal for residual pressure, downshift to let the engine drag speed off, then feed the parking brake on gradually while steering toward a run-off — cutting the engine kills power steering and can lock the wheel.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf66", cat:"safety", form:"what-next", concept:"brake-failure",
    q:"Pumping and downshifting barely slow the car and a red light looms ahead. What next?",
    choices:["Close your eyes and brace", "Swerve into oncoming lanes", "Keep speed and honk", "Rub speed off on the curb or guardrail and steer for an open run-off — a sideswipe beats an intersection T-bone"],
    a:3,
    why:"When pedal and gears are not enough, trade paint deliberately: rub the curb or rail to bleed speed and aim for open space, because a scraping stop beats blasting a red light at full pace.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw45", cat:"laws", form:"recall", concept:"crash-protocol",
    q:"After any crash with injuries, the legal order of duties is:",
    choices:["Leave and report tomorrow", "Move the injured first, then call", "Secure the scene, call 911, then aid the injured without moving them unless danger threatens", "Direct traffic from the lane"],
    a:2,
    why:"Secure the scene so you do not manufacture a second crash, summon professionals with the call, then aid without spinal-risk moves unless fire or traffic forces the move.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw46", cat:"laws", form:"what-next", concept:"crash-protocol",
    q:"You stop for a crash and fuel is pooling under a tilted car with someone inside. What next?",
    choices:["Get them out now and well clear: fire risk overrides the don't-move rule — then call 911 from a safe distance", "Wait for the ambulance regardless", "Move them gently back into the seat", "Stand in the lane to wave traffic off"],
    a:0,
    why:"Pooling fuel plus a trapped occupant is exactly the danger that overrides the don't-move rule: drag them clear, get everyone back, and call from safety.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk30", cat:"parking", form:"recall", concept:"curb-colours",
    q:"A curb painted YELLOW typically means:",
    choices:["Commercial loading or limited passenger loading — check the posted signs for hours", "Free all-day parking", "Disabled parking", "No stopping ever"],
    a:0,
    why:"A yellow curb is a loading zone: brief stops to load goods or passengers inside the posted hours, never all-day parking — red bans stopping entirely, white allows seconds-long pickup, blue needs a placard.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk31", cat:"parking", form:"what-next", concept:"curb-colours",
    q:"The only open curb is WHITE and you'll 'just be a minute' grabbing coffee. What next?",
    choices:["Park — white means all-day", "Park with hazards on", "Keep moving: white allows only seconds-long passenger pickup, not a coffee run — park legally instead", "Double-park beside it"],
    a:2,
    why:"White means active passenger loading measured in seconds, not minutes: a coffee run from a white curb earns the ticket the zone was painted to write.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk32", cat:"parking", form:"recall", concept:"curb-distance",
    q:"Why does the 12–18 inch curb rule exist?",
    choices:["To keep gutters clean", "To slow traffic", "To look tidy", "Because a wider gap steals the travel lane — beyond 18 inches you mimic double-parking and invite sideswipes"],
    a:3,
    why:"The gap is a lane-sharing bargain: hug the curb within 12–18 inches so the street keeps its full travel lane, because drifting wider turns your parked car into a chicane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk33", cat:"parking", form:"what-next", concept:"curb-distance",
    q:"You parallel-park 2 feet from the curb on a narrow street and a bus squeezes past. What next?",
    choices:["Stay — buses can manage", "Repark tighter within 12–18 inches: at 2 feet out on a narrow street you force every wide vehicle into the oncoming lane", "Move to the middle of the street", "Leave the car and hurry back later"],
    a:1,
    why:"Repark against the curb: two feet out on a narrow street pushes buses and trucks head-on into opposing traffic, so tuck back inside the 12–18 inch window.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw47", cat:"laws", form:"recall", concept:"emergency-vehicles",
    q:"A fire truck approaches from behind on a two-lane road with no shoulder. You should:",
    choices:["Stop dead where you are", "Speed up to outrun it", "Pull as far right as safely possible and stop — even partly onto a driveway or wide spot — until it passes", "Follow it closely through traffic"],
    a:2,
    why:"With no shoulder, use whatever safe space exists — driveway mouth, wide verge, side street — pull right and stop until the rig is fully past, because tailgating its wake is illegal and deadly.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"lw48", cat:"laws", form:"what-next", concept:"emergency-vehicles",
    q:"Stopped for the rig, you realize you're blocking a side street it might turn into. What next?",
    choices:["Stay — you already stopped", "Back up quickly", "Roll forward enough to clear the side street if you can do it safely, then stop again: never gift-wrap an intersection for a turning fire truck", "Drive away"],
    a:2,
    why:"If you can clear the mouth safely, do it: a stopped car plugging the exact turn a ladder truck needs costs the emergency its seconds — then stop again and wait.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp35", cat:"speed", form:"recall", concept:"following-distance-seconds",
    q:"Rain starts hammering the highway. Your following gap should become:",
    choices:["1 second — traffic is slower anyway", "Unchanged from dry conditions", "Tailgate with lights on", "At least 4 seconds: wet pavement doubles stopping distance, so stretch the dry 3-second rule"],
    a:3,
    why:"Wet roads stretch braking far past dry distance: grow the 3-second dry rule to 4 seconds in rain — 6 or more on snow and ice — because the car ahead can always stop shorter than you.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sp36", cat:"speed", form:"what-next", concept:"following-distance-seconds",
    q:"A tailgater glues to your bumper at 60 mph. What next?",
    choices:["Slow gradually and grow your own forward gap: with a tail on you, your cushion must come from ahead — never brake-check", "Brake-check them", "Speed up to lose them", "Swerve onto the shoulder"],
    a:0,
    why:"Ease off and open space ahead: a tailgater steals your rear cushion, so rebuild margin in front — braking hard with someone glued behind manufactures the pileup.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk51", cat:"markings", form:"recall", concept:"gore-area",
    q:"A gore area is painted with:",
    choices:["Solid lane lines", "Diagonal stripes or chevrons forming a neutral island between diverging paths — never to be driven on", "Parking boxes", "Crosswalk bars"],
    a:1,
    why:"The diagonal striping marks a neutral island where two paths split: it exists precisely because neither stream should be there, so crossing it is both illegal and a head-on bet.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"mk52", cat:"markings", form:"what-next", concept:"gore-area",
    q:"Traffic forces you onto the gore at speed with nowhere to go. What next?",
    choices:["Stop dead on it", "Cut hard left across lanes", "Hold your line, ease off, and rejoin the correct lane when a safe gap opens: the gore bought you no rights, so exit it without sudden moves", "Reverse back"],
    a:2,
    why:"Don't freeze and don't swerve: steady the car, bleed speed, and merge back into a real lane at the first safe gap — sudden moves from a neutral island surprise everyone around you.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk34", cat:"parking", form:"recall", concept:"hill-parking-wheels",
    q:"Parking on a hill with NO curb, wheels should point:",
    choices:["Straight ahead", "Uphill always", "Toward the edge of the road — so a runaway rolls off the pavement, not into traffic", "Downhill always"],
    a:2,
    why:"With no curb to catch a rolling car, aim the wheels at the road's edge: a brake failure then beaches the car off the pavement instead of launching it into the travel lane.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk35", cat:"parking", form:"what-next", concept:"hill-parking-wheels",
    q:"Parked uphill against a curb, you return to find the car resting a foot off the curb. What next?",
    choices:["Leave it — close enough", "Get in, brake on, restart, and snug a tire back against the curb: the curb only catches the car if a wheel actually touches it", "Push it by hand", "Deflate a tire to wedge it"],
    a:1,
    why:"Reset the curb catch: climb in with your foot hard on the brake, restart, and ease a tire back to touching — a foot of daylight means the curb trick isn't set.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk36", cat:"parking", form:"recall", concept:"illegal-parking",
    q:"Parking within 15 feet of a fire hydrant is:",
    choices:["Legal at night", "Legal for 5 minutes", "Legal with hazards on", "Illegal at all times — hydrants need working room around the clock"],
    a:3,
    why:"Fires ignore clocks: the hydrant clear zone applies around the clock, every hour of every day, so nights, minutes, and hazard lights change nothing.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"pk37", cat:"parking", form:"what-next", concept:"illegal-parking",
    q:"You spot your car being ticketed in front of a driveway you 'barely blocked.' What next?",
    choices:["Drive off before they finish", "Accept it and move: blocking any part of a driveway is the violation — inches don't matter — so relocate without arguing", "Argue the measurement", "Pay someone to watch the car"],
    a:1,
    why:"A driveway needs its full mouth: even a bumper-tip over the cut blocks turning cars, so the ticket stands — move the car and take the lesson.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw69", cat:"row", form:"recall", concept:"merge-priority",
    q:"On the ramp, who must adjust for the merge?",
    choices:["Highway traffic must always move over", "Nobody — merges are automatic", "You, the merger: match speed and take a clean gap — highway traffic holds its lane", "The fastest car wins"],
    a:2,
    why:"The ramp is the adjustment zone: your job is to match highway speed and slip into a real gap, because traffic already rolling holds its lane and its right of way.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw70", cat:"row", form:"what-next", concept:"merge-priority",
    q:"Your ramp is ending and the only gap is two car lengths at 65 mph. What next?",
    choices:["Take the shoulder to the next gap: a two-length slot at speed is no gap at all — ride the shoulder briefly rather than force a merge", "Force in — they'll brake", "Stop at the taper", "Cut across the gore"],
    a:0,
    why:"Borrow the shoulder to reach a real gap: squeezing a two-length slot at highway speed forces emergency braking behind you, while the shoulder costs nothing but pride.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg98", cat:"signs", form:"recall", concept:"school-zone-sign", signId:"schoolZone",
    q:"This five-sided fluorescent sign tells you:",
    choices:["A park is near", "A hospital zone", "A school zone or crossing is ahead — slow to the posted school speed and watch for children", "A detour"],
    a:2,
    why:"Pentagon plus yellow-green equals school: drop to the posted school speed early, scan both sidewalks, and expect small pedestrians to move unpredictably.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sg99", cat:"signs", form:"what-next", concept:"school-zone-sign", signId:"schoolZone",
    q:"Just past this sign, a crossing guard steps into the road with a stop paddle. What next?",
    choices:["Slow and wave", "Pass if no kids show", "Stop behind the line like any stop signal", "Stop well back and wait for the guard's wave: the paddle is a legal stop command, and children follow seconds behind"],
    a:3,
    why:"The paddle is law, not advice: stop well back, hold until the guard waves you through, and expect children trailing the guard by seconds.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf67", cat:"safety", form:"recall", concept:"seat-belt-law",
    q:"In a crash at 30 mph, an unbelted rear passenger becomes:",
    choices:["A projectile striking front occupants with tons of force — belts are required in every seat", "Safe if they brace", "Protected by the front seats", "Safer than belted drivers"],
    a:0,
    why:"Crash physics multiplies body weight into tons of flying force: the unbelted rear rider slams the people in front, which is why belts are required in every seat, not just the front.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"sf68", cat:"safety", form:"what-next", concept:"seat-belt-law",
    q:"Your passenger refuses the belt for a 'short trip.' What next?",
    choices:["Drive — their choice", "Buckle up yourself and refuse to move until their belt clicks too: most crashes happen near home, and an unbelted body becomes the driver's hazard", "Let them sit in back unbelted", "Drive slower to compensate"],
    a:1,
    why:"Don't roll until everyone clicks: most crashes happen minutes from home, and an unbelted passenger endangers the driver too — the car stays parked until the belt clicks.",
    sourceId:"us-dmv-handbooks-composite" },
  { id:"rw71", cat:"row", form:"what-next", concept:"left-on-red",
    q:"Stopped at a red on a one-way, about to turn left onto another one-way, a pedestrian steps into your target lane. What next?",
    choices:["Turn behind them quickly", "Wait: left-on-red still yields to every pedestrian — the maneuver is a privilege, not a right", "Honk them along", "Turn into the far lane"],
    a:1,
    why:"Left-on-red borrows the right-on-red rules: full stop, then yield to everything — pedestrians first — because the red never grants priority, only permission to go when clear.",
    sourceId:"us-dmv-handbooks-composite" },

  /* ---- Visual-form variants for sign concepts: transfer needs 2+ FORMS, so a
     second recall item adds nothing. Each is grounded in the rule its concept's
     existing question already states, so no new factual claim is introduced. ---- */
{ id:"tx100", cat:"signs", form:"diagram", concept:"stop-sign-shape", signId:"stop",
    q:"Approaching a junction you see the sign drawn above, its face turned away from you at an angle so the words are unreadable, and its reverse is visible on the far post. Snow is packed into the lettering. What still identifies it?",
    choices:["The red colour, which no other sign uses", "The eight-sided shape, which no other sign shares", "Its height above the roadway", "The white border around the edge"],
    a:1,
    why:"The octagon is unique to STOP, so the shape alone carries the meaning when the words cannot be read — turned away, snow-covered, or seen from behind. Reading it by colour fails on the many other red signs; height and border are not part of the sign's identity.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx101", cat:"signs", form:"sign-combo", concept:"stop-sign-shape",
    signIds:["stop", "yield"],
    q:"These two signs stand on the same approach, one behind the other. Which statement about their shapes is correct?",
    choices:["Both are triangles, differing only in colour", "The stop sign is the only eight-sided sign; the yield sign is the only downward-pointing triangle", "Both are rectangles with different wording", "The yield sign is eight-sided and the stop sign is a triangle"],
    a:1,
    why:"Shape is the first thing a driver reads. The octagon belongs to STOP alone and the inverted triangle to YIELD alone, which is why both remain identifiable when dirty, snow-covered or seen from an angle.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx102", cat:"signs", form:"diagram", concept:"stop-sign-response", signId:"stop",
    q:"You reach the sign drawn above, the junction is completely empty, and you can see for a long distance in both directions. What is required?",
    choices:["Slow to a walking pace and continue", "Stop only if another vehicle is approaching", "Come to a complete stop, then proceed when clear", "Yield, then continue without stopping if nothing is coming"],
    a:2,
    why:"A stop sign requires a full stop with the wheels no longer turning, at the line, crosswalk or before entering the junction — the emptiness of the junction changes nothing. Slowing is not stopping, and treating an empty junction as a reason to skip the stop is the single most common way this sign is failed.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx103", cat:"signs", form:"scenario", concept:"stop-sign-response", signId:"stop",
    q:"At a four-way stop you arrive first, but a car on your left arrives a moment later and edges forward as if to go. What do you do?",
    choices:["Wave them through, since they are already moving", "Proceed, because you arrived first and hold the priority", "Stop completely, then proceed only when it is genuinely safe — priority does not remove the duty to avoid a collision", "Sound your horn and go, since the priority is yours"],
    a:2,
    why:"Arriving first gives you the order of proceeding, but a stop sign still requires a full stop, and holding the priority never removes your obligation to avoid a crash. Waving a driver through a junction creates confusion for everyone else, and asserting priority into a moving car converts a right into a collision.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx104", cat:"signs", form:"diagram", concept:"yield-sign-meaning", signId:"yield",
    q:"You approach the sign above at a junction where the cross traffic is light but continuous, and there is a clear gap. What does the sign require of you?",
    choices:["A complete stop before entering, every time", "Slow down, give way to cross traffic and pedestrians, and continue without stopping if the way is genuinely clear", "Maintain your speed, because you have priority over turning traffic", "Stop only if a vehicle is physically in the junction"],
    a:1,
    why:"Yield means give the right of way and be ready to stop, not necessarily stop. A clear gap lets you continue, which is exactly what separates this sign from a stop sign; requiring a full stop every time treats it as a stop sign, and keeping full speed discards the duty to give way.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx105", cat:"signs", form:"lane-choice", concept:"yield-sign-meaning", signId:"yield",
    q:"You are on a slip road joining a busy road, and the sign above stands at the end of the merge. Traffic on the main road is steady and you have not yet found a gap. What is the correct action?",
    choices:["Accelerate hard and merge, forcing a gap in the traffic", "Stop at the end of the slip road and wait for the road to empty", "Adjust your speed to match the traffic and merge into a genuine gap, stopping only if you truly cannot join safely", "Continue at your current speed and let main-road traffic avoid you"],
    a:2,
    why:"The duty to give way sits with the driver joining, so you match the speed of the traffic and take a real gap, using the slip road's whole length. Forcing a merge makes someone else brake for you, waiting for the road to be empty misunderstands a give-way as a stop, and holding speed leaves main-road traffic to solve a problem that is yours.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx106", cat:"signs", form:"diagram", concept:"no-u-turn-sign", signId:"noUturn",
    q:"You have overshot your turning and see the sign above on the central reservation. There is no other traffic at all. What does the sign mean?",
    choices:["U-turns are banned here, whatever the traffic conditions", "U-turns are permitted when the road is clear of traffic", "Only large vehicles are prohibited from turning", "A U-turn is allowed if you can complete it in one movement"],
    a:0,
    why:"A prohibition sign is absolute while it applies and says nothing about traffic conditions — an empty road does not lift it. The permission it withholds does not return because the move happens to be convenient or easy; you continue to a place where a U-turn is lawful.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx107", cat:"signs", form:"sign-combo", concept:"no-u-turn-sign",
    signIds:["noUturn", "noLeftTurn"],
    q:"Both signs are mounted together on the same post at a junction. What do they prohibit?",
    choices:["Left turns only", "U-turns only", "Both left turns and U-turns at this junction", "Neither — the pair cancels out and both moves are permitted"],
    a:2,
    why:"Signs on one post apply together, and each prohibition stands on its own; the pair narrows what you may do rather than cancelling. Reading only the larger or lower plate leaves a banned movement that the other plate was placed there to prohibit.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx108", cat:"signs", form:"scenario", concept:"slippery-road-sign", signId:"slippery",
    q:"You pass the sign above as light rain begins after a long dry spell, and the road surface looks unchanged. What should you change?",
    choices:["Nothing — the sign is a permanent warning for winter ice", "Reduce speed and avoid sudden braking or steering, because oil build-up makes a first rain unusually slick", "Increase speed to get off the affected stretch quickly", "Use your high beams so you can see the surface better"],
    a:1,
    why:"A slippery-road warning is about the surface, not the season. Oil and rubber accumulated through dry weather lift into a film in the first rain, so the road is at its most treacherous precisely when it looks least changed — which is why the response is gentler inputs rather than speed or more light.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx109", cat:"signs", form:"what-next", concept:"slippery-road-sign", signId:"slippery",
    q:"You are crossing a bridge carrying the sign above, in freezing conditions, when the rear of your car starts to slide. What is the correct sequence?",
    choices:["Brake hard, then steer against the slide", "Ease off the accelerator and steer in the direction the rear is sliding, then correct gently once grip returns", "Accelerate to pull the car straight", "Keep the steering still and brake progressively to a stop"],
    a:1,
    why:"Bridges freeze first because cold air reaches the deck from below. Removing the cause — the accelerator — and steering where the rear is going lets the tyres regain grip before you make a further correction; braking hard or holding the wheel still locks in the slide, and accelerating adds the force that caused it.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx110", cat:"signs", form:"diagram", concept:"two-way-traffic-sign", signId:"twoWayTraffic",
    q:"You have been driving on a divided road and pass the sign above at a break in the central reservation. What has changed?",
    choices:["A one-way section begins, so you may use the whole width", "Opposing traffic will now be in the lane beside you, so keep right and pass only where it is legal and clear", "The road becomes a passing zone for its whole length", "Two lanes in your direction begin"],
    a:1,
    why:"The opposing arrows announce that oncoming traffic returns to the lane beside you, so the lane you occupy is no longer protected by a divider. That makes position and passing discipline matter again; reading it as a one-way or an automatic passing zone removes the very caution the sign exists to restore.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx111", cat:"signs", form:"photo", concept:"two-way-traffic-sign", signId:"twoWayTraffic",
    q:"PHOTO: a two-lane road with no central divider, the sign above on the right verge just behind you. Ahead, a slow tractor occupies your lane and the oncoming lane is empty as far as a slight crest.",
    choices:["Pass now, while the oncoming lane is visibly clear", "Do not pass — the crest hides oncoming traffic, and this sign has just warned that opposing traffic shares this road", "Pass slowly, staying ready to pull back in", "Follow closely and pass immediately after the crest"],
    a:1,
    why:"The empty lane is empty only as far as you can see, and the crest is exactly where that certainty ends. The sign has just told you oncoming traffic uses that lane, so an overtake begun on an assumption rather than a clear sightline is the manoeuvre the sign was placed to discourage.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx112", cat:"signs", form:"scenario", concept:"work-zone-authority", signId:"flagger",
    q:"In a work zone a flagger signals you to stop while the traffic signal beside them shows green. What do you do?",
    choices:["Proceed, because a green signal outranks a person on foot", "Stop, because the flagger is directing traffic and their signal must be obeyed", "Proceed slowly, treating the flagger's signal as advice", "Wait for the signal to change before deciding"],
    a:1,
    why:"A flagger is authorised to direct traffic through the work zone, and their instruction governs the movement in front of them — a signal head cannot see the obstruction that made them raise a hand. Treating a green light as outranking a person directing traffic is how drivers end up in a closed lane.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx113", cat:"signs", form:"what-next", concept:"work-zone-authority", signId:"flagger",
    q:"A flagger waves you forward into a work zone, then a worker steps into your lane ahead carrying equipment. What is the correct sequence?",
    choices:["Sound your horn and hold your line, since you were waved through", "Continue at the flagger's pace and pass the worker closely", "Proceed at a speed that lets you stop, and stop for the worker in the lane — the flagger's signal is permission to enter, not a guarantee the lane is clear", "Brake hard and reverse out of the zone"],
    a:2,
    why:"A flagger's wave admits you to the zone; it cannot promise that the lane stays clear of people working in it. A work zone is a place where the unexpected is expected, so the only speed that works is one from which you can stop — and reversing out of a live zone creates a second hazard.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx114", cat:"speed", form:"scenario", concept:"work-zone-speed", signId:"workZone",
    q:"You pass a work-zone speed limit sign on a road where no workers are visible and no equipment is in your lane. What applies?",
    choices:["The normal limit, since no one is working", "The posted work-zone limit, which applies whether or not workers are visible — and fines are often doubled", "The work-zone limit only while a flagger is present", "The normal limit once you have passed the first cone"],
    a:1,
    why:"A work-zone limit is an enforceable regulation that stands for the zone as posted, not for the moments when a worker happens to be in view — people and equipment can be just beyond a crest or a parked machine. Treating visibility as the trigger is how drivers meet a worker who stepped out a second earlier.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx115", cat:"speed", form:"diagram", concept:"work-zone-speed", signId:"workZone",
    q:"In the work zone above, the lane narrows and your lane's traffic is merging while a queue of vehicles builds behind you. What is the safest response?",
    choices:["Maintain the work-zone limit and merge in turn where the lane closes", "Speed up to clear the zone before the queue grows", "Move onto the shoulder to let others past", "Stop in the lane and wait for the merge to finish"],
    a:0,
    why:"The limit is the ceiling and merging in turn is the orderly way through a narrowing lane. Exceeding the limit to escape a queue trades a short delay for the exact collision the zone was coned off to prevent, and stopping in a live lane or using the shoulder creates hazards of its own.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx116", cat:"signs", form:"scenario", concept:"school-zone-sign", signId:"schoolZone",
    q:"You pass the sign above outside school hours, and the flashing beacons it mentions are not lit. What should you do?",
    choices:["Ignore the sign, since the beacons are off", "Maintain the normal limit and treat the area as ordinary road", "Keep to the posted school-zone limit where the sign states one, and stay alert for children in any case — signs like this mark an area, not a timetable", "Sound your horn to warn anyone nearby"],
    a:2,
    why:"A school-zone sign marks an area where children are likely, and children appear outside lesson times too. Where the sign carries a limit, the plate states when it applies; regardless, the reason for caution — children who judge speed poorly and appear from between parked cars — has not gone away because the beacons are dark.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx117", cat:"signs", form:"photo", concept:"school-zone-sign", signId:"schoolZone",
    q:"PHOTO: a school-zone sign on a pole, a crossing guard's empty post, and two children on bicycles on the pavement ahead, one of them wobbling towards the kerb.",
    choices:["Hold your speed — they are on the pavement and the crossing is unattended", "Slow down and move away from the kerb where you can, because a wobbling child cyclist may come into the road", "Sound your horn so they know you are there and continue", "Accelerate past them quickly to reduce the time alongside"],
    a:1,
    why:"An unattended crossing and an empty guard post remove the person who would normally stop the children, not the reason to expect them. A wobble is the visible sign of a rider who may not hold their line, so the response is speed that lets you stop plus room to spare; horn and speed both assume the rider can react correctly to you.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx118", cat:"signs", form:"diagram", concept:"signal-ahead-sign", signId:"signalAhead",
    q:"The sign above stands on a bend where the traffic signals themselves are hidden until you are almost on them. What is the sign there to do?",
    choices:["Tell you the colour of the light ahead", "Warn you that signals are ahead, so you can slow and be ready rather than braking suddenly when they appear", "Mark the point at which the signal becomes enforceable", "Replace the signals where they cannot be seen"],
    a:1,
    why:"A warning sign describes a hazard, it does not report the state of it, so this one never tells you which light you will meet. Its purpose is preparation: settling your speed and position before the signals come into view, which is exactly what a bend hiding the junction makes necessary.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx119", cat:"signs", form:"what-next", concept:"signal-ahead-sign", signId:"signalAhead",
    q:"You pass the sign above and reach the signals as they change from green to amber. You are close enough that stopping would mean braking very hard. What is the correct sequence?",
    choices:["Accelerate to clear the junction before red", "Brake hard immediately, whatever is behind you", "Proceed through if you are genuinely too close to stop safely, otherwise stop — an amber is a warning to stop unless stopping cannot be done safely", "Stop in the junction once the light turns red"],
    a:2,
    why:"Amber means stop unless you are so close that stopping cannot be done safely, which is why the warning sign upstream matters. Accelerating converts a warning into a race with the red, hard braking ignores the vehicle behind, and stopping once inside the junction blocks the crossing it was meant to clear.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx120", cat:"signs", form:"lane-choice", concept:"no-parking-sign", signId:"noParking",
    q:"The sign above stands on the kerb where you had intended to leave your car for a few minutes while you collect a parcel. What is permitted?",
    choices:["Parking for up to five minutes with hazard lights on", "No parking at this point — you may stop briefly to load or unload only if the sign does not prohibit stopping too", "Parking at any time, since the sign applies only to commercial vehicles", "Parking facing the direction of traffic"],
    a:1,
    why:"A no-parking sign controls leaving the vehicle standing there; whether you may stop at all depends on whether the sign also prohibits stopping, which is a stronger restriction. Thinking in terms of a grace period invents a rule the sign does not contain, and hazard lights do not create a right to park.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx121", cat:"signs", form:"scenario", concept:"no-parking-sign", signId:"noParking",
    q:"You park where the sign above allows it, then find your car is blocking a driveway you had not noticed. What matters?",
    choices:["Nothing — the parking sign is the only rule that applies", "You must move the car, because blocking a driveway obstructs access regardless of what the parking sign permits", "Only if the householder complains while you are present", "Nothing, if you leave the car for less than ten minutes"],
    a:1,
    why:"A permitted parking place does not licence obstructing access — that is a separate restriction and it applies whatever the sign on the kerb says. Waiting to be asked, or relying on how briefly you left the car, both put the judgement in the wrong hands.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx122", cat:"signs", form:"diagram", concept:"railroad-crossing-sign", signId:"railCrossing",
    q:"You approach the sign above at a crossing where the gates are raised and no train is in sight. What does the sign alone tell you?",
    choices:["That a train is approaching", "That you are at a rail crossing and must be prepared to stop — the absence of a train in view is not the information the sign carries", "That the crossing is out of use", "That you may cross without reducing speed"],
    a:1,
    why:"The sign identifies the crossing; it does not report whether a train is coming. Trains approach far faster than they appear to and can hide the crossing's own signals, which is why the sign asks for preparation rather than supplying the answer. Reading a raised gate as permanent permission is how drivers arrive at a crossing they cannot stop for.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx123", cat:"signs", form:"what-next", concept:"railroad-crossing-sign", signId:"railCrossing",
    q:"At a crossing with the sign above, the lights begin to flash and the gates are still up. Traffic ahead of you has stopped. What is the correct sequence?",
    choices:["Drive round the stopped traffic and cross before the gates lower", "Stop before the crossing, wait for the gates to lower and rise and the lights to stop flashing, then cross", "Continue across if you can reach the far side before the gates descend", "Reverse away from the crossing to find another route"],
    a:1,
    why:"Flashing lights mean a train is coming, and the gates come down after them precisely because the warning has to arrive before the barrier. Waiting for the lights to stop gives you the all-clear; beating the gates or driving round stopped traffic puts you on the track at the moment a train arrives, which is a collision no braking can avoid.",
    sourceId:"us-dmv-handbooks-composite" },


  /* ---- Batch 2: a SECOND FORM for the remaining thin concepts. transferCeiling
     needs >=2 questions AND >=2 forms, so one question in a different form
     unlocks transfer. Each is grounded in the rule its concept's existing
     question already states, so no new factual claim is introduced. ---- */
{ id:"tx200", cat:"signs", form:"diagram", concept:"wrong-way-sign", signId:"wrongWay",
    q:"You are on an off-ramp that has just taken you onto a road running against the traffic you have been following. The sign above faces you and the carriageway is completely empty. What is correct?",
    choices:["Continue — the road is empty, so there is no risk", "Drive on, but only in the outer lane until you find a turning point", "Stop at once, get out and walk back to check which way the traffic flows, then turn around safely", "Follow the wrong-way sign until the road rejoins the motorway"],
    a:2,
    why:"An empty carriageway does not make a wrong-way entry safe — traffic is coming, and it is coming fast and from a direction you cannot see. The first move is to stop before you meet anything, then establish which way the traffic runs before turning around.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx201", cat:"signs", form:"scenario", concept:"speed-limit-sign", signId:"speedLimit",
    q:"The sign above sets 55 mph, and you are on a straight highway in heavy rain. What speed should you drive?",
    choices:["55 mph, because that is the posted limit", "A speed below the limit that suits the conditions — slow enough to stop within the distance you can see", "55 mph in the left lane and faster in the right", "Whatever the vehicle in front is doing"],
    a:1,
    why:"A posted limit is a maximum in ideal conditions, never a target. Rain cuts visibility and lengthens stopping distance, so the basic speed law requires a speed appropriate to what you can actually see, which here means below the number on the plate.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx202", cat:"signs", form:"diagram", concept:"work-zone-sign", signId:"workZone",
    q:"The sign above stands at the start of a work zone. Beyond it the road narrows to one lane, and a crew is on foot in the remaining lane. What does the sign require?",
    choices:["Nothing — orange signs are advisory", "It marks a temporary zone: slow down, follow the reduced limit, and be ready for workers and changing lanes", "The road is closed beyond the sign", "It applies only to trucks and trailers"],
    a:1,
    why:"Orange is reserved for temporary work zones, and it tells you the ordinary rules ahead are altered — narrowed lanes, reduced limits, workers on foot. Treating it as advisory ignores the whole reason the colour exists, which is to separate temporary conditions from permanent signage.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx203", cat:"signs", form:"recall", concept:"services-sign", signId:"hospital",
    q:"You need fuel and a rest stop, and you see the sign above. How should you read it?",
    choices:["It marks a hospital, and you should turn in for emergency care", "It is a blue services sign — it lists motorist facilities such as fuel, food and rest areas ahead", "It marks a scenic route worth photographing", "It means the road ahead is closed to through traffic"],
    a:1,
    why:"Blue square signs are the motorist-services system, and this one names the type of facility on the route ahead. Green is guidance and direction, brown is recreation, and red is prohibition — the colour family alone tells you which of those you are looking at.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx204", cat:"signs", form:"scenario", concept:"stop-ahead-sign", signId:"stopAhead",
    q:"You are approaching a junction where the STOP sign itself is hidden by a parked van, and the sign above warns you it is there. What is correct?",
    choices:["Ignore it — the stop sign is hidden, so it does not apply", "Slow now and prepare to make a full stop at the line, because the sign applies even where the stop sign cannot be seen", "Sound your horn to warn the van", "Carry on at a slow crawl without stopping"],
    a:2,
    why:"A stop-ahead warning is issued precisely because the sign itself cannot be seen, so ignoring it because the stop sign is obscured is exactly the situation it exists for. Slow early, then stop fully at the line, crosswalk or before the junction.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx205", cat:"signs", form:"what-next", concept:"soft-shoulder-sign", signId:"softShoulder",
    q:"Your front wheel has dropped onto the soft shoulder shown by the sign and the car is starting to drag towards the verge. What is the correct sequence?",
    choices:["Steer hard back onto the road immediately and accelerate", "Ease off the accelerator, hold the wheel steady, and allow the car to drift back onto the pavement at low speed", "Brake hard, then turn sharply toward the road", "Stop in the shoulder and call for assistance"],
    a:1,
    why:"A soft shoulder cannot carry a car at speed, so the wheel sinks and the car pulls toward the verge. Lifting off and letting the car settle back at low speed is the recovery; a sudden turn or brake makes the dig deeper and can spin the car.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx206", cat:"signs", form:"what-next", concept:"stale-green-light",
    q:"The light above has been green for a long time and the pedestrian signal beside it is counting down. What do you do?",
    choices:["Keep your speed and expect the light to hold", "Accelerate to clear the junction while it is still green", "Ease off, cover the brake, check your mirrors and be ready to stop", "Stop immediately, wherever you happen to be"],
    a:2,
    why:"A long-lit green with the pedestrian phase counting down is the classic setup for the light changing against you. Lifting off and covering the brake leaves you able to stop smoothly, whereas accelerating into a changing light removes the option to stop at all.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx207", cat:"signs", form:"diagram", concept:"traffic-signals",
    q:"The signals above show a steady amber. You are about 20 feet from the stop line and travelling at 30 mph. What is the correct response?",
    choices:["Stop immediately, however hard the braking", "Stop if you can do so safely; if you are too close to stop, continue through with care", "Accelerate so you clear before the red", "Stop in the middle of the junction"],
    a:1,
    why:"A steady amber warns that the signal is about to turn red, and the rule is deliberately conditional: stop if stopping is safe, and proceed only when it is not. It is a decision about the road, not an instruction to brake at any cost, and it is never a reason to accelerate.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx208", cat:"row", form:"scenario", concept:"uncontrolled-intersection-tie",
    q:"You reach an uncontrolled intersection at the same moment as a car on your right. Neither of you has a stop or yield sign. Who goes first?",
    choices:["Whoever is travelling faster", "Whoever reaches the middle first", "The car on your right — in the absence of signs, the driver on the right has priority", "You, because you are the one who stopped first at the kerb"],
    a:2,
    why:"With no signs to settle it, the tie is broken by a long-standing rule of thumb: priority goes to whoever is on your right. Speed, proximity to the middle and who slowed first are not the test, and treating them as such is how two drivers pick the same gap.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx209", cat:"row", form:"diagram", concept:"t-intersection-priority",
    q:"The road you are on ends at the T-junction shown. A car on the road ahead faces you and is stopped, apparently waiting to turn. What is correct?",
    choices:["The car ahead must wait until you turn, because it is on the main road", "You have priority because you are on the left", "Give way to the car on the right — you are approaching a T-junction and it is on the through road", "Both turn at the same time"],
    a:2,
    why:"At a T-junction the road that ends gives way, so the driver approaching from the side must give priority to traffic on the through road. The vehicle on the main road is not waiting for you; it is waiting for a safe opening, and taking that opening is what the junction is for.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx210", cat:"row", form:"lane-choice", concept:"turn-across-bike-lane",
    q:"You are in the right-hand lane and want to turn right across a bike lane that a cyclist is using. What is the correct sequence?",
    choices:["Move into the bike lane early and turn from it", "Signal, yield to the cyclist, check the blind spot over your right shoulder, then turn across", "Accelerate slightly so the cyclist falls back", "Sound your horn and turn through"],
    a:1,
    why:"Cyclists in the lane have priority, so the turn waits for them to clear. The blind-spot check over the right shoulder is the step that stops the turn becoming a right-hook, because a cyclist alongside you is invisible in a mirror and only shows up when you look over your shoulder.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx211", cat:"row", form:"what-next", concept:"stopped-emergency-vehicle",
    q:"A fire engine is stopped on the right shoulder with its lights flashing, and you are in the left lane in a 50 mph limit. What do you do?",
    choices:["Maintain speed and keep close to it for visibility", "Change lane away from it if that is safe; if you cannot, slow down well below the limit", "Stop behind it and wait", "Pull onto the shoulder behind it"],
    a:1,
    why:"Move-over laws require you to leave a lane away from a stopped emergency vehicle where it is safe to do so, and where it is not, they require you to slow well below the limit. The purpose is to keep the working shoulder clear for the responders and for whoever is stranded beside it.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx212", cat:"row", form:"scenario", concept:"roundabout-priority",
    q:"You are waiting at the give-way line of a roundabout. A car is already circulating on the far side, and another car is entering from the left. Who do you wait for?",
    choices:["Only the car on your left, which is nearest to you", "Only the car already circulating, because the other is not in the circle yet", "Both — every vehicle already in the circle has priority over you, whatever its entry point", "Neither, if the gap looks wide enough"],
    a:2,
    why:"Priority inside a roundabout belongs to everything already circulating, regardless of which entry a vehicle used. The later arrival from the opposite side does not outrank the car beside you, and a gap that looks wide enough is not a substitute for the one the rule requires.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx213", cat:"laws", form:"scenario", concept:"signalling-requirement",
    q:"You are about to turn left at an intersection, and there is a cyclist alongside you on your right. When must you signal?",
    choices:["Only if the cyclist looks back at you", "Before the turn, and check the blind spot over your shoulder before moving across their path", "After the turn, once you are clear", "Signals are optional when traffic is light"],
    a:1,
    why:"A signal tells other road users what you intend to do, so it has to come before the manoeuvre, not after it. Checking the shoulder blind spot before crossing a cyclist's path is the second half of the same obligation, because a signal does not make the cyclist visible.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx214", cat:"laws", form:"scenario", concept:"u-turn-legality",
    q:"There is no U-turn prohibition sign on your road, the junction ahead is clear, and you need to reverse direction. What must you be able to do?",
    choices:["Nothing, because no sign means no restriction", "You must be able to see clearly in both directions and complete the turn without obstructing or endangering traffic", "The U-turn is illegal in any residential area", "You may make the turn as long as you signal"],
    a:1,
    why:"Where no sign prohibits it, a U-turn is generally lawful, but the permission is conditional: you need a clear view both ways and must not obstruct or endanger anyone. Signalling alone does not create the right, and the absence of a sign does not remove the responsibility.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx215", cat:"laws", form:"diagram", concept:"solid-white-line-crossing",
    q:"A solid white line runs along the road as shown, with a broken white line beside it. Which movement is legal?",
    choices:["Cross the solid line to overtake a slow vehicle", "Cross the solid line to turn into a driveway", "Change lanes across the broken line, and do not cross the solid line except to turn or enter a driveway", "Cross either line freely when the road is empty"],
    a:2,
    why:"A solid white line marks the edge of the lane for the direction you are travelling: you may not cross it to pass, though you may cross it to turn off or enter a driveway. The broken line beside it is a lane boundary you may change across.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx216", cat:"laws", form:"scenario", concept:"hov-lane-use",
    q:"You are alone in your car and approach a lane marked for high-occupancy vehicles only. What applies?",
    choices:["You may use it briefly while passing slower traffic", "You may not use it while driving alone — the restriction is absolute while it applies", "You may use it if you switch on your hazards", "You may use it outside peak hours"],
    a:1,
    why:"An HOV restriction names the minimum occupancy, and a lone driver never qualifies for it. Moving into the lane briefly to pass, signalling a reason, or hoping the restriction has ended does not qualify you either, and the lane is enforced against exactly that shortcut.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx217", cat:"laws", form:"what-next", concept:"suspended-licence",
    q:"Your licence has been suspended and you have a valid passport. You need to travel tomorrow. What is the correct position?",
    choices:["A passport is enough, because it is not a driving licence", "Driving while suspended is an offence regardless of what you drive — do not drive, and use licensed transport", "Drive only if a passenger sits beside you", "Drive if the trip is under a mile"],
    a:1,
    why:"A suspension removes the privilege to drive; it does not narrow it to some classes of journey. Driving during a suspension is an offence whether you drive a car, a van or someone else's vehicle, so a licensed driver or a taxi is the only lawful way to travel.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx218", cat:"laws", form:"prioritisation", concept:"move-over",
    q:"A stationary vehicle with hazard lights on occupies the left lane ahead of you. What do you do?",
    choices:["Slow and move one lane to the right where it is safe, passing with a gap", "Stop behind it until its hazards are switched off", "Pass immediately in the same lane with your hazards on", "Use the shoulder to get past it"],
    a:0,
    why:"Move-over rules ask you to leave a lane where it is safe to do so and give a real gap, and a stationary vehicle with hazards on is the case they were written for. Stopping behind it, crowding past in-lane, or taking the shoulder all create a hazard rather than clearing one.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx219", cat:"speed", form:"diagram", concept:"speed-and-stopping-distance",
    q:"Two cars are identical, but the one in the rain ahead has a laden trailer. The gap between them is the same as in the dry car behind. What is the risk?",
    choices:["None — the gap is what matters, not the conditions", "The laden car in the wet needs a much larger gap, because the same gap that was safe in the dry will not be safe now", "The gap is too small for either car", "Only the car in front is at risk in the wet"],
    a:1,
    why:"Stopping distance is built from reaction time, braking distance, and the road surface under the tyres. Rain lengthens braking distance and a laden trailer adds its own weight and braking lag, so an unchanged gap that was acceptable in the dry is now the gap that closes a collision.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx220", cat:"speed", form:"scenario", concept:"stopping-distance-components",
    q:"A following car's driver is distracted for two seconds. Which part of stopping distance does that two seconds of distraction add to?",
    choices:["The braking distance, because the driver brakes later", "The reaction distance, because the time before the brakes are applied is longer", "Neither, since braking distance is fixed", "The road surface component only"],
    a:1,
    why:"Stopping distance has two halves. The first is how long it takes you to notice and react, which is where a distracted or surprised driver loses time, and the second is how long the vehicle takes to stop once the brakes are on, which the road and speed set.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx221", cat:"speed", form:"what-next", concept:"slow-driving-hazard",
    q:"You are following a slower vehicle in a lane where the limit is higher, and a gap appears in the faster lane beside you. What is the correct response?",
    choices:["Move over promptly into the gap to keep up with traffic", "Only move across if it is safe and clear, and never so close that you are forced to brake hard", "Tailgate the slower vehicle until it speeds up", "Move over and then accelerate to match the flow"],
    a:1,
    why:"Keeping pace is a courtesy, not a licence to change lanes unsafely. The move is made into a real gap, and the condition on it is that you can still stop if something appears in front — otherwise a quicker lane has simply replaced a slow car with a closing gap.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx222", cat:"speed", form:"scenario", concept:"truck-following-downgrade",
    q:"You are behind a loaded truck on a long downgrade, and the truck's brakes are heating. What is the safest way to follow?",
    choices:["Stay close behind so the truck knows you are there", "Leave a generous gap, stay out of its blind spot, and be ready for it to slow suddenly or need extra space to stop", "Pass on the inside to get ahead of it", "Match its speed exactly with no gap"],
    a:1,
    why:"A loaded vehicle on a descent needs far more braking capacity and more room to use it, and a truck's blind spots make its sides the worst place to be. The gap protects you from a vehicle that has to brake harder than expected, and staying out of the blind spot means you are seen.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx223", cat:"speed", form:"scenario", concept:"speed-limits",
    q:"You are on an unposted residential street where children are playing and cars are parked along both sides. Which speed is defensible?",
    choices:["30 mph, which feels appropriate for a neighbourhood", "25 mph, the default where the street is unposted, and appropriate to the conditions in any case", "40 mph, since the street is straight and clear ahead", "The speed of the parked cars"],
    a:1,
    why:"Where a street is unposted, the default residential limit applies in most states, and the conditions here call for less rather than more: children in the road and parked cars narrowing your view. The limit is a ceiling you should not be reaching on this street anyway.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx224", cat:"alcohol", form:"scenario", concept:"under-21-alcohol-limit",
    q:"You are 19 and a friend offers you a single sip of a drink at a party. What is the legal position?",
    choices:["It is fine, because a single sip cannot register", "Under-21 limits are near zero, and a single sip can be enough to put you over — the safe choice is to decline", "It is fine if you have not eaten", "It is fine if you do not drive afterwards"],
    a:1,
    why:"Under-21 limits sit near zero, often low enough that one sip of an alcoholic drink can register as a violation, which is why even some mouthwash can trip them. Declining is the only choice that cannot put your licence at risk on a technicality.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx225", cat:"alcohol", form:"diagram", concept:"standard-drink-equivalence",
    q:"The chart above shows how a standard drink is built up: a shot of spirit, a glass of wine, and a pint of beer each count as one. A driver has had one of each. How many standard drinks is that?",
    choices:["One, because they were all drunk at the same time", "Three — each of those is one standard drink", "Two — the pint counts for less than the others", "It cannot be estimated"],
    a:1,
    why:"Standard drinks are counted, not felt: a shot, a wine and a pint are each one, so that is three, and timing does not reduce it. Counting the glasses is the only way to know where you stand, and it is a step most impaired drivers never take.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx226", cat:"alcohol", form:"what-next", concept:"dui-penalties",
    q:"You have been convicted of a first DUI. What is the sequence of consequences to expect?",
    choices:["Suspension, heavy fines, mandatory alcohol education, and a large rise in insurance costs — with repeat offences adding jail and ignition interlocks", "A fine and nothing else, since a first offence is treated leniently", "A warning, provided you complete a course", "Nothing, if you did not cause a crash"],
    a:0,
    why:"A first conviction commonly means licence suspension, substantial fines and fees, mandatory classes, and insurance that costs a great deal more for years. Each later offence adds to that, including jail and an ignition interlock, and whether a crash occurred changes the charge, not whether the penalty is real.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx227", cat:"alcohol", form:"scenario", concept:"bac-limits",
    q:"An officer lawfully asks you to take a breath test and you decline, even though you are confident you are under the limit. What happens?",
    choices:["Nothing, because you were under the limit", "Your licence is suspended automatically under implied consent, often for longer than a first DWI would cause", "A small fine", "Points on your licence only"],
    a:1,
    why:"Implied consent makes the request itself the trigger, so refusing produces an automatic suspension that is frequently harsher than the penalty for the offence you would have faced. The test measures the offence; the refusal is punished separately and independently of the measurement.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx228", cat:"safety", form:"what-next", concept:"tyre-blowout",
    q:"Your front-right tyre blows out at speed. What is the correct sequence of actions?",
    choices:["Brake hard and immediately, then pull over", "Hold the wheel firmly, ease off the accelerator, let the car decelerate in a straight line, then move to the shoulder and stop", "Steer sharply to the left and stop in the left lane", "Accelerrate to reach the next exit"],
    a:1,
    why:"A blow-out usually leaves the car controllable if the wheel is held and the speed is allowed to fall gradually, which is what easing off does. Hard braking and sharp steering while the tyre is shredding is what breaks the car loose, and reaching the next exit is not worth the loss of control.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx229", cat:"safety", form:"what-next", concept:"stuck-accelerator",
    q:"Your foot has caught the accelerator and the car is accelerating. What do you do?",
    choices:["Keep braking with the other foot and reach for the keys while driving", "Brake firmly, shift into neutral, and if needed turn the key off — the engine can be stalled without the steering losing assistance", "Pull the handbrake immediately at speed", "Climb into the passenger seat"],
    a:1,
    why:"The pedal is under your foot, so the immediate action is braking, and then neutral or the ignition to stop the engine driving the wheels forward. A handbrake at speed can pull the car into a spin, and leaving the driver's seat gives up control of the steering at the worst moment.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx230", cat:"safety", form:"scenario", concept:"unattended-vehicle-damage",
    q:"You park on a street and return to find a long scratch along the driver's side. What is the correct response?",
    choices:["Drive away and note it later", "Photograph the damage, note the time and place, and report it — do not leave the scene in a way that suggests you were involved", "Confront every parked car on the street", "Move the car and say nothing"],
    a:1,
    why:"Damage you did not cause is still reported, and an accurate account of when and where you left the vehicle is what makes the difference between a claim and an accusation. Photographing it and reporting it in that order protects you; moving the car and staying silent leaves the record to say what it likes.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx231", cat:"safety", form:"prioritisation", concept:"texting-while-driving",
    q:"Your phone lights up with a message while you are driving. What is the priority order that keeps you safe?",
    choices:["Read it at the next red light", "Read it while stopped at a light, or not at all — eyes and hands stay on the road, because a light change can come at any moment", "Reply using voice control while keeping your eyes up", "Pull over in the middle of the lane to read it"],
    a:1,
    why:"Looking away from the road for even a few seconds moves you a long way at speed, and a red light is not a safe window because it can change while you are looking down. The only safe handling is to leave the phone alone, or to read it once you are properly stopped.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx232", cat:"safety", form:"scenario", concept:"truck-no-zones",
    q:"You are a car driver and a truck is alongside you in a stretch marked as a no-passing zone for trucks. What does the marking mean for you?",
    choices:["It bans you from passing the truck as well", "It restricts the truck from passing you — you may pass it if it is safe and legal to do so", "It bans overtaking in both directions", "It is a truck parking zone"],
    a:1,
    why:"A no-passing restriction for heavy vehicles is directed at the vehicle that would have to cross into oncoming traffic to get past. As the car driver you are not the vehicle being restricted, and where the view allows it you may still overtake lawfully and safely.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx233", cat:"safety", form:"what-next", concept:"tailgating-response",
    q:"The car behind you is sitting very close and flashes its lights. What do you do?",
    choices:["Speed up to open the gap", "Maintain a safe gap and your own speed — the lights grant you nothing and do not transfer the responsibility", "Brake sharply to teach them a lesson", "Move into their lane"],
    a:0,
    why:"Pressure from a following driver changes nothing about who is responsible for the gap, and reacting to it by speeding or braking hands that control to someone else. Holding a safe distance at a steady speed is what ends the pressure, because it removes their reason for it.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx234", cat:"vehicle", form:"recall", concept:"tyre-pressure-source",
    q:"Where should you find the correct tyre pressure for your car?",
    choices:["On the tyre sidewall, which shows the maximum the tyre can take", "On the placard in the driver's door jamb, or the owner's manual — the sidewall figure is a maximum, not the working pressure", "Whatever the tyre station recommends", "The same as the vehicle behind you"],
    a:1,
    why:"The working pressure is the one specified for the vehicle, and it is normally on the driver's door jamb placard or in the manual. The number moulded into the tyre wall is the maximum that tyre may be run at, which is a different figure and often higher.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx235", cat:"vehicle", form:"scenario", concept:"tyre-tread-test",
    q:"How can you check that a tyre's tread is adequate without a depth gauge?",
    choices:["Look at the sidewall markings", "Check that the tread blocks are still visible in the grooves, and that the wear bars in the tread have not been reached", "Press the tyre and see if it feels soft", "Run a finger along the sidewall"],
    a:1,
    why:"A penny or a worn tread block tells you the depth has gone, and the wear bars moulded into the grooves show the legal minimum in a glance. Sidewall markings, softness and sidewall texture say nothing about the contact patch that actually grips the road.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx236", cat:"vehicle", form:"what-next", concept:"steering-hand-position",
    q:"You have been driving for several hours and your hands are stiff. What should you do?",
    choices:["Grip the wheel harder to stay in control", "Relax your grip and reposition your hands, keeping control of the wheel with light hands and relaxed shoulders", "Rest your hands in your lap briefly", "Change hands every few minutes while driving"],
    a:1,
    why:"A death grip is tiring rather than safer, and it is what makes hands stiff and attention drift over a long drive. Light hands and relaxed shoulders keep the same control while reducing fatigue, and taking your hands off the wheel or swapping them mid-drive is a far worse trade than the fatigue you were managing.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx237", cat:"vehicle", form:"scenario", concept:"uphill-stop-in-traffic",
    q:"You are stopped in traffic on a hill and the car in front pulls away. What is the risk you must manage?",
    choices:["The car may roll backwards into the vehicle behind you", "The engine may overheat while stationary", "The brakes may fade from holding the car on a hill", "Your lights may not be visible from behind"],
    a:0,
    why:"On a hill a stationary car is held by the brake and the transmission, and when the car in front moves off that hold is released. Setting the handbrake and leaving the vehicle in gear covers the gap between the brake and the accelerator, which is when the rollback happens.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx238", cat:"vehicle", form:"recall", concept:"wiper-condition",
    q:"When should wipers be replaced?",
    choices:["Every two years, regardless of condition", "When they smear, chatter or leave streaks rather than clearing the glass — rubber perishes with age and use", "Only when they stop moving entirely", "When the washer fluid runs out"],
    a:1,
    why:"Wiper blades are consumable rubber, and they degrade with time and use even while they still sweep. The signs of a perished blade are streaking, smearing and chattering, none of which clear the glass properly, and the fix is a new blade rather than more fluid or a stiffened arm.",
    sourceId:"us-dmv-handbooks-composite" },


  /* ---- Batch 3: close the last thin concepts for the remaining thin concepts. transferCeiling
     needs >=2 questions AND >=2 forms, so one question in a different form
     unlocks transfer. Each is grounded in the rule its concept's existing
     question already states, so no new factual claim is introduced. ---- */
{ id:"tx300", cat:"signs", form:"scenario", concept:"services-sign", signId:"hospital",
    q:"You are looking for fuel and a rest stop, and the sign above points to one ahead. What should you take from it?",
    choices:["It names a hospital, so turn in if anyone is unwell", "It is the blue services sign — it tells you that motorist facilities are available ahead, so plan for a stop there", "It marks a scenic route worth driving for the view", "It means the road ahead is closed to through traffic"],
    a:1,
    why:"The blue square family is the motorist-services system, and this one announces the kind of facility ahead rather than directing you into a place. Green signs give direction and brown signs mark recreation, so the colour alone places it in the services category.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx301", cat:"vehicle", form:"what-next", concept:"tyre-pressure-source",
    q:"Your tyre placard gives 35 psi, but the sidewall of the tyre itself shows 40 psi. Which figure do you inflate to?",
    choices:["40 psi, because it is moulded into the tyre", "35 psi, the working pressure for the vehicle — the sidewall number is a maximum the tyre may be run at, not its working pressure", "Whichever is higher, for safety", "40 psi, but check it weekly"],
    a:1,
    why:"The figure moulded into the sidewall is the ceiling that particular tyre may be run at, which is often higher than the vehicle's working pressure. The number to use is the one specified for the car, on the door jamb or in the manual, and inflating to the higher of the two risks the tyre failing.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx302", cat:"vehicle", form:"scenario", concept:"wiper-condition",
    q:"Your wipers leave a smear across the screen in the rain and chatter on a dry day. What is the right response?",
    choices:["Add more washer fluid to cut through the smear", "Fit new blades — perished rubber sweeps but does not clear, and fluid cannot fix a blade that has lost its edge", "Wait for the weather to improve", "Replace the wiper arm's spring"],
    a:1,
    why:"A blade that smears and chatters has perished, and no amount of fluid or arm tension restores the rubber's edge. Replacing the blades is the fix, and waiting for better weather simply means driving with a smeared view for longer.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx303", cat:"markings", form:"diagram", concept:"solid-white-lane-line",
    q:"The road is marked as shown: a solid white line on your right with a broken white line to your left. What does each line permit?",
    choices:["The solid line on your right may be crossed to pass a slow vehicle; the broken line may be crossed to change lanes", "The solid line marks the edge of your lane and may be crossed only to turn off or enter a driveway; the broken line is a lane boundary you may change across", "Both lines mean you may not change lanes", "The solid line is a cycle lane boundary"],
    a:1,
    why:"A solid white line is the edge of the lane for your direction of travel: you may not cross it to overtake, though leaving the road to turn or to reach a property is permitted. The broken line beside it marks lanes you are free to move between.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx304", cat:"markings", form:"diagram", concept:"two-way-left-turn-lane",
    q:"The centre of the road is marked as shown — a single lane between broken lines, used for left turns in both directions. You are waiting in it for a gap. What is allowed?",
    choices:["Only one direction may use the lane at a time", "Both directions may use it to wait for a turn, passing each other nose-to-nose, then turning when a gap appears", "It is for through traffic only", "It may be used for a U-turn"],
    a:1,
    why:"This lane is deliberately shared: opposing traffic waits in it too, the two pass each other nose-to-nose, and each completes its turn when a gap appears. It is for waiting and turning, not for travelling along, which is why using it as a running lane is prohibited.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx305", cat:"markings", form:"scenario", concept:"stop-line-marking",
    q:"A stop line is painted across your lane, and a stop sign stands just beyond it. Where must you stop?",
    choices:["Anywhere before the intersection, as long as you are clear of the line", "At the stop line, or at the crosswalk if one is there, or before entering the intersection — whichever comes first", "Beyond the line but clear of the crosswalk", "Wherever the driver ahead stopped"],
    a:1,
    why:"The stop line, the crosswalk and the edge of the intersection mark successive places to come to a halt, and you stop at the earliest one that applies. Stopping short of all of them is a violation, and stopping beyond the line but inside the crosswalk is just as wrong.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx306", cat:"markings", form:"lane-choice", concept:"lane-arrow-marking",
    q:"Your lane is marked with a left-turn arrow only, and you need to go straight ahead. What do you do?",
    choices:["Move across into the straight-ahead lane, signalling and only if it is safe", "Turn left and rejoin the route afterwards, since the arrow is a restriction you cannot cross", "Ignore the arrow — it is only a suggestion", "Stop and wait for a police officer to direct you"],
    a:1,
    why:"A lane arrow assigns that lane to the movement it shows, so a left-turn-only lane is not a lane for going straight. Changing to a lane that serves your destination is the normal way to handle it, and the arrow is an instruction rather than advice.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx307", cat:"signs", form:"scenario", concept:"sign-combination",
    signIds:["stop", "oneWay"],
    q:"You are approaching a junction where a stop sign faces you and, on the far side, a one-way arrow points to your right. What is the correct reading?",
    choices:["The stop applies to the one-way street, so you must stop before turning right", "The stop sign binds you at the junction you are approaching; the one-way arrow governs the street beyond it, which flows only to the right", "The one-way arrow cancels the stop sign", "You may turn right without stopping"],
    a:1,
    why:"Each sign addresses the road it faces: the stop sign governs your approach and the arrow describes the traffic flow past the junction. Reading one as overriding the other inverts both, because the junction you must stop at and the street beyond it are governed separately.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx308", cat:"signs", form:"recall", concept:"sign-combo-recognition",
    signIds:["yield", "pedCrossing"],
    q:"A triangular give-way sign carries a small plate beneath it showing a person walking. What does the combination require of you?",
    choices:["Yield to cross traffic only; the plate is decorative", "Give way to pedestrians in the crossing ahead, stopping if necessary, exactly as you would for cross traffic", "Stop for a fixed period before proceeding", "Nothing — the plate is an older sign that has been withdrawn"],
    a:1,
    why:"A supplemental plate narrows the scope of the sign above it. Here the people in the crossing are explicitly part of what you must give way to, so a pedestrian stepping out is a full reason to stop rather than something to weigh against the traffic.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx309", cat:"signs", form:"recall", concept:"sign-color",
    signIds:["doNotEnter", "wrongWay"],
    q:"Two signs on the same post are both red and white: one is a solid red circle with a white bar, the other shows a red arrow crossed by a slash. What does each prohibit?",
    choices:["Both prohibit the same movement", "The white bar bars entry from your direction; the slashed arrow warns you are travelling the wrong way", "The white bar warns you are in the wrong lane; the slash bars entry", "Both are warnings rather than orders"],
    a:1,
    why:"A solid disc with a white bar closes the street to vehicles coming from the side it faces, while a crossed arrow is an advance warning that the direction of travel is wrong. Both belong to the prohibition family, so the shape and symbol — not the shared colour — tell them apart.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx310", cat:"signs", form:"recall", concept:"sign-shape",
    signIds:["stop", "yield"],
    q:"One sign is a red octagon, the other a red-bordered inverted triangle. Which is which, and what is the difference in what they require?",
    choices:["The triangle is stop and the octagon is yield; both mean a full stop", "The octagon is stop and requires a complete halt; the triangle is give way and asks you to slow and yield, stopping only if needed", "Both are warnings about the road ahead", "The octagon means speed limit and the triangle means no entry"],
    a:1,
    why:"Shape separates the two orders before a word is read: the octagon is the only stop sign and demands the wheels stop, while the inverted triangle asks for a reduction in speed and the right of way, with a stop only if the way is not clear.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx311", cat:"row", form:"scenario", concept:"turn-priority",
    q:"You are at an intersection where a car on your right is waiting to turn, and no sign controls the junction. What is the correct action?",
    choices:["Proceed, because you are on the left and the junction is clear", "Give way to the vehicle on your right, and take the gap only once it has gone", "Proceed, because you have the higher priority road", "Sound your horn and proceed"],
    a:1,
    why:"Without signs, priority at a junction belongs to the driver on the right, and that is the whole of the tie-break. A clear junction on your own does not create priority, and the gap you take has to be one the other driver has already declined.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx312", cat:"laws", form:"diagram", concept:"work-zones", signId:"workZone",
    q:"You pass the sign above and the road ahead has a lower posted limit, narrowed lanes and a crew working on foot. What governs you here?",
    choices:["The normal limit, because the general rules resume once past the sign", "The temporary work-zone limit and signage, which govern you for the length of the zone — including the reduced limit and any lane changes they impose", "The limit of the road you are joining", "Whatever the traffic in front is doing"],
    a:1,
    why:"A work zone replaces the ordinary rules for its whole length with temporary ones: reduced limits, altered lanes, and instructions from the crew. The general limit resumes when the zone ends, not when you pass the first sign.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx313", cat:"safety", form:"scenario", concept:"tire-blowout",
    q:"A tyre blows out on the motorway and the car begins to pull to one side. What is the correct response?",
    choices:["Steer towards the side the car is pulling to, to compensate", "Hold the wheel firmly, ease off the accelerator, let it run straight while the speed falls, then move to the shoulder and stop", "Brake hard immediately and hold the brakes", "Switch on hazard lights and stop in the running lane"],
    a:1,
    why:"A blown tyre usually leaves the car steerable if the wheel is held and the speed is allowed to fall gently, which is what easing off does. Fighting the pull with opposite lock, braking hard while it is shredding, or stopping in a live lane are what turn a survivable blow-out into a crash.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx314", cat:"row", form:"what-next", concept:"two-way-left-turn",
    q:"You are waiting in a two-way left-turn lane and a gap opens in the oncoming direction. What do you do?",
    choices:["Wait for a gap in your own direction as well, because a turn needs both lanes clear", "Take the gap in the oncoming lane and turn, checking that the gap is genuinely long enough for your vehicle", "Edge into the oncoming lane first to wait", "Turn across the centre line instead"],
    a:1,
    why:"The turn is made into a gap in the oncoming lane, because that is where the traffic you are waiting for is going. The judgement required is whether the gap is long enough for your vehicle to clear it, not whether both directions happen to be free at once.",
    sourceId:"us-dmv-handbooks-composite" },
{ id:"tx315", cat:"laws", form:"scenario", concept:"move-over",
    q:"A stopped vehicle with hazard lights on is in the lane beside you. What does the move-over law require?",
    choices:["That you stop and wait for it to move off", "That you change lane away from it where that is safe, and otherwise slow well below the limit", "That you follow it closely until it moves", "That you use the shoulder to pass it"],
    a:1,
    why:"The law asks for a lane change away from a stopped emergency or stopped-vehicle hazard where it can be done safely, and for a substantial reduction in speed where it cannot. The purpose is to keep that space workable for the people in the stopped vehicle, not to make you wait behind it.",
    sourceId:"us-dmv-handbooks-composite" },

];

/* Quick self-check on load (dev aid): every question has a valid answer index. */
if (typeof window !== "undefined") {
  QUESTIONS.forEach(q => {
    if (!q.choices || q.a < 0 || q.a >= q.choices.length) console.error("Bad question:", q.id);
    if (!CATEGORIES[q.cat]) console.error("Bad category:", q.id, q.cat);
    if (q.signId && typeof SIGNS === "undefined" || q.signId && !SIGNS[q.signId]) console.error("Bad sign:", q.id, q.signId);
  });
}
